import React from "react";
import classNames from "classnames/bind";

export default function LuxFeedbackQuestionLabel({ questionConfig, className, as: Tag = "label" }) {
  if (!questionConfig) return null;
  return (
    <Tag className={classNames("lux-fb-q__label", className)}>
      {questionConfig.question}
      {questionConfig.mandatory === true && (
        <span className="lux-fb-q__required" title="Required" aria-label="required">
          *
        </span>
      )}
    </Tag>
  );
}
