import dateUtils from "_helpers/date.utils";
import {
  buildTeamHeatmap,
  getUtilizationTone,
} from "./plannerAnalytics.utils";
import {
  employeeIdsMatch,
  filterPlannerWorkItems,
  formatPlannerHours,
  getItemEndDate,
  getItemStartDate,
  classifyPlannerWorkItemType,
  getOverlappedMinutes,
  getPlannerDays,
  getWorkItemEmployeeId,
  normalizeWorkItemStatus,
} from "./planner.utils";
import { isPlannerLeaveOrHolidayItem } from "./plannerLeave.utils";
import { buildDayCapacityMapFromRow } from "./plannerAssignForm.utils";

function mergeDayBreakdown(existing, incoming) {
  const map = new Map();
  (existing || []).forEach((d) => map.set(d.dayKey, { ...d }));
  (incoming || []).forEach((d) => {
    const prev = map.get(d.dayKey);
    if (prev) {
      map.set(d.dayKey, { ...prev, minutes: prev.minutes + d.minutes });
    } else {
      map.set(d.dayKey, { ...d });
    }
  });
  return Array.from(map.values()).sort((a, b) => a.dayKey.localeCompare(b.dayKey));
}

function buildAssignmentDayBreakdown(item, days) {
  const start = getItemStartDate(item);
  if (!start) return [];
  const end = getItemEndDate(item, start);
  const breakdown = [];
  days.forEach((dayMoment) => {
    const minutes = getOverlappedMinutes(start, end, dayMoment);
    if (minutes <= 0) return;
    breakdown.push({
      dayKey: dayMoment.format("YYYY-MM-DD"),
      dateLabel: dayMoment.format("DD MMM"),
      weekday: dayMoment.format("ddd"),
      minutes,
      hoursLabel: formatPlannerHours(minutes),
    });
  });
  return breakdown;
}

function buildHorizonDateRangeLabel(dayBreakdown) {
  if (!dayBreakdown || dayBreakdown.length === 0) return "—";
  if (dayBreakdown.length === 1) {
    const d = dayBreakdown[0];
    return `${d.weekday} ${d.dateLabel}`;
  }
  const first = dayBreakdown[0];
  const last = dayBreakdown[dayBreakdown.length - 1];
  return `${first.dateLabel} – ${last.dateLabel}`;
}

export function buildPlannerAssignEmployeeContext({
  employee,
  workItems,
  startMoment,
  horizonWeeks,
  holidayItems,
  reduceForHolidays,
  filterOptions,
  leaveMap,
  capacityOverrides,
}) {
  if (!employee || employee.id == null) return null;

  const heatmap = buildTeamHeatmap({
    employees: [employee],
    workItems,
    startMoment,
    horizonWeeks,
    holidayItems,
    reduceForHolidays,
    filterOptions,
    leaveMap,
    capacityOverrides,
    showActuals: false,
  });

  const row = heatmap.rows && heatmap.rows[0];
  const days = getPlannerDays(startMoment.clone(), horizonWeeks);
  const filtered = filterPlannerWorkItems(workItems, filterOptions, employee.id);
  const assignmentMap = new Map();

  filtered.forEach((item) => {
    if (isPlannerLeaveOrHolidayItem(item)) return;
    if (!employeeIdsMatch(getWorkItemEmployeeId(item), employee.id)) return;
    const dayBreakdown = buildAssignmentDayBreakdown(item, days);
    if (dayBreakdown.length === 0) return;
    const minutes = dayBreakdown.reduce((s, d) => s + d.minutes, 0);
    const start = getItemStartDate(item);
    const end = start ? getItemEndDate(item, start) : null;
    const scheduleStart = start
      ? dateUtils.convertDateToMoment(start).format("DD MMM YYYY")
      : null;
    const scheduleEnd = end ? dateUtils.convertDateToMoment(end).format("DD MMM YYYY") : null;

    const existing = assignmentMap.get(item.id);
    if (existing) {
      existing.minutes += minutes;
      existing.dayBreakdown = mergeDayBreakdown(existing.dayBreakdown, dayBreakdown);
      existing.horizonDateLabel = buildHorizonDateRangeLabel(existing.dayBreakdown);
      existing.hoursLabel = formatPlannerHours(existing.minutes);
    } else {
      assignmentMap.set(item.id, {
        item,
        minutes,
        dayBreakdown,
        horizonDateLabel: buildHorizonDateRangeLabel(dayBreakdown),
        hoursLabel: formatPlannerHours(minutes),
        scheduleStart,
        scheduleEnd,
        scheduleRangeLabel:
          scheduleStart && scheduleEnd && scheduleStart !== scheduleEnd
            ? `${scheduleStart} – ${scheduleEnd}`
            : scheduleStart || scheduleEnd || null,
      });
    }
  });

  const assignments = Array.from(assignmentMap.values()).sort((a, b) => b.minutes - a.minutes);

  const statusCounts = {};
  assignments.forEach(({ item }) => {
    const st = normalizeWorkItemStatus(item.status) || "OTHER";
    statusCounts[st] = (statusCounts[st] || 0) + 1;
  });

  const projectMinutes = {};
  assignments.forEach(({ item, minutes }) => {
    const key = item.projectName || item.taskActCategory || item.name || "Other";
    projectMinutes[key] = (projectMinutes[key] || 0) + minutes;
  });

  const projects = Object.entries(projectMinutes)
    .map(([name, minutes]) => ({ name, minutes }))
    .sort((a, b) => b.minutes - a.minutes);

  const taskTypeMinutes = { billable: 0, nonBillable: 0, leaveHoliday: 0 };
  filtered.forEach((item) => {
    if (!employeeIdsMatch(getWorkItemEmployeeId(item), employee.id)) return;
    const dayBreakdown = buildAssignmentDayBreakdown(item, days);
    const minutes = dayBreakdown.reduce((s, d) => s + d.minutes, 0);
    if (minutes <= 0) return;
    const kind = classifyPlannerWorkItemType(item);
    taskTypeMinutes[kind] = (taskTypeMinutes[kind] || 0) + minutes;
  });

  const allocatedMinutes = row
    ? row.dayCells.reduce((s, c) => s + c.allocated, 0)
    : assignments.reduce((s, a) => s + a.minutes, 0);

  const capacityMinutes = row ? row.dayCells.reduce((s, c) => s + c.capacity, 0) : 0;
  const freeMinutes = row ? row.freeMinutes : Math.max(0, capacityMinutes - allocatedMinutes);
  const horizonUtilization = row
    ? row.horizonUtilization
    : capacityMinutes > 0
      ? Math.round((allocatedMinutes / capacityMinutes) * 100)
      : 0;

  return {
    employee,
    tone: row ? row.tone : getUtilizationTone(horizonUtilization),
    horizonUtilization,
    allocatedMinutes,
    capacityMinutes,
    freeMinutes,
    overbookedDays: row ? row.overbookedDays : 0,
    activeProjects: row ? row.activeProjects : projects.length,
    dailyLoad: row
      ? row.dayCells.map((c) => ({
          label: c.label,
          dateLabel: c.dateLabel,
          allocated: c.allocated,
          capacity: c.capacity,
          utilization: c.utilization,
          isOnLeave: c.isOnLeave,
        }))
      : [],
    statusCounts,
    projects,
    taskTypeMinutes,
    assignments,
    dayCapacityMap: buildDayCapacityMapFromRow(row),
    itemCount: assignments.length,
    allocatedLabel: formatPlannerHours(allocatedMinutes),
    capacityLabel: formatPlannerHours(capacityMinutes),
    freeLabel: formatPlannerHours(freeMinutes),
  };
}
