import React, { Component } from "react";
import { withRouter } from "react-router-dom";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isAiWorkIntelligenceEnabled } from "config/ai-work-intelligence.config";
import {
  AI_DOMAIN_PAGE_META,
  AI_DOMAIN_ROUTE_AGENT_MAP,
  getAiWorkIntelligenceShellPageTitle,
} from "config/ai-work-intelligence-nav.config";
import { canRunAgent, canViewAiWorkIntelligence } from "config/ai-work-intelligence-security.utils";
import { aiWorkIntelligenceService } from "_services/aiWorkIntelligence.service";
import AiLuxPage, { AiActionButton, AiLuxPanel } from "views/ai/components/AiLuxShared";
import { AiAgentDomainHero } from "views/ai/components/AiHitlSnapshotStrip";
import AgentRecommendationPanel from "views/ai/components/AgentRecommendationPanel";
import { AgentRunHistoryRegister } from "views/ai/components/AgentRegistryPanel";

const AI_AGENT_PAGE_ID_MAP = {
  "agent-wbs": "wbs-assistant",
  "agent-staff": "staffing-agent",
  "agent-pay": "payroll-readiness",
  "agent-ts": "timesheet-agent",
  "agent-risk": "risk-agent",
  "agent-exec": "executive-briefing",
};

class AIAgentDomainPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    agent: null,
    runs: [],
    recommendations: [],
    selectedRecommendationId: null,
    running: false,
    busyId: null,
  };

  componentDidMount() {
    this.loadData();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.location.pathname !== this.props.location.pathname) {
      this.loadData();
    }
  }

  getAgentId = () => {
    const { agentId, location } = this.props;
    if (agentId) {
      return agentId;
    }
    return AI_DOMAIN_ROUTE_AGENT_MAP[location.pathname] || null;
  };

  getActivePersona = () => {
    const personaCtx = this.props.personaContext || {};
    return personaCtx.activePersona || "EXECUTIVE";
  };

  loadData = async () => {
    const agentId = this.getAgentId();
    const persona = this.getActivePersona();
    if (!agentId) {
      this.setState({ loading: false, loadError: "Unknown AI workspace route." });
      return;
    }
    this.setState({ loading: true, loadError: null });
    try {
      const [agentResult, runsResult, recsResult] = await Promise.all([
        aiWorkIntelligenceService.getAgent(agentId),
        aiWorkIntelligenceService.listAgentRuns({ agentId, persona }),
        aiWorkIntelligenceService.listRecommendations({ agentId, persona }),
      ]);
      const recommendations = recsResult.payload || [];
      this.setState({
        loading: false,
        dataSource: agentResult.source,
        agent: agentResult.payload,
        runs: runsResult.payload || [],
        recommendations,
        selectedRecommendationId: recommendations[0] ? recommendations[0].id : null,
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load AI workspace.",
      });
    }
  };

  handleRun = async () => {
    const { agent } = this.state;
    if (!agent) {
      return;
    }
    const persona = this.getActivePersona();
    this.setState({ running: true, loadError: null });
    try {
      const result = await aiWorkIntelligenceService.runAgent(agent.id, { persona, scope: agent.domain });
      const recommendation = result.payload && result.payload.recommendation;
      if (recommendation) {
        this.setState({ selectedRecommendationId: recommendation.id });
      }
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to run agent." });
    } finally {
      this.setState({ running: false });
    }
  };

  handleDecide = async (recommendationId, decision, rationale) => {
    const persona = this.getActivePersona();
    this.setState({ busyId: recommendationId, loadError: null });
    try {
      await aiWorkIntelligenceService.decideRecommendation(recommendationId, decision, rationale, { persona });
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to record decision." });
    } finally {
      this.setState({ busyId: null });
    }
  };

  render() {
    if (!isAiWorkIntelligenceEnabled()) {
      return <PersonaAccessDenied title="AI workspace" message="AI work intelligence is not enabled for this organization." />;
    }
    const persona = this.getActivePersona();
    if (!canViewAiWorkIntelligence(persona)) {
      return <PersonaAccessDenied title="AI workspace" message="Your persona cannot access this AI workspace." />;
    }

    const agentId = this.getAgentId();
    const pageMeta = AI_DOMAIN_PAGE_META[agentId] || {
      tone: "violet",
      icon: "fe fe-cpu",
      eyebrow: "AI",
      titleLead: "Domain",
      titleAccent: "agent",
      lede: "Run domain agent with evidence-backed recommendations.",
    };
    const shellTitle = getAiWorkIntelligenceShellPageTitle(this.props.location.pathname);
    const { loading, loadError, dataSource, agent, runs, recommendations, selectedRecommendationId, running, busyId } = this.state;
    const canRun = agent && canRunAgent(persona, agent);

    return (
      <AiLuxPage
        pageMeta={pageMeta}
        pageId={AI_AGENT_PAGE_ID_MAP[agentId]}
        shellTitle={shellTitle}
        dataSource={dataSource}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        heroActions={
          <AiActionButton icon="fe fe-play" variant="primary" onClick={this.handleRun} disabled={!canRun || running}>
            {running ? "Running…" : "Run agent"}
          </AiActionButton>
        }
      >
        {loadError ? <p className="lux-ai-intel-error">{loadError}</p> : null}
        <AiAgentDomainHero agent={agent} loading={loading} />

        <div className="lux-ai-intel-layout lux-ai-intel-layout--single">
          <AiLuxPanel title="Recommendations" meta="Inspect evidence and record decisions" icon="fe fe-inbox" accent="indigo" featured>
            <AgentRecommendationPanel
              recommendations={recommendations}
              activePersona={persona}
              selectedRecommendationId={selectedRecommendationId}
              onSelectRecommendation={(id) => this.setState({ selectedRecommendationId: id })}
              onDecide={this.handleDecide}
              busyId={busyId}
              loading={loading}
            />
          </AiLuxPanel>
        </div>

        <AiLuxPanel title="Recent runs" meta="Execution history for this agent" icon="fe fe-clock" accent="emerald">
          <AgentRunHistoryRegister runs={runs} loading={loading} />
        </AiLuxPanel>
      </AiLuxPage>
    );
  }
}

export default withRouter(AIAgentDomainPage);
