/**
 * Merge helpers for invoice presentation.
 * Identity (addresses, bank, supplier, signatory) must come from the API /
 * Tracopus client {@code details_json} — not front-end hardcodes.
 */

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value == null) continue;
    if (typeof value === "string" && value.trim() === "") continue;
    if (Array.isArray(value) && value.length === 0) continue;
    return value;
  }
  return null;
}

function resolveAddress(source) {
  const fromSource = Array.isArray(source.address)
    ? source.address.filter(Boolean)
    : source.address
    ? [source.address]
    : [];
  return fromSource;
}

/** Merge API party with optional sparse override; no invented identities. */
export function mergeParty(party, fallback = {}) {
  const source = party || {};
  const base = fallback || {};
  const name = firstNonEmpty(source.name, base.name);
  const email = firstNonEmpty(source.email, source.emails && source.emails[0], base.email);
  const phone = firstNonEmpty(source.phone, source.phones && source.phones[0], base.phone);
  const address = resolveAddress(source).length
    ? resolveAddress(source)
    : resolveAddress(base);
  const emails =
    source.emails && source.emails.length
      ? source.emails
      : email
      ? [email]
      : base.emails || [];
  const phones =
    source.phones && source.phones.length
      ? source.phones
      : phone
      ? [phone]
      : base.phones || [];
  if (!name && !address.length && !emails.length && !phones.length) {
    return null;
  }
  return {
    name: name || null,
    parentCompany: firstNonEmpty(source.parentCompany, base.parentCompany),
    registration: firstNonEmpty(source.registration, source.registrationNumber, base.registration),
    address,
    emails,
    phones,
    hours: firstNonEmpty(source.hours, base.hours),
    website: firstNonEmpty(source.website, base.website),
    logo: firstNonEmpty(source.logo, base.logo),
    email: email || (emails && emails[0]) || null,
    phone: phone || (phones && phones[0]) || null,
  };
}

export function mergePayment(payment, fallback = {}) {
  const source = payment || {};
  const base = fallback || {};
  const merged = {
    method: firstNonEmpty(source.method, base.method) || "Bank transfer",
    pan: firstNonEmpty(source.pan, base.pan),
    gst: firstNonEmpty(source.gst, source.gstin, base.gst),
    lutArn: firstNonEmpty(source.lutArn, source.lut, base.lutArn),
    accountName: firstNonEmpty(source.accountName, source.accountHolder, base.accountName),
    accountNumber: firstNonEmpty(source.accountNumber, base.accountNumber),
    ifsc: firstNonEmpty(source.ifsc, source.ifscCode, base.ifsc),
    bank: firstNonEmpty(source.bank, source.bankName, base.bank),
    branch: firstNonEmpty(source.branch, base.branch),
    branchLocation: firstNonEmpty(source.branchLocation, source.branchAddress, base.branchLocation),
  };
  const hasUseful =
    merged.bank ||
    merged.accountNumber ||
    merged.ifsc ||
    merged.accountName ||
    merged.pan ||
    merged.gst;
  return hasUseful ? merged : null;
}

export function mergeSignatory(signatory, fallback = {}) {
  const source = signatory || {};
  const base = fallback || {};
  const name = firstNonEmpty(source.name, base.name);
  if (!name) {
    return null;
  }
  return {
    name,
    title: firstNonEmpty(source.title, base.title),
    image: firstNonEmpty(source.image, base.image),
  };
}
