import React from "react";
import Skeleton from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "./luxSkeleton.constants";

/** Inline skeleton for list/register count labels while loading. */
export default function LuxListCountSkeleton({ width = 72 }) {
  return (
    <Skeleton
      width={width}
      height={12}
      borderRadius={4}
      baseColor={LUX_SKELETON_THEME.baseColor}
      highlightColor={LUX_SKELETON_THEME.highlightColor}
    />
  );
}
