/**
 * F20-T5 — Sensitive field masking policy service.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import envconfig from "env.config";
import { normalizeMaskingPolicyRule } from "config/masking-policy.config";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ENTITY_TYPES } from "_constants/audit.constants";

import { apiErrorResult } from "config/mock-fallback.utils";

export const maskingPolicyService = {
  listRules,
  getRule,
  updatePersonaLevel,
};

const API_BASE = `${urlConfig.APPCONFIG_API_PATH}/masking-policies`;

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function listRules() {
  if (envconfig.USE_MASKING_POLICY_ADMIN_API === true) {
    try {
      const response = await axiosUtils.getWithParam(API_BASE, teamQuery());
      const rows = (response && response.payload) || response || [];
      return {
        payload: (Array.isArray(rows) ? rows : []).map(normalizeMaskingPolicyRule).filter(Boolean),
        source: "api",
      };
    } catch (e) {
      // fall through
    }
  }

  return apiErrorResult(null);
}

async function getRule(ruleId) {
  if (envconfig.USE_MASKING_POLICY_ADMIN_API === true) {
    try {
      const response = await axiosUtils.getWithParam(`${API_BASE}/${ruleId}`, teamQuery());
      const row = (response && response.payload) || response;
      return { payload: normalizeMaskingPolicyRule(row), source: "api" };
    } catch (e) {
      // fall through
    }
  }
  return apiErrorResult(null);
}

async function updatePersonaLevel(ruleId, persona, level) {
  if (envconfig.USE_MASKING_POLICY_ADMIN_API === true) {
    try {
      const response = await axiosUtils.patch(
        `${API_BASE}/${ruleId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
        { persona, level }
      );
      const row = (response && response.payload) || response;
      const result = { payload: normalizeMaskingPolicyRule(row), source: "api" };
      recordAuditEvent({
        actionType: "UPDATED",
        entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
        entityRef: `${result.payload && result.payload.name} · ${persona}`,
        metadata: {
          ruleId,
          persona,
          level,
          fieldKey: result.payload && result.payload.fieldKey,
        },
      });
      return result;
    } catch (e) {
      // fall through
    }
  }
  throw new Error("Unable to complete action via API.");

}
