const CHART_FONT = "Inter, system-ui, sans-serif";

function baseDonutOptions(labels, colors) {
  return {
    chart: { fontFamily: CHART_FONT, toolbar: { show: false } },
    labels,
    colors,
    legend: { show: false },
    dataLabels: { enabled: false },
    stroke: { width: 2, colors: ["#fff"] },
    plotOptions: {
      pie: {
        donut: {
          size: "72%",
          labels: {
            show: true,
            total: {
              show: true,
              label: "Total",
              fontSize: "11px",
              fontWeight: 700,
              color: "#64748b",
            },
          },
        },
      },
    },
  };
}

export function buildAccountTypeDonutChart(stat) {
  const mix = stat.typeMix || [];
  if (!mix.length) return null;
  return {
    series: mix.map((s) => s.count),
    options: baseDonutOptions(
      mix.map((s) => s.label),
      mix.map((s) => toneColor(s.tone))
    ),
  };
}

export function buildAccountSourceDonutChart(stat) {
  const mix = stat.sourceMix || [];
  if (!mix.length) return null;
  if (mix.length === 1 && mix[0].key === "MANUAL" && !stat.salesforceCount) return null;
  return {
    series: mix.map((s) => s.count),
    options: baseDonutOptions(
      mix.map((s) => s.label),
      mix.map((s) => toneColor(s.tone))
    ),
  };
}

export function buildAccountHealthDonutChart(stat) {
  const mix = stat.healthMix || [];
  if (!mix.length || stat.total === 0) return null;
  return {
    series: mix.map((s) => s.count),
    options: baseDonutOptions(
      mix.map((s) => s.label),
      mix.map((s) => toneColor(s.tone))
    ),
  };
}

export function buildAccountBillingDonutChart(stat) {
  const mix = stat.billingMix || [];
  if (!mix.length) return null;
  return {
    series: mix.map((s) => s.count),
    options: baseDonutOptions(
      mix.map((s) => s.label),
      mix.map((s) => toneColor(s.tone))
    ),
  };
}

export function buildAccountIssuesBarChart(stat) {
  const mix = stat.issueMix || [];
  if (!mix.length) return null;
  return {
    series: [{ name: "Records", data: mix.map((s) => s.count) }],
    options: {
      chart: {
        type: "bar",
        fontFamily: CHART_FONT,
        toolbar: { show: false },
      },
      plotOptions: {
        bar: {
          borderRadius: 6,
          horizontal: true,
          distributed: true,
          barHeight: "70%",
        },
      },
      colors: mix.map((s) => toneColor(s.tone)),
      dataLabels: {
        enabled: true,
        style: { fontSize: "10px", fontWeight: 700 },
      },
      xaxis: {
        categories: mix.map((s) => s.label),
        labels: { style: { fontSize: "10px", colors: "#64748b" } },
      },
      yaxis: {
        labels: { style: { fontSize: "10px", fontWeight: 600, colors: "#334155" } },
      },
      grid: {
        borderColor: "rgba(226, 232, 240, 0.9)",
        strokeDashArray: 4,
      },
      legend: { show: false },
      tooltip: { theme: "light" },
    },
  };
}

export function buildAccountTopClientsBarChart(stat) {
  const rows = stat.topByClients || [];
  if (!rows.length) return null;
  const categories = rows.map((r) => truncate(r.name, 20));
  const data = rows.map((r) => r.clients);
  return {
    series: [{ name: "Clients", data }],
    options: {
      chart: {
        type: "bar",
        fontFamily: CHART_FONT,
        toolbar: { show: false },
      },
      plotOptions: {
        bar: {
          borderRadius: 6,
          horizontal: true,
          barHeight: "68%",
        },
      },
      colors: ["rgba(var(--lux-primary-rgb, 91, 95, 244), 0.85)"],
      dataLabels: { enabled: false },
      xaxis: {
        categories,
        labels: { style: { fontSize: "10px", colors: "#64748b" } },
      },
      yaxis: {
        labels: { style: { fontSize: "10px", fontWeight: 600, colors: "#334155" } },
      },
      grid: {
        borderColor: "rgba(226, 232, 240, 0.9)",
        strokeDashArray: 4,
        xaxis: { lines: { show: true } },
        yaxis: { lines: { show: false } },
      },
      tooltip: { theme: "light" },
    },
  };
}

export function buildAccountCoverageBarChart(stat) {
  const { coverage, typeCounts } = stat;
  if (!coverage || !typeCounts) return null;
  const rows = [];
  if (typeCounts.ACCOUNT > 0 && coverage.accountTeamRate != null) {
    rows.push({ label: "Accounts with teams", value: coverage.accountTeamRate });
  }
  if (typeCounts.TEAM > 0 && coverage.teamClientRate != null) {
    rows.push({ label: "Teams with clients", value: coverage.teamClientRate });
  }
  if (typeCounts.CLIENT > 0 && coverage.clientEmailRate != null) {
    rows.push({ label: "Clients with email", value: coverage.clientEmailRate });
  }
  if (!rows.length) return null;
  return {
    series: [{ name: "%", data: rows.map((r) => r.value) }],
    options: {
      chart: { type: "bar", fontFamily: CHART_FONT, toolbar: { show: false } },
      plotOptions: {
        bar: { borderRadius: 6, horizontal: true, barHeight: "65%" },
      },
      colors: ["#14b8a6"],
      dataLabels: {
        enabled: true,
        formatter: (val) => `${val}%`,
        style: { fontSize: "10px", fontWeight: 700 },
      },
      xaxis: { max: 100, labels: { style: { fontSize: "10px" } } },
      yaxis: {
        categories: rows.map((r) => r.label),
        labels: { style: { fontSize: "10px", fontWeight: 600 } },
      },
      grid: { borderColor: "#e2e8f0", strokeDashArray: 4 },
      tooltip: { y: { formatter: (v) => `${v}%` } },
    },
  };
}

function truncate(str, max) {
  if (!str || str.length <= max) return str || "";
  return `${str.slice(0, max - 1)}…`;
}

function toneColor(tone) {
  const map = {
    indigo: "#6366f1",
    sky: "#0ea5e9",
    teal: "#14b8a6",
    green: "#22c55e",
    amber: "#f59e0b",
    slate: "#94a3b8",
    rose: "#f43f5e",
    violet: "#8b5cf6",
  };
  return map[tone] || map.slate;
}

export function buildAccountsSummaryCharts(stat) {
  return {
    typeDonut: buildAccountTypeDonutChart(stat),
    sourceDonut: buildAccountSourceDonutChart(stat),
    healthDonut: buildAccountHealthDonutChart(stat),
    billingDonut: buildAccountBillingDonutChart(stat),
    issuesBar: buildAccountIssuesBarChart(stat),
    topClientsBar: buildAccountTopClientsBarChart(stat),
    coverageBar: buildAccountCoverageBarChart(stat),
  };
}
