const DEFAULT_SETTINGS = {
  typography: 'custom',
  font: 'inter',
  stickyHeader: true,
  elevatedSurfaces: false,
  moduleMenuRail: true,
};

export function getTypographyPreset(presetId) {
  return TYPOGRAPHY_PRESETS.find((preset) => preset.id === presetId) || null;
}

export function getFontOption(fontId) {
  const normalized = LEGACY_FONT_MAP[fontId] || fontId;
  return FONT_OPTIONS.find((font) => font.id === normalized) || FONT_OPTIONS[0];
}

export function getActiveTypographyLabel(settings) {
  const preset = getTypographyPreset(settings.typography);
  if (preset) {
    return preset.label;
  }
  return getFontOption(settings.font).label;
}

function buildFontStack(family) {
  return `${family}, ${FONT_FALLBACK}`;
}

function normalizeSettings(settings) {
  const raw = settings || {};
  const next = { ...DEFAULT_SETTINGS, ...raw };
  const hasTypography = Object.prototype.hasOwnProperty.call(raw, 'typography');

  if (!hasTypography) {
    if (Object.keys(raw).length === 0) {
      const defaultPreset = getTypographyPreset(next.typography);
      if (defaultPreset) {
        next.font = defaultPreset.uiFontId;
      }
      return next;
    }
    next.typography = 'custom';
    next.font = getFontOption(next.font).id;
    return next;
  }

  const preset = getTypographyPreset(next.typography);
  if (preset) {
    next.font = preset.uiFontId;
  } else {
    next.typography = 'custom';
    next.font = getFontOption(next.font).id;
  }

  return next;
}

export function getUiSettings() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_SETTINGS };
    return normalizeSettings(JSON.parse(raw));
  } catch (e) {
    return { ...DEFAULT_SETTINGS };
  }
}

function persistUiSettings(settings) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch (e) {
    /* ignore storage errors */
  }
}

function ensureGoogleFontLoaded(linkId, googleFamily) {
  if (!googleFamily || typeof document === 'undefined') return;

  if (document.getElementById(linkId)) return;

  const link = document.createElement('link');
  link.id = linkId;
  link.rel = 'stylesheet';
  link.href = `https://fonts.googleapis.com/css2?family=${googleFamily}&display=swap`;
  document.head.appendChild(link);
}

function ensureFontLoaded(fontOption) {
  if (!fontOption || !fontOption.googleFamily) return;
  ensureGoogleFontLoaded(`lux-font-${fontOption.id}`, fontOption.googleFamily);
}

function applyBrandFont(typographyId) {
  const preset = getTypographyPreset(typographyId);
  const brand = preset
    ? {
        family: preset.brandFamily,
        googleFamily: preset.brandGoogleFamily,
        linkId: preset.brandLinkId,
      }
    : DEFAULT_BRAND;

  ensureGoogleFontLoaded(brand.linkId, brand.googleFamily);

  const stack = buildFontStack(brand.family);
  const typographyAttr = preset ? preset.id : 'custom';

  document.documentElement.setAttribute('data-lux-typography', typographyAttr);
  document.documentElement.style.setProperty('--lux-brand-font', stack);

  if (document.body) {
    document.body.style.setProperty('--lux-brand-font', stack);
  }
}

function applyFont(fontId) {
  const fontOption = getFontOption(fontId);
  const stack = buildFontStack(fontOption.family);

  ensureFontLoaded(fontOption);

  document.documentElement.setAttribute('data-lux-font', fontOption.id);
  document.documentElement.style.setProperty('--app-font-sans', stack);

  if (document.body) {
    document.body.style.setProperty('--app-font-sans', stack);
  }

  const root = document.getElementById('root');
  if (root) {
    root.style.setProperty('--app-font-sans', stack);
  }

  const mainContent = document.getElementById('main_content');
  if (mainContent) {
    mainContent.style.setProperty('--app-font-sans', stack);
  }

  return fontOption;
}

function applyElevatedSurfaces(enabled) {
  document.body.classList.toggle('lux-elevated-surfaces', enabled);
  document.querySelectorAll('.card, .btn, .progress').forEach((el) => {
    el.classList.toggle('box_shadow', enabled);
  });
}

export function applyUiSettings(settings) {
  const next = normalizeSettings(settings);

  applyFont(next.font);
  applyBrandFont(next.typography);

  const pageTop = document.getElementById('page_top');
  if (pageTop) {
    pageTop.classList.toggle('sticky-top', next.stickyHeader);
  }

  if (document.body) {
    applyElevatedSurfaces(next.elevatedSurfaces);
    document.body.classList.toggle('lux-module-menu-rail', next.moduleMenuRail !== false);
  }

  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('lux-ui-settings-changed', { detail: next }));
  }

  return next;
}

export function updateUiSettings(partial) {
  const merged = { ...getUiSettings(), ...partial };

  if (partial.font !== undefined && partial.typography === undefined) {
    merged.typography = 'custom';
  }

  const next = applyUiSettings(merged);
  persistUiSettings(next);
  return next;
}

export function initUiSettings() {
  const settings = getUiSettings();
  applyUiSettings(settings);
  return settings;
}

export function getFontIds() {
  return FONT_IDS;
}
