import React from "react";
import { formatFinanceUsd } from "config/finance-intelligence.utils";

export default function FinanceChartStrip({ series = [], loading }) {
  if (loading) {
    return <div className="lux-finance-chart__loading">Loading forecast chart…</div>;
  }
  if (!series.length) {
    return <div className="lux-finance-chart__empty">No forecast series available.</div>;
  }

  const maxRevenue = Math.max(...series.map((row) => row.revenueUsd || 0), 1);

  return (
    <div className="lux-finance-chart">
      <div className="lux-finance-chart__legend">
        <span>
          <i className="lux-finance-chart__dot is-revenue" aria-hidden="true" />
          Revenue
        </span>
        <span>
          <i className="lux-finance-chart__dot is-cost" aria-hidden="true" />
          Cost
        </span>
      </div>
      <div className="lux-finance-chart__bars">
        {series.map((row) => (
          <div key={row.month} className="lux-finance-chart__col">
            <div className="lux-finance-chart__stack">
              <span
                className="lux-finance-chart__bar is-revenue"
                style={{ height: `${Math.round(((row.revenueUsd || 0) / maxRevenue) * 100)}%` }}
                title={`Revenue ${formatFinanceUsd(row.revenueUsd)}`}
              />
              <span
                className="lux-finance-chart__bar is-cost"
                style={{ height: `${Math.round(((row.costUsd || 0) / maxRevenue) * 100)}%` }}
                title={`Cost ${formatFinanceUsd(row.costUsd)}`}
              />
            </div>
            <small>{row.month.slice(5)}</small>
            <span>{row.marginPct}%</span>
          </div>
        ))}
      </div>
    </div>
  );
}
