import React from "react";
import classNames from "classnames/bind";
import FinanceChartStrip from "views/finance/components/FinanceChartStrip";
import { FinanceActionButton } from "views/finance/components/FinanceLuxShared";
import { formatFinancePct, formatFinanceUsd } from "config/finance-intelligence.utils";

export default function RevenueForecastPanel({
  forecasts = [],
  activeForecast,
  chartSeries = [],
  loading,
  activeForecastId,
  onSelectForecast,
  onSaveForecast,
  saving,
}) {
  return (
    <div className="lux-finance-forecast">
      <div className="lux-finance-snapshots__toolbar">
        <div className="lux-finance-snapshots__filters">
          <label className="lux-finance-snapshots__field">
            <span>Scenario</span>
            <select
              value={activeForecastId || (activeForecast && activeForecast.id) || ""}
              onChange={(event) => onSelectForecast(event.target.value)}
            >
              {forecasts.map((row) => (
                <option key={row.id} value={row.id}>
                  {row.name} ({row.scenarioType})
                </option>
              ))}
            </select>
          </label>
        </div>
        <div className="lux-finance-toolbar__actions">
          <FinanceActionButton
            icon="fe fe-save"
            variant="ghost"
            onClick={onSaveForecast}
            disabled={saving || !activeForecast}
          >
            {saving ? "Saving…" : "Save scenario"}
          </FinanceActionButton>
        </div>
      </div>

      {activeForecast ? (
        <div className="lux-finance-forecast__summary">
          <span className={classNames("lux-portfolio-badge", activeForecast.variancePct < 0 ? "is-rose" : "is-green")}>
            {formatFinancePct(activeForecast.variancePct)} vs prior
          </span>
          <p>
            {activeForecast.name} forecasts {formatFinanceUsd(activeForecast.totalForecastUsd)} over{" "}
            {activeForecast.horizonMonths} months.
          </p>
        </div>
      ) : null}

      <FinanceChartStrip series={chartSeries} loading={loading} />
    </div>
  );
}
