import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { PROJECT_HEALTH_BANDS } from "config/portfolio-control-tower.config";

const BAND_TONE = {
  [PROJECT_HEALTH_BANDS.HEALTHY]: "green",
  [PROJECT_HEALTH_BANDS.WATCH]: "amber",
  [PROJECT_HEALTH_BANDS.CRITICAL]: "rose",
};

export default function PortfolioProjectHealthRegister({ rows = [], loading }) {
  if (loading) {
    return <div className="lux-portfolio-register__loading">Loading project health snapshots…</div>;
  }

  if (!rows.length) {
    return <div className="lux-portfolio-register__empty">No governed projects in the current portfolio scope.</div>;
  }

  return (
    <div className="lux-portfolio-register-wrap">
      <table className="lux-portfolio-register lux-portfolio-register--health">
        <thead>
          <tr>
            <th>Project</th>
            <th>Program</th>
            <th>Health</th>
            <th>Band</th>
            <th>Slippage</th>
            <th>Risks</th>
            <th>Issues</th>
            <th>Gates</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.projectId} className="lux-portfolio-register__row">
              <td>
                <div className="lux-portfolio-register__primary">
                  <strong>{row.projectName}</strong>
                  <small>{row.projectCode}</small>
                </div>
              </td>
              <td>{row.programName || "—"}</td>
              <td>
                <strong>{row.healthScore}%</strong>
              </td>
              <td>
                <span className={classNames("lux-portfolio-badge", `is-${BAND_TONE[row.healthBand] || "slate"}`)}>
                  {row.healthBand || "—"}
                </span>
              </td>
              <td>{row.milestoneSlippageDays != null ? `${row.milestoneSlippageDays}d` : "—"}</td>
              <td>
                {row.openRisks}
                {row.criticalRisks > 0 ? <small>{row.criticalRisks} critical</small> : null}
              </td>
              <td>{row.openIssues}</td>
              <td>{row.gateComplianceRate != null ? `${row.gateComplianceRate}%` : "—"}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p className="lux-portfolio-register__foot">
        Open project delivery views via{" "}
        <Link to="/project/milestones">milestones</Link>,{" "}
        <Link to="/project/risks">risks</Link>, or{" "}
        <Link to="/project/issues">issues</Link>.
      </p>
    </div>
  );
}
