/**
 * Maps legacy ItemsNotFoundSection image filenames to luxury empty-state presets.
 */
export const LEGACY_EMPTY_IMG_PRESETS = {
  "no_checklist.png": {
    variant: "checklist",
    eyebrow: "Checklist",
    hints: [
      "Attach a template from deliverable or work-item settings",
      "Questions can be required before marking work complete",
      "Saved checklists sync with completion status",
    ],
  },
  "noactivetasks-min.PNG": {
    variant: "task-activities",
    eyebrow: "Work activities",
    hints: [
      "Create activities from project deliverables",
      "Use filters and date range to narrow the register",
      "Log time against activities from the timesheet",
    ],
  },
  "notasks-min.PNG": {
    variant: "bid-requests",
    eyebrow: "Bid register",
    hints: [
      "Confirm the bid ID in the URL",
      "Return to the list and open the bid from the register",
      "Check team scope if the record was recently created",
    ],
  },
  "noprojects-min.PNG": {
    variant: "projects",
    eyebrow: "Project workspace",
    hints: [
      "Confirm the project ID in the URL",
      "Open the project from the portfolio list",
      "Verify team membership and permissions",
    ],
  },
  "nocontacts-min.PNG": {
    variant: "attendance",
    eyebrow: "Team roster",
    hints: [
      "Select one or more teams in the header",
      "Employees must be active in the selected teams",
      "Try clearing filters if the roster looks empty",
    ],
  },
};

export function resolveLegacyEmptyPreset(imgurl) {
  if (!imgurl) return null;
  const key = Object.keys(LEGACY_EMPTY_IMG_PRESETS).find(
    (k) => k.toLowerCase() === String(imgurl).toLowerCase()
  );
  return key ? LEGACY_EMPTY_IMG_PRESETS[key] : null;
}
