/**
 * Compose analytics from live list endpoints so charts/KPIs always match the FE contract
 * even when /analytics returns the EA17 metrics-array shape.
 */
async function composeResourceAnalyticsFromLists() {
  const [capacityResult, allocationsResult, staffingResult, benchResult, skillsResult] =
    await Promise.all([
      getCapacitySummary().catch(() => ({ payload: null })),
      listAllocations().catch(() => ({ payload: [] })),
      listStaffingRequests().catch(() => ({ payload: [] })),
      listBenchRecords().catch(() => ({ payload: [] })),
      listSkillProfiles().catch(() => ({ payload: [] })),
    ]);

  const capacitySummary = capacityResult && capacityResult.payload;
  const allocations = (allocationsResult && allocationsResult.payload) || [];
  const staffingRequests = (staffingResult && staffingResult.payload) || [];
  const benchRecords = (benchResult && benchResult.payload) || [];
  const skillProfiles = (skillsResult && skillsResult.payload) || [];

  const hasAny =
    capacitySummary ||
    allocations.length ||
    staffingRequests.length ||
    benchRecords.length ||
    skillProfiles.length;

  if (!hasAny) {
    return { payload: null, source: "api-error" };
  }

  return {
    payload: composeResourceAnalyticsSnapshot({
      capacitySummary,
      allocations,
      staffingRequests,
      benchRecords,
      skillProfiles,
    }),
    source:
      (capacityResult && capacityResult.source === "api") ||
      (allocationsResult && allocationsResult.source === "api") ||
      (staffingResult && staffingResult.source === "api") ||
      (benchResult && benchResult.source === "api") ||
      (skillsResult && skillsResult.source === "api")
        ? "api"
        : "client",
  };
}

function pickNonEmptySeries(primary, secondary) {
  if (Array.isArray(primary) && primary.length) return primary;
  if (Array.isArray(secondary) && secondary.length) return secondary;
  return Array.isArray(primary) ? primary : [];
}

async function getResourceAnalytics() {
  const composed = await composeResourceAnalyticsFromLists();

  let apiPayload = null;
  try {
    const result = await getResourceAnalyticsFromApi();
    apiPayload = result && result.payload;
  } catch (e) {
    // List composition keeps the page usable when /analytics fails or returns EA17-only shape.
  }

  if (!composed.payload && !apiPayload) {
    return apiErrorResult(null);
  }

  if (!composed.payload) {
    const payload = normalizeResourceAnalyticsSnapshot(apiPayload, {});
    recordResourceAudit(AUDIT_ACTION_TYPES.AUDIT_VIEWED, "Resource analytics viewed", "resource-analytics", {
      route: "/resources/utilization",
    });
    return { payload, source: "api" };
  }

  const apiNormalized = apiPayload
    ? normalizeResourceAnalyticsSnapshot(apiPayload, {
        capacitySummary: {
          snapshotDate: composed.payload.snapshotDate,
          avgUtilizationPct: composed.payload.metrics.avgUtilizationPct,
          freeHours: composed.payload.metrics.freeHours,
        },
      })
    : null;

  const payload = {
    snapshotDate: (apiPayload && apiPayload.snapshotDate) || composed.payload.snapshotDate,
    metrics: {
      ...composed.payload.metrics,
      ...(apiNormalized && apiNormalized.metrics),
    },
    charts: {
      capacityVsDemand: pickNonEmptySeries(
        composed.payload.charts.capacityVsDemand,
        apiNormalized && apiNormalized.charts.capacityVsDemand
      ),
      allocationByProject: pickNonEmptySeries(
        composed.payload.charts.allocationByProject,
        apiNormalized && apiNormalized.charts.allocationByProject
      ),
      benchTrend: pickNonEmptySeries(
        composed.payload.charts.benchTrend,
        apiNormalized && apiNormalized.charts.benchTrend
      ),
      overallocatedUsers: pickNonEmptySeries(
        composed.payload.charts.overallocatedUsers,
        apiNormalized && apiNormalized.charts.overallocatedUsers
      ),
      upcomingRolloffs: pickNonEmptySeries(
        composed.payload.charts.upcomingRolloffs,
        apiNormalized && apiNormalized.charts.upcomingRolloffs
      ),
      skillGaps: pickNonEmptySeries(
        composed.payload.charts.skillGaps,
        apiNormalized && apiNormalized.charts.skillGaps
      ),
      heatmap: pickNonEmptySeries(
        composed.payload.charts.heatmap,
        apiNormalized && apiNormalized.charts.heatmap
      ),
    },
    insights:
      apiNormalized && apiNormalized.insights && apiNormalized.insights.length
        ? apiNormalized.insights
        : composed.payload.insights,
  };

  recordResourceAudit(AUDIT_ACTION_TYPES.AUDIT_VIEWED, "Resource analytics viewed", "resource-analytics", {
    route: "/resources/utilization",
  });

  return {
    payload,
    source: apiPayload ? "api" : composed.source || "client",
  };
}

