async function updateBenchRecord(benchId, payload) {
  if (shouldUseResourcePlanningApi()) {
    try {
      const response = await axiosUtils.patch(
        `${urlConfig.RESOURCE_PLANNING_API_PATH}/bench/${benchId}?${resourceTeamQueryString({
          actorId: commonUtils.getCurrentUserId(),
        })}`,
        payload
      );
      const row = normalizeBenchRecord((response && response.payload) || response);
      const isPlacement = row && row.status === "PLACED";
      recordResourceAudit(
        isPlacement ? AUDIT_ACTION_TYPES.APPROVED : AUDIT_ACTION_TYPES.STATUS_CHANGED,
        isPlacement ? "Resource placement confirmed" : "Bench record updated",
        benchId,
        {
          status: row && row.status,
          employeeId: row && row.employeeId,
          action: isPlacement ? "RESOURCE_CONFIRMED" : undefined,
        }
      );
      return { payload: row, source: "api" };
    } catch (e) {
      // fall through
    }
  }

  return { payload: null, source: "client" };
}
