import {
  FINANCE_BILLING_PLAN_STATUSES,
  FINANCE_INVOICE_REC_STATUSES,
  FINANCE_LEAKAGE_SEVERITIES,
  normalizeBillingPlan,
  normalizeInvoiceRecommendation,
  normalizeRevenueForecast,
  normalizeRevenueLeakageFlag,
} from "config/finance-intelligence.config";
import {
  buildProjectFinancialsRollup,
  formatFinancePct,
  formatFinanceUsd,
} from "config/finance-intelligence.utils";

export function filterBillingPlans(rows = [], filters = {}) {
  let result = rows.map((row) => normalizeBillingPlan(row)).filter(Boolean);
  if (filters.status && filters.status !== "ALL") {
    result = result.filter((row) => row.status === filters.status);
  }
  if (filters.search) {
    const term = String(filters.search).trim().toLowerCase();
    if (term) {
      result = result.filter(
        (row) =>
          (row.name && row.name.toLowerCase().indexOf(term) >= 0) ||
          (row.projectName && row.projectName.toLowerCase().indexOf(term) >= 0)
      );
    }
  }
  return result;
}

export function buildBillingPlansOverview(rows = []) {
  const plans = filterBillingPlans(rows);
  const active = plans.filter((row) => row.status === FINANCE_BILLING_PLAN_STATUSES.ACTIVE);
  const readyMilestones = active.reduce((count, plan) => {
    const ready = (plan.milestones || []).filter((ms) => ms.status === "READY").length;
    return count + ready;
  }, 0);
  const overdueMilestones = active.reduce((count, plan) => {
    const overdue = (plan.milestones || []).filter((ms) => ms.status === "OVERDUE").length;
    return count + overdue;
  }, 0);
  const totalValue = active.reduce((sum, row) => sum + (row.totalValueUsd || 0), 0);
  const recognized = active.reduce((sum, row) => sum + (row.recognizedUsd || 0), 0);

  return {
    plans,
    kpiCards: [
      {
        id: "active-plans",
        label: "Active plans",
        value: String(active.length),
        hint: `${plans.length} total`,
        tone: "indigo",
        icon: "fe fe-layers",
      },
      {
        id: "recognized",
        label: "Recognized revenue",
        value: formatFinanceUsd(recognized),
        hint: `of ${formatFinanceUsd(totalValue)}`,
        tone: "green",
        icon: "fe fe-check-circle",
      },
      {
        id: "ready-ms",
        label: "Ready milestones",
        value: String(readyMilestones),
        hint: "Billable now",
        tone: "amber",
        icon: "fe fe-flag",
      },
      {
        id: "overdue-ms",
        label: "Overdue milestones",
        value: String(overdueMilestones),
        hint: "Needs action",
        tone: "rose",
        icon: "fe fe-alert-triangle",
      },
    ],
    insights: [
      overdueMilestones > 0
        ? {
            id: "overdue-billing",
            tone: "rose",
            icon: "fe fe-alert-circle",
            title: `${overdueMilestones} overdue milestone${overdueMilestones > 1 ? "s" : ""}`,
            body: "Review billing readiness before the next finance steering pack.",
            path: "/finance/invoice",
          }
        : {
            id: "billing-stable",
            tone: "green",
            icon: "fe fe-check",
            title: "Billing plans on track",
            body: `${readyMilestones} milestone${readyMilestones !== 1 ? "s" : ""} ready for invoicing.`,
            path: "/finance/invoice",
          },
    ],
  };
}

export function validateBillingPlanPayload(payload = {}) {
  const errors = [];
  if (!payload.projectId) {
    errors.push("projectId is required");
  }
  if (!payload.name) {
    errors.push("name is required");
  }
  return { valid: errors.length === 0, errors };
}

export function filterRevenueForecasts(rows = [], filters = {}) {
  let result = rows.map((row) => normalizeRevenueForecast(row)).filter(Boolean);
  if (filters.scenarioType && filters.scenarioType !== "ALL") {
    result = result.filter((row) => row.scenarioType === filters.scenarioType);
  }
  if (filters.status && filters.status !== "ALL") {
    result = result.filter((row) => row.status === filters.status);
  }
  return result;
}

export function buildRevenueForecastOverview(rows = [], activeId) {
  const forecasts = filterRevenueForecasts(rows);
  const active =
    forecasts.find((row) => row.id === activeId) ||
    forecasts.find((row) => row.status === "ACTIVE") ||
    forecasts[0] ||
    null;
  const chartRows = active && active.monthly ? active.monthly : [];
  const marginSeries = chartRows.map((row) => {
    const revenue = row.revenueUsd || 0;
    const cost = row.costUsd || 0;
    const marginPct = revenue > 0 ? Math.round(((revenue - cost) / revenue) * 100) : 0;
    return { month: row.month, revenueUsd: revenue, costUsd: cost, marginPct };
  });

  return {
    forecasts,
    activeForecast: active,
    chartSeries: marginSeries,
    kpiCards: active
      ? [
          {
            id: "forecast-total",
            label: "Forecast total",
            value: formatFinanceUsd(active.totalForecastUsd),
            hint: active.name,
            tone: "indigo",
            icon: "fe fe-trending-up",
          },
          {
            id: "variance",
            label: "Variance vs prior",
            value: formatFinancePct(active.variancePct),
            hint: "Scenario delta",
            tone: active.variancePct < 0 ? "rose" : "green",
            icon: "fe fe-activity",
          },
          {
            id: "horizon",
            label: "Horizon",
            value: `${active.horizonMonths || 0} mo`,
            hint: active.scenarioType,
            tone: "blue",
            icon: "fe fe-calendar",
          },
          {
            id: "margin",
            label: "Avg margin",
            value: formatFinancePct(
              marginSeries.length
                ? Math.round(
                    marginSeries.reduce((sum, row) => sum + row.marginPct, 0) / marginSeries.length
                  )
                : null
            ),
            hint: "Cost vs revenue",
            tone: "amber",
            icon: "fe fe-pie-chart",
          },
        ]
      : [],
    insights: active
      ? [
          {
            id: "forecast-variance",
            tone: active.variancePct < 0 ? "rose" : "green",
            icon: "fe fe-bar-chart-2",
            title: `${active.name} ${active.variancePct < 0 ? "below" : "above"} prior`,
            body: `Total forecast ${formatFinanceUsd(active.totalForecastUsd)} with ${formatFinancePct(active.variancePct)} variance.`,
            path: "/finance/project-financials",
          },
        ]
      : [],
  };
}

export function validateRevenueForecastPayload(payload = {}) {
  const errors = [];
  if (!payload.name) {
    errors.push("name is required");
  }
  if (!payload.scenarioType) {
    errors.push("scenarioType is required");
  }
  return { valid: errors.length === 0, errors };
}

export function filterRevenueLeakageFlags(rows = [], filters = {}) {
  let result = rows.map((row) => normalizeRevenueLeakageFlag(row)).filter(Boolean);
  if (filters.severity && filters.severity !== "ALL") {
    result = result.filter((row) => row.severity === filters.severity);
  }
  if (filters.status && filters.status !== "ALL") {
    result = result.filter((row) => row.status === filters.status);
  }
  return result;
}

export function buildRevenueLeakageOverview(rows = []) {
  const flags = filterRevenueLeakageFlags(rows, { status: "ALL" });
  const openFlags = flags.filter((row) => row.status === "OPEN");
  const highSeverity = openFlags.filter((row) => row.severity === FINANCE_LEAKAGE_SEVERITIES.HIGH);
  const totalLeakageUsd = openFlags.reduce((sum, row) => sum + (row.estimatedUsd || 0), 0);

  return {
    flags,
    openFlags,
    kpiCards: [
      {
        id: "open-flags",
        label: "Open leakage flags",
        value: String(openFlags.length),
        hint: `${flags.length} total`,
        tone: "rose",
        icon: "fe fe-alert-triangle",
      },
      {
        id: "high-sev",
        label: "High severity",
        value: String(highSeverity.length),
        hint: "Needs steering review",
        tone: "rose",
        icon: "fe fe-shield",
      },
      {
        id: "leakage-usd",
        label: "Estimated leakage",
        value: formatFinanceUsd(totalLeakageUsd),
        hint: "Open items",
        tone: "amber",
        icon: "fe fe-dollar-sign",
      },
      {
        id: "avg-pct",
        label: "Avg leakage %",
        value: formatFinancePct(
          openFlags.length
            ? Math.round(
                openFlags.reduce((sum, row) => sum + (row.leakagePct || 0), 0) / openFlags.length
              )
            : 0
        ),
        hint: "Portfolio avg",
        tone: "violet",
        icon: "fe fe-percent",
      },
    ],
    insights: openFlags.length
      ? openFlags.slice(0, 2).map((row) => ({
          id: row.id,
          tone: row.severity === FINANCE_LEAKAGE_SEVERITIES.HIGH ? "rose" : "amber",
          icon: "fe fe-alert-circle",
          title: `${row.projectName} — ${row.leakageType.replace(/_/g, " ").toLowerCase()}`,
          body: row.recommendation,
          path: "/finance/project-financials",
        }))
      : [
          {
            id: "no-leakage",
            tone: "green",
            icon: "fe fe-check-circle",
            title: "No open leakage flags",
            body: "Timesheet and billing reconciliation is within tolerance.",
            path: "/analytics/finance",
          },
        ],
  };
}

export function filterInvoiceRecommendations(rows = [], filters = {}) {
  let result = rows.map((row) => normalizeInvoiceRecommendation(row)).filter(Boolean);
  if (filters.status && filters.status !== "ALL") {
    result = result.filter((row) => row.status === filters.status);
  }
  return result;
}

export function buildInvoiceRecommendationsOverview(rows = []) {
  const recommendations = filterInvoiceRecommendations(rows);
  const pending = recommendations.filter((row) => row.status === FINANCE_INVOICE_REC_STATUSES.PENDING);
  const pendingValue = pending.reduce((sum, row) => sum + (row.recommendedAmountUsd || 0), 0);

  return {
    recommendations,
    pending,
    kpiCards: [
      {
        id: "pending-recs",
        label: "Pending recommendations",
        value: String(pending.length),
        hint: "Billing Advice Agent",
        tone: "indigo",
        icon: "fe fe-zap",
      },
      {
        id: "pending-value",
        label: "Recommended value",
        value: formatFinanceUsd(pendingValue),
        hint: "Ready to invoice",
        tone: "green",
        icon: "fe fe-credit-card",
      },
    ],
  };
}

export function buildFinanceDashboardOverview(context = {}) {
  const snapshots = context.snapshots || [];
  const billingPlans = context.billingPlans || [];
  const forecasts = context.forecasts || [];
  const leakage = context.leakage || [];
  const recommendations = context.recommendations || [];

  const projectRollup = buildProjectFinancialsRollup(snapshots, { includeSensitive: true });
  const billingOverview = buildBillingPlansOverview(billingPlans);
  const forecastOverview = buildRevenueForecastOverview(forecasts);
  const leakageOverview = buildRevenueLeakageOverview(leakage);
  const invoiceOverview = buildInvoiceRecommendationsOverview(recommendations);

  return {
    kpiCards: [
      {
        id: "revenue",
        label: "Portfolio revenue",
        value: formatFinanceUsd(projectRollup.revenueUsd),
        hint: `${projectRollup.projectCount} projects`,
        tone: "indigo",
        icon: "fe fe-dollar-sign",
      },
      {
        id: "margin",
        label: "Blended margin",
        value: formatFinancePct(projectRollup.blendedMarginPct),
        hint: "Revenue-weighted",
        tone: "green",
        icon: "fe fe-trending-up",
      },
      {
        id: "unbilled",
        label: "Unbilled work",
        value: formatFinanceUsd(projectRollup.unbilledUsd),
        hint: `${billingOverview.kpiCards[2] && billingOverview.kpiCards[2].value} ready milestones`,
        tone: "amber",
        icon: "fe fe-alert-circle",
      },
      {
        id: "leakage",
        label: "Open leakage",
        value: String(leakageOverview.openFlags.length),
        hint: formatFinanceUsd(
          leakageOverview.openFlags.reduce((sum, row) => sum + (row.estimatedUsd || 0), 0)
        ),
        tone: "rose",
        icon: "fe fe-shield",
      },
    ],
    insights: [
      ...billingOverview.insights,
      ...forecastOverview.insights.slice(0, 1),
      ...leakageOverview.insights.slice(0, 1),
      {
        id: "invoice-recs",
        tone: "violet",
        icon: "fe fe-zap",
        title: `${invoiceOverview.pending.length} invoice recommendations`,
        body: `${formatFinanceUsd(
          invoiceOverview.pending.reduce((sum, row) => sum + (row.recommendedAmountUsd || 0), 0)
        )} ready for finance review.`,
        path: "/finance/invoice",
      },
    ].slice(0, 4),
    chartSeries: forecastOverview.chartSeries,
    pendingRecommendations: invoiceOverview.pending,
    openLeakage: leakageOverview.openFlags,
  };
}

export function exportBillingPlansCsv(rows = []) {
  const plans = filterBillingPlans(rows);
  if (!plans.length) {
    return "";
  }
  const header = "plan_id,project,name,status,total_usd,recognized_usd,readiness_pct,next_billing_date";
  const lines = plans.map((row) =>
    [
      row.id,
      row.projectName,
      row.name,
      row.status,
      row.totalValueUsd,
      row.recognizedUsd,
      row.readinessPct,
      row.nextBillingDate,
    ]
      .map((cell) => `"${String(cell == null ? "" : cell).replace(/"/g, '""')}"`)
      .join(",")
  );
  return [header, ...lines].join("\n");
}

export function exportRevenueForecastCsv(forecast) {
  const row = normalizeRevenueForecast(forecast);
  if (!row || !row.monthly.length) {
    return "";
  }
  const header = "month,revenue_usd,cost_usd,margin_pct";
  const lines = row.monthly.map((monthRow) => {
    const revenue = monthRow.revenueUsd || 0;
    const cost = monthRow.costUsd || 0;
    const marginPct = revenue > 0 ? Math.round(((revenue - cost) / revenue) * 100) : 0;
    return `"${monthRow.month}",${revenue},${cost},${marginPct}`;
  });
  return [header, ...lines].join("\n");
}

export function exportFinancePackCsv(context = {}) {
  const sections = [];
  if (context.projectFinancialsCsv) {
    sections.push("# Project financials", context.projectFinancialsCsv);
  }
  if (context.billingPlansCsv) {
    sections.push("# Billing plans", context.billingPlansCsv);
  }
  if (context.forecastCsv) {
    sections.push("# Revenue forecast", context.forecastCsv);
  }
  return sections.join("\n\n");
}
