/**
 * W5-B02 / EXP-009 — Expense amount persona masking (mirrors paycheck-security.utils).
 */
import { resolveMaskedFieldValue, isFieldVisible } from "config/employee360-field.utils";
import { redactAuditMetadata } from "config/audit-write.utils";

const EXPENSE_FINANCE_PERSONAS = ["FINANCE", "PAYROLL_MANAGER", "HR_ADMIN", "SYSTEM_ADMIN", "ADMIN"];

export function buildExpenseViewerContext(personaContext, currentUser) {
  const user = currentUser || {};
  return {
    activePersona: (personaContext && personaContext.activePersona) || "EMPLOYEE",
    viewerEmployeeId: user.id || (personaContext && personaContext.employeeId) || null,
    maskingPolicy: (personaContext && personaContext.maskingPolicy) || {},
  };
}

export function canViewExpenseAmount(viewerContext, claim) {
  if (!claim) {
    return false;
  }
  const ctx = viewerContext || {};
  if (
    ctx.viewerEmployeeId &&
    claim.employeeId &&
    String(ctx.viewerEmployeeId) === String(claim.employeeId)
  ) {
    return true;
  }
  const persona = ctx.activePersona || "EMPLOYEE";
  return EXPENSE_FINANCE_PERSONAS.indexOf(persona) >= 0;
}

export function maskExpenseAmount(value, maskingPolicy, currency) {
  if (value == null) {
    return "—";
  }
  const formatted =
    currency != null
      ? `${currency} ${value}`
      : String(value);
  return resolveMaskedFieldValue("payrollLines", formatted, maskingPolicy);
}

export function maskExpenseClaimForDisplay(claim, maskingPolicy, viewerContext) {
  if (!claim) {
    return null;
  }
  const ctx = viewerContext || {};
  const isOwn =
    ctx.viewerEmployeeId &&
    claim.employeeId &&
    String(ctx.viewerEmployeeId) === String(claim.employeeId);
  if (isOwn) {
    return claim;
  }

  const policy = maskingPolicy || ctx.maskingPolicy || {};
  if (!isFieldVisible("payrollLines", policy)) {
    return {
      ...claim,
      amount: "Restricted",
      amountUsd: "Restricted",
    };
  }

  const currency = claim.currency || "USD";
  return {
    ...claim,
    amount: maskExpenseAmount(claim.amount != null ? claim.amount : claim.amountUsd, policy, currency),
    amountUsd:
      claim.amountUsd != null ? maskExpenseAmount(claim.amountUsd, policy, currency) : claim.amountUsd,
  };
}

export function buildExpenseAuditMetadata(claim, actionType, extras) {
  const base = {
    actionType,
    claimRef: claim && (claim.claimRef || claim.id),
    employeeId: claim && claim.employeeId,
    status: claim && claim.status,
    amountMasked: claim && claim.amount != null ? "••••••" : undefined,
  };
  return redactAuditMetadata(Object.assign(base, extras || {}));
}
