import React from "react";
import classNames from "classnames/bind";
import LifecycleDepartmentSelect from "./LifecycleDepartmentSelect";

function LifecycleFilterBar({
  statusFilter,
  departmentFilter,
  statusOptions,
  departments,
  onStatusChange,
  onDepartmentChange,
  resultCount,
}) {
  return (
    <div className="lux-onb-toolbar">
      <div className="lux-onb-toolbar__grid">
        <div className="lux-onb-toolbar__status-col">
          <span className="lux-onb-toolbar__label">Status</span>
          <div
            className="lux-hrms-dash__filter-group lux-onb-toolbar__chips"
            role="group"
            aria-label="Filter by status"
          >
            <button
              type="button"
              className={classNames("lux-hrms-dash__filter-chip", { "is-active": statusFilter === "ALL" })}
              onClick={() => onStatusChange("ALL")}
            >
              All
            </button>
            {statusOptions.map((item) => (
              <button
                key={item.id}
                type="button"
                className={classNames("lux-hrms-dash__filter-chip", { "is-active": statusFilter === item.id })}
                onClick={() => onStatusChange(item.id)}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>

        <div className="lux-onb-toolbar__dept-col">
          <LifecycleDepartmentSelect
            value={departmentFilter}
            departments={departments}
            onChange={onDepartmentChange}
          />
        </div>
      </div>

      <span className="lux-onb-toolbar__count">
        <strong>{resultCount}</strong>
        <span>case{resultCount === 1 ? "" : "s"}</span>
      </span>
    </div>
  );
}

export default LifecycleFilterBar;
