import React from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import {
  TicketActionButton,
  TicketPriorityBadge,
  TicketSlaBadge,
  TicketStatusBadge,
} from "views/tickets/components/TicketsLuxShared";
import TicketAiPanel from "views/tickets/components/TicketAiPanel";

export default function TicketDetailDrawer({
  ticket,
  aiSuggestion,
  aiLoading,
  onClose,
  onResolve,
  onEscalate,
  busy,
}) {
  if (!ticket) {
    return null;
  }

  const accent = ticket.slaStatus === "breached" ? "danger" : ticket.priority === "P1" ? "warning" : "indigo";

  return createPortal(
    <div className="lux-ticket-drawer-backdrop" role="presentation" onClick={onClose}>
      <aside
        className={classNames("lux-ticket-drawer", `lux-ticket-drawer--${accent}`)}
        role="dialog"
        aria-modal="true"
        aria-labelledby="lux-ticket-drawer-title"
        onClick={(e) => e.stopPropagation()}
      >
        <span className="lux-ticket-drawer__accent" aria-hidden="true" />

        <header className="lux-ticket-drawer__head">
          <div className="lux-ticket-drawer__head-main">
            <span className="lux-ticket-drawer__category-icon" aria-hidden="true">
              <i className="fe fe-life-buoy" />
            </span>
            <div className="lux-ticket-drawer__head-copy">
              <span className="lux-ticket-drawer__eyebrow">{ticket.number} · {ticket.queueLabel}</span>
              <h2 id="lux-ticket-drawer-title">{ticket.title}</h2>
              <div className="lux-ticket-drawer__badges">
                <TicketStatusBadge status={ticket.status} />
                <TicketPriorityBadge priority={ticket.priority} />
                <TicketSlaBadge slaStatus={ticket.slaStatus} />
              </div>
            </div>
          </div>
          <button type="button" className="lux-ticket-drawer__close" onClick={onClose} aria-label="Close">
            <i className="fe fe-x" aria-hidden="true" />
          </button>
        </header>

        <div className="lux-ticket-drawer__body">
          <p className="lux-ticket-drawer__lede">{ticket.description}</p>

          <div className="lux-ticket-drawer__metrics">
            <article>
              <span>Billable</span>
              <strong>{ticket.billableHours}h</strong>
            </article>
            <article>
              <span>Effort</span>
              <strong>{ticket.effortHours}h</strong>
            </article>
            <article>
              <span>Client</span>
              <strong>{ticket.clientName || "—"}</strong>
            </article>
          </div>

          <TicketAiPanel suggestion={aiSuggestion} loading={aiLoading} />

          <section className="lux-ticket-drawer__section">
            <h3>Links</h3>
            <dl className="lux-ticket-drawer__facts">
              <div>
                <dt>Project</dt>
                <dd>{ticket.projectName || "—"}</dd>
              </div>
              <div>
                <dt>Work item</dt>
                <dd>{ticket.linkedWorkItemId || "—"}</dd>
              </div>
              <div>
                <dt>Timesheet</dt>
                <dd>{ticket.linkedTimesheetId || "—"}</dd>
              </div>
              <div>
                <dt>External</dt>
                <dd>{ticket.externalRef ? `${ticket.externalSource}: ${ticket.externalRef}` : "Internal"}</dd>
              </div>
              <div>
                <dt>Assignee</dt>
                <dd>{ticket.assigneeName || "Unassigned"}</dd>
              </div>
              <div>
                <dt>Requester</dt>
                <dd>{ticket.requesterName || "—"}</dd>
              </div>
            </dl>
          </section>
        </div>

        <footer className="lux-ticket-drawer__footer">
          <TicketActionButton variant="ghost" icon="fe fe-arrow-up" disabled={busy} onClick={() => onEscalate && onEscalate(ticket)}>
            Escalate
          </TicketActionButton>
          <TicketActionButton icon="fe fe-check" disabled={busy} onClick={() => onResolve && onResolve(ticket)}>
            Resolve
          </TicketActionButton>
        </footer>
      </aside>
    </div>,
    document.body
  );
}
