import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";
import { sanitizeUiCopy } from "_helpers/ui-copy.utils";

/**
 * Project-list style Insights shell for admin consoles.
 * Reuses lux-bid-summary / lux-po-summary layout: header, collapsed strip,
 * KPI strip, highlights, mix-bar insights, series panels, optional children.
 */
class AdminInsightsSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      expanded: readSummaryExpanded(props.storageKey, props.defaultExpanded !== false),
    };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(this.props.storageKey, this.state.expanded)
    );
  };

  renderKpiStrip = (kpis) => {
    if (!kpis || kpis.length === 0) return null;
    return (
      <div className="lux-bid-summary__kpi-strip" role="list" aria-label="Insight metrics">
        {kpis.map((kpi) => (
          <article
            key={kpi.key || kpi.id || kpi.label}
            className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
            role="listitem"
          >
            <div className="lux-bid-summary__kpi-top">
              <span className="lux-bid-summary__kpi-label">{sanitizeUiCopy(kpi.label)}</span>
              {kpi.icon ? (
                <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
                  <i className={kpi.icon} />
                </span>
              ) : null}
            </div>
            <strong className="lux-bid-summary__kpi-value">
              {typeof kpi.value === "number" ? (
                <CountUp end={kpi.value} duration={0.75} decimals={kpi.decimals || 0} suffix={kpi.suffix || ""} />
              ) : (
                sanitizeUiCopy(kpi.value)
              )}
            </strong>
            {kpi.hint ? <span className="lux-bid-summary__kpi-hint">{sanitizeUiCopy(kpi.hint)}</span> : null}
          </article>
        ))}
      </div>
    );
  };

  renderHighlights = (highlights) => {
    if (!highlights || highlights.length === 0) return null;
    return (
      <div className="lux-po-summary__highlights" role="list" aria-label="Highlights">
        {highlights.map((item) => (
          <article
            key={item.key || item.id || item.label}
            className={classNames("lux-po-summary__highlight", item.tone && `is-${item.tone}`)}
            role="listitem"
          >
            {item.icon ? (
              <span className="lux-po-summary__highlight-icon" aria-hidden="true">
                <i className={item.icon} />
              </span>
            ) : null}
            <div className="lux-po-summary__highlight-copy">
              <span className="lux-po-summary__highlight-label">{sanitizeUiCopy(item.label)}</span>
              <strong>
                {typeof item.value === "number" ? (
                  <CountUp end={item.value} duration={0.7} decimals={item.decimals || 0} />
                ) : (
                  sanitizeUiCopy(item.value)
                )}
                {item.suffix || ""}
              </strong>
              {item.hint ? (
                <span className="lux-po-summary__highlight-hint">{sanitizeUiCopy(item.hint)}</span>
              ) : null}
            </div>
          </article>
        ))}
      </div>
    );
  };

  renderMixInsight = (insight) => (
    <article
      key={insight.key || insight.id}
      className="lux-bid-summary__insight lux-po-summary__insight lux-admin-summary__insight"
    >
      <header>
        <i className={insight.icon || "fe fe-info"} aria-hidden="true" />
        <div>
          <strong>{sanitizeUiCopy(insight.title)}</strong>
          <span>{sanitizeUiCopy(insight.subtitle || insight.copy || "")}</span>
        </div>
      </header>
      {!insight.mix || insight.mix.length === 0 ? (
        <div className="lux-bid-summary__bar lux-bid-summary__bar--empty">
          {sanitizeUiCopy(insight.emptyLabel || "No mix data yet")}
        </div>
      ) : (
        <>
          <div className="lux-bid-summary__bar" aria-hidden="true">
            {insight.mix.map((seg) => (
              <span
                key={seg.key || seg.label}
                className={classNames("lux-bid-summary__bar-segment", `is-${seg.tone || "slate"}`)}
                style={{ flexGrow: Math.max(seg.count || seg.value || 0.15, 0.15) }}
                title={`${seg.label}: ${seg.count != null ? seg.count : seg.value}`}
              />
            ))}
          </div>
          <ul className="lux-bid-summary__legend">
            {insight.mix.map((seg) => (
              <li key={seg.key || seg.label}>
                <span className={classNames("lux-bid-summary__legend-dot", `is-${seg.tone || "slate"}`)} />
                <span>{sanitizeUiCopy(seg.label)}</span>
                <strong>{seg.count != null ? seg.count : seg.value}</strong>
                {seg.pct != null ? <em>{seg.pct}%</em> : null}
              </li>
            ))}
          </ul>
        </>
      )}
    </article>
  );

  renderAttention = (attention) => {
    if (!attention || attention.length === 0) return null;
    return (
      <div className="lux-admin-summary__attention" role="list" aria-label="Attention items">
        {attention.map((item) => (
          <article
            key={item.id || item.key || item.title}
            className={classNames("lux-admin-summary__attention-card", item.tone && `is-${item.tone}`)}
            role="listitem"
          >
            <span className="lux-admin-summary__attention-icon" aria-hidden="true">
              <i className={item.icon || "fe fe-info"} />
            </span>
            <div className="lux-admin-summary__attention-copy">
              <div className="lux-admin-summary__attention-top">
                {item.eyebrow ? <span>{sanitizeUiCopy(item.eyebrow)}</span> : null}
                {item.stat != null ? <strong>{sanitizeUiCopy(String(item.stat))}</strong> : null}
              </div>
              <strong>{sanitizeUiCopy(item.title)}</strong>
              <p>{sanitizeUiCopy(item.copy || item.body || item.detail)}</p>
              {item.hint ? <em>{sanitizeUiCopy(item.hint)}</em> : null}
            </div>
          </article>
        ))}
      </div>
    );
  };

  renderSeriesPanel = (panel) => {
    const rows = panel.rows || [];
    return (
      <article
        key={panel.id || panel.title}
        className={classNames(
          "lux-bid-summary__chart-panel",
          "lux-admin-summary__series-panel",
          panel.wide && "lux-bid-summary__chart-panel--wide"
        )}
      >
        <div className="lux-bid-summary__panel-head">
          <div>
            <h3 className="lux-bid-summary__panel-title">{sanitizeUiCopy(panel.title)}</h3>
            {panel.subtitle ? (
              <p className="lux-bid-summary__panel-sub">{sanitizeUiCopy(panel.subtitle)}</p>
            ) : null}
          </div>
        </div>
        <div className="lux-bid-summary__chart-body">
          {rows.length === 0 ? (
            <p className="lux-bid-summary__chart-empty">
              {sanitizeUiCopy(panel.emptyLabel || "No distribution data yet")}
            </p>
          ) : (
            <ul className="lux-admin-summary__series" role="list">
              {rows.map((row) => {
                const pct =
                  row.pct != null
                    ? row.pct
                    : row.total > 0
                      ? Math.round(((row.value || row.count || 0) / row.total) * 100)
                      : 0;
                return (
                  <li key={row.key || row.label} className="lux-admin-summary__series-row" role="listitem">
                    <div className="lux-admin-summary__series-label">
                      {row.icon ? (
                        <span
                          className={classNames(
                            "lux-admin-summary__series-icon",
                            row.tone && `is-${row.tone}`
                          )}
                        >
                          <i className={row.icon} aria-hidden="true" />
                        </span>
                      ) : null}
                      <span>{sanitizeUiCopy(row.label)}</span>
                      <em>
                        {row.meta != null
                          ? row.meta
                          : row.total != null
                            ? `${row.value != null ? row.value : row.count}/${row.total}`
                            : row.value != null
                              ? row.value
                              : row.count}
                      </em>
                    </div>
                    <div className="lux-admin-summary__series-track" aria-hidden="true">
                      <span
                        className={classNames(
                          "lux-admin-summary__series-fill",
                          row.tone && `is-${row.tone}`
                        )}
                        style={{ width: `${Math.max(pct, row.value || row.count ? 6 : 0)}%` }}
                      />
                    </div>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      </article>
    );
  };

  renderSkeleton = () => (
    <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
      <div
        className={classNames(
          "lux-bid-summary",
          "lux-po-summary",
          "lux-admin-summary",
          this.props.domainClass,
          "is-loading"
        )}
      >
        <Skeleton height={72} borderRadius={16} />
        <div className="lux-bid-summary__kpi-strip lux-bid-summary__kpi-strip--skeleton">
          {[1, 2, 3, 4].map((key) => (
            <Skeleton key={key} height={72} borderRadius={14} />
          ))}
        </div>
      </div>
    </SkeletonTheme>
  );

  render() {
    const {
      loading,
      eyebrow,
      eyebrowIcon,
      eyebrowVariant,
      title,
      compactTitle,
      collapsedLine,
      subtitle,
      kpis,
      highlights,
      mixInsights,
      attention,
      series,
      children,
      domainClass,
      testId,
      ariaLabel,
    } = this.props;
    const { expanded } = this.state;

    if (loading) {
      return this.renderSkeleton();
    }

    return (
      <section
        className={classNames(
          "lux-bid-summary",
          "lux-po-summary",
          "lux-admin-summary",
          domainClass,
          { "is-collapsed": !expanded }
        )}
        aria-label={ariaLabel || title || "Insights"}
        data-surface="lux-summary"
        data-testid={testId || "admin-insights-summary"}
      >
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow
              variant={eyebrowVariant}
              icon={eyebrowIcon}
              className="lux-bid-summary__eyebrow"
            >
              {eyebrow || "Governance intelligence"}
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                {compactTitle || title}
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">{title}</h2>
            )}
          </div>
          <button
            type="button"
            className="lux-bid-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-admin-insights-summary-body"
            data-testid="admin-insights-toggle"
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i
              className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")}
              aria-hidden="true"
            />
          </button>
        </div>

        {!expanded && (collapsedLine || subtitle) ? (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">{collapsedLine || subtitle}</p>
          </div>
        ) : null}

        <div
          id="lux-admin-insights-summary-body"
          className="lux-bid-summary__body"
          aria-hidden={!expanded}
        >
          {(subtitle || collapsedLine) && expanded ? (
            <div className="lux-bid-summary__toolbar">
              <p className="lux-bid-summary__subtitle">{subtitle || collapsedLine}</p>
            </div>
          ) : null}

          <div className="lux-bid-summary__metrics-row lux-po-summary__metrics-row lux-admin-summary__metrics-row">
            {this.renderKpiStrip(kpis)}
          </div>

          {this.renderHighlights(highlights)}
          {this.renderAttention(attention)}

          {mixInsights && mixInsights.length > 0 ? (
            <div className="lux-bid-summary__insights lux-po-summary__insights">
              {mixInsights.map(this.renderMixInsight)}
            </div>
          ) : null}

          {series && series.length > 0 ? (
            <div className="lux-po-summary__analytics lux-po-summary__analytics--primary lux-admin-summary__analytics">
              {series.map(this.renderSeriesPanel)}
            </div>
          ) : null}

          {children ? <div className="lux-admin-summary__extra">{children}</div> : null}
        </div>
      </section>
    );
  }
}

export default AdminInsightsSummary;
