import React from "react";
import classNames from "classnames/bind";
import { CHANGE_REQUEST_STATUSES } from "config/project-governance.config";
import { getChangeStatusTone } from "config/project-governance.utils";

export default function ChangeRequestRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-gov-register-wrap">
      <table className="lux-gov-register lux-gov-register--changes">
        <thead>
          <tr>
            <th>Change</th>
            <th>Project</th>
            <th>Requested by</th>
            <th>Submitted</th>
            <th>Impact</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const tone = getChangeStatusTone(row.status);
            const isPending = row.status === CHANGE_REQUEST_STATUSES.SUBMITTED;
            return (
              <tr
                key={row.id}
                className={classNames("lux-gov-register__row", { "is-critical": isPending })}
              >
                <td>
                  <button type="button" className="lux-gov-register__link" onClick={() => onSelect && onSelect(row)}>
                    <strong>{row.title}</strong>
                    {row.proposedScope ? <span>{row.proposedScope}</span> : null}
                  </button>
                </td>
                <td>
                  <span className="lux-gov-register__project">{row.projectName}</span>
                  {row.projectCode ? <span className="lux-gov-register__meta">{row.projectCode}</span> : null}
                </td>
                <td>{row.requestedBy || "—"}</td>
                <td>{row.submittedAt || "—"}</td>
                <td>{row.impactSummary || "—"}</td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${tone}`)}>{row.status}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
