import {
  API_NOT_FOUND_MESSAGE,
  getApiErrorMessage,
  getApiErrorStatus,
  isApiNotFoundError,
} from "./apiError.utils";

const REGISTER_FETCH_FALLBACK =
  "Something went wrong while loading data. Please try again.";

export function formatRegisterFetchError(error) {
  return getApiErrorMessage(error, REGISTER_FETCH_FALLBACK);
}

export function isRegisterNotFoundError(error) {
  return isApiNotFoundError(error);
}

export function shouldShowRegisterFetchError({ error, isLoading, items }) {
  if (!error || isLoading || isRegisterNotFoundError(error)) {
    return false;
  }
  if (items == null) {
    return true;
  }
  return Array.isArray(items) ? items.length === 0 : false;
}

export function shouldShowRegisterEmptyState({ error, isLoading, items }) {
  if (isLoading) {
    return false;
  }
  const hasItems = Array.isArray(items) ? items.length > 0 : !!items;
  if (hasItems) {
    return false;
  }
  if (!error) {
    return true;
  }
  return isRegisterNotFoundError(error);
}

export function getRegisterEmptyCopy(error, defaults = {}) {
  if (isRegisterNotFoundError(error)) {
    return {
      eyebrow: defaults.eyebrow,
      title: defaults.notFoundTitle || API_NOT_FOUND_MESSAGE,
      description:
        defaults.notFoundDescription ||
        "Nothing is available for the selected teams, date range, or filters.",
    };
  }
  return {
    eyebrow: defaults.eyebrow,
    title: defaults.title,
    description: defaults.description,
  };
}

export function shouldHideRegisterOnLoadError(error, items) {
  if (!error) {
    return false;
  }
  const hasItems = Array.isArray(items) ? items.length > 0 : Boolean(items);
  return !hasItems;
}

export function isRegisterConnectionError(error) {
  if (!error || isRegisterNotFoundError(error)) {
    return false;
  }
  const status = getApiErrorStatus(error);
  if (status == null) {
    return true;
  }
  return [0, 502, 503, 504].includes(status);
}
