import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { findNodeInOrgTree, getEmployeeInitials } from "config/org-structure.utils";

function OrgChartNode({ node, selectedId, onSelect, depth }) {
  const isSelected = selectedId === node.id;
  const hasChildren = node.children && node.children.length > 0;

  return (
    <li className={classNames("lux-org-chart__branch", depth > 0 && "has-parent")}>
      <button
        type="button"
        className={classNames("lux-org-chart__node", { "is-selected": isSelected })}
        onClick={() => onSelect(node)}
        aria-pressed={isSelected}
      >
        <span className="lux-org-chart__node-avatar" aria-hidden="true">
          {getEmployeeInitials(node.name)}
        </span>
        <span className="lux-org-chart__node-copy">
          <strong>{node.name}</strong>
          <small>{node.designation}</small>
          <span className="lux-org-chart__node-meta">
            {node.department}
            {node.directReports > 0 && ` · ${node.directReports} report${node.directReports === 1 ? "" : "s"}`}
          </span>
        </span>
      </button>
      {hasChildren && (
        <ul className="lux-org-chart__children">
          {node.children.map((child) => (
            <OrgChartNode
              key={child.id}
              node={child}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={depth + 1}
            />
          ))}
        </ul>
      )}
    </li>
  );
}

export default function OrgChartTree({ tree, selectedId, onSelect, selectedNode }) {
  if (!tree || tree.length === 0) {
    return null;
  }

  return (
    <div className="lux-org-chart__layout">
      <div className="lux-org-chart__canvas" role="tree" aria-label="Organization reporting hierarchy">
        <ul className="lux-org-chart__tree">
          {tree.map((node) => (
            <OrgChartNode
              key={node.id}
              node={node}
              selectedId={selectedId}
              onSelect={onSelect}
              depth={0}
            />
          ))}
        </ul>
      </div>

      {selectedNode && (
        <aside className="lux-org-chart__detail" aria-label="Selected employee details">
          <header className="lux-org-chart__detail-head">
            <span className="lux-org-chart__detail-avatar" aria-hidden="true">
              {getEmployeeInitials(selectedNode.name)}
            </span>
            <div>
              <h3>{selectedNode.name}</h3>
              <p>{selectedNode.designation}</p>
            </div>
          </header>
          <dl className="lux-org-chart__detail-grid">
            <div>
              <dt>Department</dt>
              <dd>{selectedNode.department || "—"}</dd>
            </div>
            <div>
              <dt>Location</dt>
              <dd>{selectedNode.location || "—"}</dd>
            </div>
            <div>
              <dt>Manager</dt>
              <dd>{selectedNode.managerName && selectedNode.managerName !== "—" ? selectedNode.managerName : "—"}</dd>
            </div>
            <div>
              <dt>Direct reports</dt>
              <dd>{selectedNode.directReports || 0}</dd>
            </div>
            <div>
              <dt>Status</dt>
              <dd>{selectedNode.status || "Active"}</dd>
            </div>
          </dl>
          <div className="lux-org-chart__detail-actions">
            <Link to={`/people/employees/${selectedNode.id}/360`} className="lux-org-chart__detail-link">
              <i className="fe fe-user" aria-hidden="true" />
              Employee 360
            </Link>
            {selectedNode.managerName && selectedNode.managerName !== "—" && (
              <button
                type="button"
                className="lux-org-chart__detail-link is-ghost"
                onClick={() => {
                  const manager = findNodeInOrgTree(tree, (row) => row.name === selectedNode.managerName);
                  if (manager) {
                    onSelect(manager);
                  }
                }}
              >
                <i className="fe fe-arrow-up" aria-hidden="true" />
                View manager
              </button>
            )}
          </div>
        </aside>
      )}
    </div>
  );
}
