import React, { Component } from "react";
import classNames from "classnames/bind";

const SOURCE_LABELS = {
  api: "Live",
  client: "Client computed",
  mock: "Demo",
};

export default class TimesheetAgentDraftPanel extends Component {
  handleAction = (action) => {
    const { onAction, recommendation, actionInProgress } = this.props;
    if (actionInProgress || (recommendation && recommendation.decision)) {
      return;
    }
    if (onAction) {
      onAction(action, recommendation);
    }
  };

  render() {
    const { recommendation, actionLog, source, actionInProgress } = this.props;
    if (!recommendation) {
      return null;
    }

    const statusLabel = SOURCE_LABELS[source] || (source ? String(source) : "Ready");
    const decision = recommendation.decision;
    const decided = Boolean(decision);

    return (
      <section className="lux-ts-intel__agent" aria-label="Agent draft workflow">
        <header className="lux-ts-intel__agent-head">
          <div>
            <span className="lux-ts-intel__agent-kicker">
              <i className="fe fe-cpu" aria-hidden="true" />
              AI agent workflow
            </span>
            <h4>Accept, reject, or defer</h4>
          </div>
          <span
            className={classNames("lux-ts-intel__agent-badge", {
              "is-live": source === "api",
              "is-client": source === "client",
              "is-decided": decided,
            })}
          >
            {decided ? `Decided · ${decision}` : statusLabel}
          </span>
        </header>

        {recommendation.summary && (
          <p className="lux-ts-intel__agent-context">{recommendation.summary}</p>
        )}
        <p className="lux-ts-intel__agent-summary">{recommendation.recommendation}</p>

        {Array.isArray(recommendation.evidence) && recommendation.evidence.length > 0 && (
          <ul className="lux-ts-intel__agent-evidence" aria-label="Evidence">
            {recommendation.evidence.map((row) => (
              <li key={row}>{row}</li>
            ))}
          </ul>
        )}

        {recommendation.nextStep && !decided && (
          <p className="lux-ts-intel__agent-next">
            <i className="fe fe-arrow-right-circle" aria-hidden="true" />
            {recommendation.nextStep}
          </p>
        )}

        {decided ? (
          <div className={classNames("lux-ts-intel__agent-decided", `is-${decision}`)} role="status">
            <strong>{decision}</strong>
            <span>{recommendation.decisionMessage || `This recommendation was ${decision}.`}</span>
            {decision === "accept" && recommendation.nextStep ? (
              <em>{recommendation.nextStep}</em>
            ) : null}
          </div>
        ) : (
          <div className="lux-ts-intel__agent-actions">
            <button
              type="button"
              className="lux-ts-intel__agent-btn is-accept"
              disabled={actionInProgress}
              onClick={() => this.handleAction("accept")}
            >
              <i className="fe fe-check" aria-hidden="true" />
              Accept
            </button>
            <button
              type="button"
              className="lux-ts-intel__agent-btn is-reject"
              disabled={actionInProgress}
              onClick={() => this.handleAction("reject")}
            >
              <i className="fe fe-x" aria-hidden="true" />
              Reject
            </button>
            <button
              type="button"
              className="lux-ts-intel__agent-btn is-defer"
              disabled={actionInProgress}
              onClick={() => this.handleAction("defer")}
            >
              <i className="fe fe-clock" aria-hidden="true" />
              Defer
            </button>
          </div>
        )}

        {actionLog && actionLog.length > 0 && (
          <ul className="lux-ts-intel__agent-log">
            {actionLog.slice(0, 3).map((entry) => (
              <li key={entry.at} className={classNames("lux-ts-intel__agent-log-item", `is-${entry.action}`)}>
                <strong>{entry.action}</strong>
                <span>{entry.message}</span>
              </li>
            ))}
          </ul>
        )}

        {recommendation.disclaimer && !decided && (
          <p className="lux-ts-intel__agent-disclaimer">{recommendation.disclaimer}</p>
        )}
      </section>
    );
  }
}
