import React, { useCallback, useEffect, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { commonUtils } from "_helpers";
import { appConfigService } from "_services/appconfig.service";
import { employeeService } from "_services/employee.service";
import { onboardingService } from "_services/onboarding.service";
import {
  buildConvertPreviewFromCase,
  extractConvertErrorMessage,
  isConvertSuccessPayload,
} from "config/onboarding.utils";
import LifecycleActionLink from "./LifecycleActionLink";

const DRAWER_CLOSE_MS = 280;

function normalizeRoleList(rolesRes) {
  const payload = rolesRes && rolesRes.payload;
  if (!payload) {
    return [];
  }
  if (Array.isArray(payload)) {
    return payload
      .filter((role) => role && role.id != null)
      .map((role) => ({
        id: role.id,
        name: role.name || role.label || `Role ${role.id}`,
      }));
  }
  const grouped = Array.isArray(payload) ? payload : [payload];
  return commonUtils.getSubRoles(grouped, commonUtils.getCurrentUserRoleId());
}

function normalizeTeamList(teamsRes) {
  const payload = teamsRes && teamsRes.payload;
  if (!payload) {
    return [];
  }
  const raw = Array.isArray(payload) ? payload : [payload];
  return raw
    .filter((team) => team && team.id != null)
    .map((team) => ({
      id: team.id,
      name: team.name || team.label || `Team ${team.id}`,
    }));
}

function normalizeEmployeeList(employeesRes) {
  const payload = employeesRes && employeesRes.payload;
  const raw = Array.isArray(payload) ? payload : payload ? [payload] : [];
  return raw
    .filter((employee) => employee && employee.id != null)
    .map((employee) => ({
      id: employee.id,
      name: employee.name || employee.email || `Employee ${employee.id}`,
    }));
}

function resolveDefaultManagerId(preview, caseData) {
  if (preview && preview.managerId != null) {
    return String(preview.managerId);
  }
  if (caseData && caseData.managerId != null) {
    return String(caseData.managerId);
  }
  return "";
}

function resolveDefaultTeamId(preview, caseData) {
  if (preview && preview.userTeamId != null) {
    return String(preview.userTeamId);
  }
  if (caseData && caseData.userTeamId != null) {
    return String(caseData.userTeamId);
  }
  const currentTeamId = commonUtils.getCurrentUserTeamId();
  return currentTeamId != null ? String(currentTeamId) : "";
}

function PreviewField({ label, value }) {
  return (
    <div className="lux-onb-convert__field">
      <span className="lux-onb-convert__field-label">{label}</span>
      <span className="lux-onb-convert__field-value">{value || "—"}</span>
    </div>
  );
}

function ConvertToEmployeePanel({ caseData, open, onClose, onConverted }) {
  const [preview, setPreview] = useState(null);
  const [roles, setRoles] = useState([]);
  const [teams, setTeams] = useState([]);
  const [managers, setManagers] = useState([]);
  const [selectedRoleId, setSelectedRoleId] = useState("");
  const [selectedTeamId, setSelectedTeamId] = useState("");
  const [selectedManagerId, setSelectedManagerId] = useState("");
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [closing, setClosing] = useState(false);

  const requestClose = useCallback(() => {
    setClosing(true);
    window.setTimeout(() => {
      setClosing(false);
      setSuccess(null);
      setError(null);
      onClose();
    }, DRAWER_CLOSE_MS);
  }, [onClose]);

  useEffect(() => {
    if (!open || !caseData) {
      return undefined;
    }
    let cancelled = false;
    setLoading(true);
    setError(null);
    setSuccess(null);

    Promise.all([
      onboardingService.getOnboardingConvertPreview(caseData.id),
      appConfigService.getAllRoles(false),
      appConfigService.getAllTeams(false),
      employeeService.getAllEmployees(),
    ])
      .then(([previewRes, rolesRes, teamsRes, employeesRes]) => {
        if (cancelled) {
          return;
        }
        const payload =
          previewRes.payload || buildConvertPreviewFromCase(caseData);
        setPreview(payload);
        const roleList = normalizeRoleList(rolesRes);
        const teamList = normalizeTeamList(teamsRes);
        setRoles(roleList);
        setTeams(teamList);
        const managerList = normalizeEmployeeList(employeesRes);
        setManagers(managerList);
        const defaultRoleId =
          commonUtils.getCurrentUserRoleId() ||
          (roleList.length ? roleList[0].id : "");
        if (defaultRoleId) {
          setSelectedRoleId(String(defaultRoleId));
        }
        const defaultTeamId = resolveDefaultTeamId(payload, caseData);
        if (defaultTeamId) {
          setSelectedTeamId(defaultTeamId);
        } else if (teamList.length) {
          setSelectedTeamId(String(teamList[0].id));
        }
        const defaultManagerId = resolveDefaultManagerId(payload, caseData);
        if (defaultManagerId) {
          setSelectedManagerId(defaultManagerId);
        } else if (managerList.length) {
          setSelectedManagerId(String(managerList[0].id));
        }
        setLoading(false);
      })
      .catch(() => {
        if (!cancelled) {
          const fallbackPreview = buildConvertPreviewFromCase(caseData);
          setPreview(fallbackPreview);
          setRoles([]);
          setTeams([]);
          const defaultTeamId = resolveDefaultTeamId(fallbackPreview, caseData);
          if (defaultTeamId) {
            setSelectedTeamId(defaultTeamId);
          }
          setLoading(false);
        }
      });

    return () => {
      cancelled = true;
    };
  }, [open, caseData]);

  const handleConvert = async () => {
    if (!caseData || !selectedRoleId || !selectedTeamId || submitting) {
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      const res = await onboardingService.convertOnboardingCase(
        caseData.id,
        Number(selectedRoleId),
        Number(selectedTeamId),
        selectedManagerId ? Number(selectedManagerId) : null
      );
      if (isConvertSuccessPayload(res.payload)) {
        setSuccess(res.payload);
        if (onConverted) {
          onConverted(res.payload);
        }
      } else {
        setError(extractConvertErrorMessage(null, res.payload));
      }
    } catch (convertError) {
      setError(extractConvertErrorMessage(convertError, preview));
    } finally {
      setSubmitting(false);
    }
  };

  if (!open && !closing) {
    return null;
  }

  const selectedTeam = teams.find((team) => String(team.id) === String(selectedTeamId));
  const selectedTeamName = selectedTeam && selectedTeam.name;

  const canSubmit =
    preview &&
    preview.canConvert &&
    selectedRoleId &&
    selectedTeamId &&
    !submitting &&
    !success;

  const panel = (
    <div
      className={classNames("lux-onb-drawer-backdrop", { "is-closing": closing })}
      role="presentation"
      onClick={requestClose}
    >
      <aside
        className={classNames(
          "lux-onb-drawer lux-onb-drawer--primary lux-onb-convert",
          { "is-closing": closing }
        )}
        role="dialog"
        aria-labelledby="lux-onb-convert-title"
        onClick={(event) => event.stopPropagation()}
      >
        <header className="lux-onb-drawer__head">
          <div className="lux-onb-drawer__head-copy">
            <span className="lux-onb-drawer__eyebrow">People · Onboarding</span>
            <h2 id="lux-onb-convert-title">Convert to employee</h2>
            <p className="lux-onb-drawer__task-id">
              Create the HRIS employee record from this onboarding case.
            </p>
          </div>
          <button
            type="button"
            className="lux-onb-drawer__close"
            aria-label="Close"
            onClick={requestClose}
          >
            <i className="fe fe-x" aria-hidden />
          </button>
        </header>

        <div className="lux-onb-drawer__body lux-onb-convert__body">
          {loading && <p className="lux-onb-convert__loading">Loading preview…</p>}

          {!loading && preview && !success && (
            <>
              {preview.blockers && preview.blockers.length > 0 && (
                <div className="lux-onb-convert__blockers" role="alert">
                  <i className="fe fe-alert-circle" aria-hidden />
                  <ul>
                    {preview.blockers.map((item) => (
                      <li key={item}>{item}</li>
                    ))}
                  </ul>
                </div>
              )}

              <div className="lux-onb-convert__grid">
                <PreviewField label="Name" value={preview.name} />
                <PreviewField label="Email" value={preview.email} />
                <PreviewField label="Role" value={preview.designation} />
                <PreviewField label="Department" value={preview.department} />
                <PreviewField label="Location" value={preview.location} />
                <PreviewField label="Start date" value={preview.dateOfJoin} />
                <PreviewField label="Manager" value={preview.managerName} />
                {selectedTeamName && (
                  <PreviewField label="Default team" value={selectedTeamName} />
                )}
              </div>

              <label className="lux-onb-convert__role">
                <span>Reporting manager</span>
                <select
                  value={selectedManagerId}
                  onChange={(e) => setSelectedManagerId(e.target.value)}
                  disabled={!preview.canConvert || managers.length === 0}
                >
                  <option value="">Select manager (optional)</option>
                  {(Array.isArray(managers) ? managers : []).map((manager) => (
                    <option key={manager.id} value={manager.id}>
                      {manager.name}
                    </option>
                  ))}
                </select>
              </label>

              <label className="lux-onb-convert__role">
                <span>Default user team</span>
                <select
                  value={selectedTeamId}
                  onChange={(e) => setSelectedTeamId(e.target.value)}
                  disabled={!preview.canConvert || teams.length === 0}
                >
                  {teams.length === 0 && <option value="">No teams available</option>}
                  {(Array.isArray(teams) ? teams : []).map((team) => (
                    <option key={team.id} value={team.id}>
                      {team.name}
                    </option>
                  ))}
                </select>
              </label>

              <label className="lux-onb-convert__role">
                <span>Employee access role</span>
                <select
                  value={selectedRoleId}
                  onChange={(e) => setSelectedRoleId(e.target.value)}
                  disabled={!preview.canConvert}
                >
                  {(Array.isArray(roles) ? roles : []).map((role) => (
                    <option key={role.id} value={role.id}>
                      {role.name || role.label}
                    </option>
                  ))}
                </select>
              </label>

              {error && <p className="lux-onb-convert__error">{error}</p>}
            </>
          )}

          {success && (
            <div className="lux-onb-convert__success">
              <i className="fe fe-check-circle" aria-hidden />
              <h3>Employee created</h3>
              <p>
                <strong>{success.employeeName}</strong> ({success.employeeEmail}) is now in the
                employee register.
              </p>
              <div className="lux-onb-convert__success-actions">
                <LifecycleActionLink to="/people/employees" variant="primary" icon="fe-users">
                  Open employees
                </LifecycleActionLink>
                {success.employeeId && (
                  <Link
                    className="lux-onb-action lux-onb-action--ghost"
                    to={`/employees/${success.employeeId}/360`}
                  >
                    View profile
                  </Link>
                )}
              </div>
            </div>
          )}
        </div>

        {!success && (
          <footer className="lux-onb-drawer__foot">
            <LifecycleActionLink variant="ghost" onClick={requestClose}>
              Cancel
            </LifecycleActionLink>
            <LifecycleActionLink
              variant="primary"
              icon="fe-user-plus"
              onClick={handleConvert}
              disabled={!canSubmit}
            >
              {submitting ? "Creating…" : "Create employee"}
            </LifecycleActionLink>
          </footer>
        )}
      </aside>
    </div>
  );

  return createPortal(panel, document.body);
}

export default ConvertToEmployeePanel;
