import { leaveConstants } from '_constants/leave.constants';
import { notificationActions } from './notification.actions';
import { leaveService } from '_services/leave.service';
import { getApiErrorMessage } from '_helpers';

export const leaveActions = {
  loadEmployeeLeaves,
  loadPendingLeaves,
  createAndSubmitLeave,
  submitLeave,
  approveLeave,
  rejectLeave,
  promoteLeave,
};

function extractServiceError(response) {
  if (!response || !response.error) {
    return null;
  }
  const first = Array.isArray(response.error) ? response.error[0] : response.error;
  if (!first) {
    return null;
  }
  if (typeof first === 'string') {
    return first;
  }
  return first.message || first.code || 'Request failed';
}

function assertServiceSuccess(response, fallbackMessage) {
  const serviceError = extractServiceError(response);
  if (serviceError) {
    const error = new Error(serviceError);
    error.response = { data: response, status: 200 };
    throw error;
  }
  return response;
}

function loadEmployeeLeaves(employeeId, callback) {
  return (dispatch) => {
    dispatch(request());
    leaveService
      .listByEmployee(employeeId)
      .then(
        (response) => {
          assertServiceSuccess(response, 'Unable to load leaves');
          const leaves = (response && response.payload) || [];
          dispatch(success(leaves));
          if (callback) callback(leaves);
        },
        (error) => {
          dispatch(failure(resolveErrorMessage(error)));
          if (callback) callback(null);
        }
      )
      .catch((error) => {
        dispatch(failure(resolveErrorMessage(error)));
        if (callback) callback(null);
      });
  };

  function request() {
    return { type: leaveConstants.LOAD_LEAVES_REQUEST };
  }
  function success(leaves) {
    return { type: leaveConstants.LOAD_LEAVES_SUCCESS, leaves };
  }
  function failure(error) {
    return { type: leaveConstants.LOAD_LEAVES_FAILURE, error };
  }
}

