function createAndSubmitLeave(payload, actorId, callback) {
  return (dispatch) => {
    dispatch({ type: leaveConstants.CREATE_LEAVE_REQUEST });
    leaveService
      .createLeave(payload)
      .then((createResponse) => {
        assertServiceSuccess(createResponse, 'Leave was not created');
        const created = createResponse && createResponse.payload;
        const leaveId = created && created.id;
        if (!leaveId) {
          throw new Error('Leave was not created');
        }
        return leaveService
          .submitLeave(leaveId, actorId)
          .then((submitResponse) => {
            assertServiceSuccess(submitResponse, 'Leave was created but could not be submitted');
            return { mode: 'submitted', leaveId };
          })
          .catch((submitError) => {
            // Create succeeded — leave remains CREATED so proof can be linked, then Submit from history.
            return {
              mode: 'draft',
              leaveId,
              message: resolveErrorMessage(submitError),
            };
          });
      })
      .then(
        (result) => {
          dispatch({ type: leaveConstants.CREATE_LEAVE_SUCCESS });
          if (result && result.mode === 'draft') {
            const detail = result.message
              ? ` ${result.message}`
              : '';
            dispatch(
              notificationActions.warning(
                `Leave saved as draft.${detail} Link required proof under Leave → Document review, then Submit from My leave history.`
              )
            );
            if (callback) callback(true, result);
            return;
          }
          dispatch(notificationActions.success('Leave request submitted'));
          if (callback) callback(true, result);
        },
        (error) => {
          dispatch({
            type: leaveConstants.CREATE_LEAVE_FAILURE,
            error: resolveErrorMessage(error),
          });
          dispatch(notificationActions.error(resolveErrorMessage(error)));
          if (callback) callback(false);
        }
      );
  };
}

function submitLeave(leaveId, actorId, callback) {
  return (dispatch) => {
    dispatch({ type: leaveConstants.SUBMIT_LEAVE_REQUEST });
    leaveService
      .submitLeave(leaveId, actorId)
      .then((response) => {
        assertServiceSuccess(response, 'Unable to submit leave');
        dispatch({ type: leaveConstants.SUBMIT_LEAVE_SUCCESS });
        dispatch(notificationActions.success('Leave submitted for approval'));
        if (callback) callback(true);
      })
      .catch((error) => {
        dispatch({
          type: leaveConstants.SUBMIT_LEAVE_FAILURE,
          error: resolveErrorMessage(error),
        });
        dispatch(notificationActions.error(resolveErrorMessage(error)));
        if (callback) callback(false);
      });
  };
}

function approveLeave(leaveId, approverId, approvalComment, callback) {
  return (dispatch) => {
    dispatch({ type: leaveConstants.APPROVE_LEAVE_REQUEST });
    leaveService
      .approveLeave(leaveId, approverId, approvalComment)
      .then((response) => {
        assertServiceSuccess(response, 'Unable to approve leave');
        dispatch({ type: leaveConstants.APPROVE_LEAVE_SUCCESS });
        const leave = response && response.payload;
        const promo =
          leave &&
          String(leave.promotionStatus || leave.promotion_status || "").toUpperCase();
        const synced = leave && (leave.sync === true || leave.sync === "true");
        if (promo === "FAILED" || (promo && promo !== "SUCCESS" && !synced)) {
          dispatch(
            notificationActions.warning(
              "Leave approved, but work-item sync for utilization is pending or failed. Use Retry sync on the leave row."
            )
          );
        } else {
          dispatch(
            notificationActions.success(
              "Leave approved — TaskActivity work items created for utilization."
            )
          );
        }
        if (callback) callback(true);
      })
      .catch((error) => {
        dispatch({
          type: leaveConstants.APPROVE_LEAVE_FAILURE,
          error: resolveErrorMessage(error),
        });
        dispatch(notificationActions.error(resolveErrorMessage(error)));
        if (callback) callback(false);
      });
  };
}

function rejectLeave(leaveId, approverId, rejectionComment, callback) {
  return (dispatch) => {
    dispatch({ type: leaveConstants.REJECT_LEAVE_REQUEST });
    leaveService
      .rejectLeave(leaveId, approverId, rejectionComment)
      .then((response) => {
        assertServiceSuccess(response, 'Unable to reject leave');
        dispatch({ type: leaveConstants.REJECT_LEAVE_SUCCESS });
        dispatch(notificationActions.success('Leave rejected'));
        if (callback) callback(true);
      })
      .catch((error) => {
        dispatch({
          type: leaveConstants.REJECT_LEAVE_FAILURE,
          error: resolveErrorMessage(error),
        });
        dispatch(notificationActions.error(resolveErrorMessage(error)));
        if (callback) callback(false);
      });
  };
}

function resolveErrorMessage(error) {
  return getApiErrorMessage(error, 'Something went wrong. Please try again.');
}

function promoteLeave(leaveId, actorId, callback) {
  return (dispatch) => {
    const resolvedActorId = actorId;
    leaveService
      .promoteLeave(leaveId, resolvedActorId)
      .then((response) => {
        assertServiceSuccess(response, 'Unable to sync work items');
        dispatch(notificationActions.success('Work items synced'));
        if (callback) callback(true);
      })
      .catch((error) => {
        dispatch(notificationActions.error(resolveErrorMessage(error)));
        if (callback) callback(false);
      });
  };
}
