import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { formatFinanceUsd } from "config/finance-intelligence.utils";
import { FinanceActionButton } from "views/finance/components/FinanceLuxShared";

const STATUS_TONE = {
  PENDING: "amber",
  APPROVED: "green",
  DISMISSED: "slate",
};

export default function InvoiceRecommendationsPanel({
  recommendations = [],
  loading,
  onApprove,
  onDismiss,
  busyId,
}) {
  if (loading) {
    return <div className="lux-finance-register__skeleton" aria-busy="true" />;
  }
  if (!recommendations.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="No invoice recommendations"
        description="Billing Advice Agent recommendations will appear here when milestones are ready to invoice."
      />
    );
  }

  return (
    <div className="lux-finance-recs">
      {recommendations.map((row) => (
        <article key={row.id} className="lux-finance-rec-card">
          <header>
            <div>
              <strong>{row.projectName}</strong>
              <small>
                {row.agentSource} · {row.confidencePct}% confidence
              </small>
            </div>
            <span className={classNames("lux-portfolio-badge", `is-${STATUS_TONE[row.status] || "slate"}`)}>
              {row.status}
            </span>
          </header>
          <p>{row.rationale}</p>
          <div className="lux-finance-rec-card__meta">
            <span>{formatFinanceUsd(row.recommendedAmountUsd)}</span>
            <span>Invoice by {row.suggestedInvoiceDate || "—"}</span>
          </div>
          {row.status === "PENDING" ? (
            <div className="lux-finance-rec-card__actions">
              <FinanceActionButton
                variant="primary"
                disabled={busyId === row.id}
                onClick={() => onApprove(row.id)}
              >
                Approve
              </FinanceActionButton>
              <FinanceActionButton
                variant="ghost"
                disabled={busyId === row.id}
                onClick={() => onDismiss(row.id)}
              >
                Dismiss
              </FinanceActionButton>
            </div>
          ) : null}
        </article>
      ))}
    </div>
  );
}
