/**
 * F06 — Timesheet intelligence feature flags.
 * Enablement follows Application Config (org timesheetAdditional);
 * live API also requires REACT_APP_USE_TIMESHEET_INTELLIGENCE_API.
 */
import envconfig from "env.config";
import { shouldUseTimesheetIntelligence } from "config/tracopus-pilot.config";

export function isTimesheetIntelligenceEnabled() {
  return shouldUseTimesheetIntelligence();
}

/** Live timesheet intelligence API when org flag and env API toggle are both on. */
export function shouldUseTimesheetIntelligenceApi() {
  return isTimesheetIntelligenceEnabled() && envconfig.USE_TIMESHEET_INTELLIGENCE_API === true;
}
