import React from "react";
import classNames from "classnames/bind";
import {
  formatRegisterFetchError,
  isRegisterConnectionError,
} from "_helpers/registerListError.utils";

function LuxRegisterFetchError({ error, onRetry, className }) {
  if (!error) {
    return null;
  }

  const connectionIssue = isRegisterConnectionError(error);
  const message = formatRegisterFetchError(error);

  return (
    <section
      className={classNames("lux-register-empty", "lux-register-empty--fetch-error", className)}
      role="alert"
      aria-live="polite"
      aria-label="Unable to load data"
    >
      <div className="lux-register-empty__glow" aria-hidden="true" />
      <div className="lux-register-empty__inner">
        <div className="lux-register-fetch-error__icon" aria-hidden="true">
          <i className="fe fe-alert-circle" />
        </div>

        <div className="lux-register-empty__copy">
          <span className="lux-register-empty__eyebrow">
            {connectionIssue ? "Connection issue" : "Unable to load"}
          </span>
          <h3 className="lux-register-empty__title">Unable to load data</h3>
          <p className="lux-register-empty__text">{message}</p>

          {onRetry && (
            <div className="lux-register-empty__actions">
              <button
                type="button"
                className="lux-register-empty__btn lux-register-empty__btn--primary"
                onClick={onRetry}
              >
                <i className="fe fe-refresh-cw" aria-hidden="true" />
                Try again
              </button>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

export default LuxRegisterFetchError;
