export function isUniversalApprovalInboxEnabled() {
  return shouldUseUniversalApprovalInbox();
}

export function shouldUseUniversalApprovalApi() {
  return envconfig.USE_UNIVERSAL_APPROVAL_API === true;
}

export function getApprovalDomainMeta(domainId) {
  const normalized = String(domainId || "").toUpperCase();
  return (
    UNIVERSAL_APPROVAL_DOMAINS.find((domain) => domain.id === normalized) || {
      id: normalized || "UNKNOWN",
      label: normalized || "Approval",
      icon: "fe fe-inbox",
      module: "Workspace",
      tone: "slate",
    }
  );
}

export function getApprovalDomainFilterOptions() {
  const seen = new Set();
  // Production: never surface planned domains as filter chips.
  const allowPlanned = isMockDataEnabled();
  return UNIVERSAL_APPROVAL_DOMAINS.filter((domain) => {
    if (domain.parentDomain || seen.has(domain.id)) {
      return false;
    }
    if (domain.planned === true && !allowPlanned) {
      return false;
    }
    seen.add(domain.id);
    return true;
  });
}

/**
 * Domains with a registered backend ApprovalDomainAdapter (or settlement items
 * collected via OffboardingApprovalDomainAdapter). DOCUMENT is live via
 * DocumentApprovalDomainAdapter (pending vault verification).
 */
export function getLiveApprovalDomainIds() {
  return UNIVERSAL_APPROVAL_DOMAINS.filter((domain) => domain.planned !== true).map(
    (domain) => domain.id
  );
}
