import React, { Component } from "react";
import classNames from "classnames/bind";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import {
  RANKED_SKILL_SLOTS,
  SKILL_LEVEL_OPTIONS,
} from "./createEmployee.sections";

const LEVEL_LABEL = SKILL_LEVEL_OPTIONS.reduce((acc, o) => {
  acc[o.value] = o.label;
  return acc;
}, {});

class CreateEmployeeSkillsPanel extends Component {
  constructor(props) {
    super(props);
    const skills = (props.mappingObject && props.mappingObject.skills) || {};
    this.state = {
      skills,
      addPopoverOpen: false,
      draftSkill: { level: "BASIC" },
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.mappingObject !== this.props.mappingObject) {
      const skills = (this.props.mappingObject && this.props.mappingObject.skills) || {};
      this.setState({ skills });
    }
  }

  syncSkills = (skills) => {
    this.setState({ skills }, () => {
      this.props.onChange(this.props.name, skills);
    });
  };

  onRankedChange = (slotKey, skillValue) => {
    const skills = {
      ...this.state.skills,
      [slotKey]: skillValue,
    };
    this.syncSkills(skills);
  };

  getAdditionalSkills = () => {
    const list = this.state.skills && this.state.skills.additionalSkills;
    return Array.isArray(list) ? list : [];
  };

  openAddPopover = () => {
    this.setState({ addPopoverOpen: true, draftSkill: { level: "BASIC" } });
  };

  closeAddPopover = () => {
    this.setState({ addPopoverOpen: false, draftSkill: { level: "BASIC" } });
  };

  onDraftChange = (field, value) => {
    this.setState((prev) => ({
      draftSkill: { ...prev.draftSkill, [field]: value },
    }));
  };

  addDraftSkill = () => {
    const { draftSkill } = this.state;
    if (!draftSkill || !draftSkill.name) return;

    const additionalSkills = this.getAdditionalSkills();
    if (additionalSkills.some((s) => s.name === draftSkill.name)) {
      this.closeAddPopover();
      return;
    }

    this.syncSkills({
      ...this.state.skills,
      additionalSkills: [...additionalSkills, { ...draftSkill }],
    });
    this.closeAddPopover();
  };

  removeAdditionalSkill = (name) => {
    const additionalSkills = this.getAdditionalSkills().filter((s) => s.name !== name);
    this.syncSkills({
      ...this.state.skills,
      additionalSkills,
    });
  };

  renderRankedSlot = (slot) => {
    const skill =
      (this.state.skills && this.state.skills[slot.key]) || { level: "BASIC" };

    return (
      <article
        key={slot.key}
        className={classNames("lux-create-skill-card", `is-${slot.tier}`)}
      >
        <header className="lux-create-skill-card__head">
          <span className="lux-create-skill-card__tier">{slot.title}</span>
          <p className="lux-create-skill-card__desc">{slot.description}</p>
        </header>
        <div className="lux-create-skill-card__fields">
          <div className="lux-create-skill-card__field lux-create-skill-card__field--grow">
            <CustomInput
              readOnly={this.props.readOnly}
              type="select"
              label="Skill"
              name="name"
              fieldConfig={this.props.fieldConfig}
              mappingObject={skill}
              onChange={(n, v) =>
                this.onRankedChange(slot.key, { ...skill, [n]: v })
              }
              placeholder="Select skill…"
              isAppConfig={true}
              createConfig={this.props.createConfig}
              configName="skills"
              onFormError={this.props.onFormError}
              menuPortal={true}
            />
          </div>
          <div className="lux-create-skill-card__field">
            <CustomInput
              readOnly={this.props.readOnly}
              type="select"
              label="Level"
              name="level"
              disableClearable={true}
              fieldConfig={this.props.fieldConfig}
              mappingObject={skill}
              onChange={(n, v) =>
                this.onRankedChange(slot.key, { ...skill, [n]: v })
              }
              placeholder="Level"
              options={SKILL_LEVEL_OPTIONS}
              onFormError={this.props.onFormError}
              menuPortal={true}
            />
          </div>
        </div>
      </article>
    );
  };

  renderAddPopover = () => {
    if (!this.state.addPopoverOpen || this.props.readOnly) return null;

    const { draftSkill } = this.state;

    return (
      <>
        <button
          type="button"
          className="lux-create-skill-popover__backdrop"
          aria-label="Close"
          onClick={this.closeAddPopover}
        />
        <div
          className="lux-create-skill-popover"
          role="dialog"
          aria-labelledby="lux-add-skill-title"
        >
          <header className="lux-create-skill-popover__head">
            <div>
              <h4 id="lux-add-skill-title">Add additional skill</h4>
              <p>Pick a skill and proficiency, then add it to the list.</p>
            </div>
            <button
              type="button"
              className="lux-create-skill-popover__close"
              onClick={this.closeAddPopover}
              aria-label="Close"
            >
              <i className="fe fe-x" />
            </button>
          </header>
          <div className="lux-create-skill-popover__body">
            <div className="lux-create-skill-popover__fields">
              <CustomInput
                type="select"
                label="Skill"
                name="name"
                fieldConfig={this.props.fieldConfig}
                mappingObject={draftSkill}
                onChange={this.onDraftChange}
                placeholder="Select skill…"
                isAppConfig={true}
                createConfig={this.props.createConfig}
                configName="skills"
                onFormError={this.props.onFormError}
                menuPortal={true}
              />
              <CustomInput
                type="select"
                label="Level"
                name="level"
                disableClearable={true}
                fieldConfig={this.props.fieldConfig}
                mappingObject={draftSkill}
                onChange={this.onDraftChange}
                options={SKILL_LEVEL_OPTIONS}
                onFormError={this.props.onFormError}
                menuPortal={true}
              />
            </div>
          </div>
          <footer className="lux-create-skill-popover__foot">
            <button
              type="button"
              className="lux-create-footer__btn lux-create-footer__btn--ghost"
              onClick={this.closeAddPopover}
            >
              Cancel
            </button>
            <button
              type="button"
              className="lux-create-footer__btn lux-create-footer__btn--primary"
              onClick={this.addDraftSkill}
              disabled={!draftSkill.name}
            >
              <i className="fe fe-plus" aria-hidden="true" /> Add to list
            </button>
          </footer>
        </div>
      </>
    );
  };

  render() {
    const additionalSkills = this.getAdditionalSkills();
    const { readOnly } = this.props;

    return (
      <div className="lux-create-skills">
        <LuxCreateFieldGroupStub
          title="Ranked skills"
          description="Up to three skills appear prominently on the employee profile and in staffing views."
        >
          <div className="lux-create-skills__ranked">
            {RANKED_SKILL_SLOTS.map((slot) => this.renderRankedSlot(slot))}
          </div>
        </LuxCreateFieldGroupStub>

        <div className="lux-create-skills__additional">
          <header className="lux-create-skills__additional-head">
            <div>
              <h4 className="lux-create-field-group__title">Additional skills</h4>
              <p className="lux-create-field-group__desc">
                Supplementary competencies beyond the ranked three — ideal for
                certifications, tools, or occasional expertise.
              </p>
            </div>
            {!readOnly && (
              <button
                type="button"
                className="lux-create-skills__add-btn"
                onClick={this.openAddPopover}
              >
                <i className="fe fe-plus" aria-hidden="true" />
                Add skill
              </button>
            )}
          </header>

          {additionalSkills.length > 0 ? (
            <ul className="lux-create-skills__chip-list">
              {additionalSkills.map((skill) => (
                <li key={skill.name} className="lux-create-skills__chip">
                  <span className="lux-create-skills__chip-name">{skill.name}</span>
                  <span className="lux-create-skills__chip-level">
                    {LEVEL_LABEL[skill.level] || skill.level}
                  </span>
                  {!readOnly && (
                    <button
                      type="button"
                      className="lux-create-skills__chip-remove"
                      onClick={() => this.removeAdditionalSkill(skill.name)}
                      aria-label={`Remove ${skill.name}`}
                    >
                      <i className="fe fe-x" />
                    </button>
                  )}
                </li>
              ))}
            </ul>
          ) : (
            <div className="lux-create-skills__empty">
              <i className="fe fe-layers" aria-hidden="true" />
              <p>No additional skills yet</p>
              {!readOnly && (
                <button
                  type="button"
                  className="lux-create-skills__empty-btn"
                  onClick={this.openAddPopover}
                >
                  Add your first skill
                </button>
              )}
            </div>
          )}
        </div>

        {this.renderAddPopover()}
      </div>
    );
  }
}

/** Lightweight group header inside skills panel (avoids circular import). */
function LuxCreateFieldGroupStub({ title, description, children }) {
  return (
    <div className="lux-create-field-group">
      <header className="lux-create-field-group__head">
        {title && <h4 className="lux-create-field-group__title">{title}</h4>}
        {description && <p className="lux-create-field-group__desc">{description}</p>}
      </header>
      {children}
    </div>
  );
}

export default CreateEmployeeSkillsPanel;
