import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import Skeleton from "react-loading-skeleton";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const STORAGE_KEY = "famstack-filemanager-summary-expanded";

const QUICK_FILTERS = [
  { value: "ALL", label: "All" },
  { value: "FOLDERS", label: "Folders" },
  { value: "FILES", label: "Files" },
  { value: "SHARED", label: "Shared" },
  { value: "MINE", label: "Mine" },
];

export default class FileManagerPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(STORAGE_KEY, this.state.expanded)
    );
  };

  getShowFilter = () => {
    const options = this.props.filterOptions;
    return (options && options.SHOW && options.SHOW.selected) || "ALL";
  };

  quickFilter = (value) => {
    if (this.props.onQuickFilter) {
      this.props.onQuickFilter(value);
    }
  };

  buildContextLine = (stat, visibleCount, filterOptions) => {
    const parts = [];
    parts.push(
      `${stat.total} items · ${stat.folders} folders · ${stat.files} files · ${stat.storageLabel} used`
    );
    if (visibleCount !== stat.total) {
      parts.push(`${visibleCount} in view`);
    }
    if (filterOptions && filterOptions.filterText) {
      parts.push(`matching “${filterOptions.filterText}”`);
    }
    return parts.join(" · ");
  };

  renderFilterChips = (showFilter, compact) => (
    <div
      className={classNames("lux-bid-summary__filters", {
        "lux-bid-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter files"
    >
      {QUICK_FILTERS.map((option) => (
        <button
          key={option.value}
          type="button"
          className={classNames("lux-bid-summary__filter-chip", {
            "is-active": showFilter === option.value,
          })}
          onClick={() => this.quickFilter(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  renderKpiStrip = (stat, isLoading) => (
    <div className="lux-bid-summary__kpi-strip" role="list" aria-label="File manager metrics">
      {stat.kpis.map((kpi) => (
        <article
          key={kpi.key}
          className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
          role="listitem"
        >
          <div className="lux-bid-summary__kpi-top">
            <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
            <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
              <i className={kpi.icon} />
            </span>
          </div>
          <strong className="lux-bid-summary__kpi-value">
            {isLoading ? (
              <Skeleton width={48} />
            ) : kpi.displayValue ? (
              kpi.displayValue
            ) : (
              <>
                <CountUp end={Number(kpi.value) || 0} duration={0.65} />
                {kpi.suffix || ""}
              </>
            )}
          </strong>
          {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
        </article>
      ))}
    </div>
  );

  renderHighlights = (stat) => (
    <div
      className="lux-po-summary__highlights lux-file-summary__highlights"
      role="list"
      aria-label="File highlights"
    >
      {stat.highlights.map((item) => (
        <article
          key={item.key}
          className={classNames("lux-po-summary__highlight", item.tone && `is-${item.tone}`)}
          role="listitem"
        >
          <span className="lux-po-summary__highlight-icon" aria-hidden="true">
            <i className={item.icon} />
          </span>
          <div className="lux-po-summary__highlight-copy">
            <span className="lux-po-summary__highlight-label">{item.label}</span>
            <strong className="lux-po-summary__highlight-value">{item.value}</strong>
          </div>
        </article>
      ))}
    </div>
  );

  render() {
    const { stat, visibleCount, filterOptions, isLoading, currentFolderName } = this.props;
    if (!stat) return null;

    const showFilter = this.getShowFilter();
    const { expanded } = this.state;
    const contextLine = this.buildContextLine(stat, visibleCount, filterOptions);

    return (
      <section className="lux-bid-summary lux-file-summary" aria-label="File manager insights">
        <header className="lux-bid-summary__head">
          <LuxSummaryEyebrow variant="file-manager" className="lux-bid-summary__eyebrow">
            Workspace files
          </LuxSummaryEyebrow>
          <div className="lux-bid-summary__head-main">
            <h2 className="lux-bid-summary__title">File library</h2>
            <p className="lux-bid-summary__context">
              {isLoading ? <Skeleton width="70%" /> : contextLine}
            </p>
            {currentFolderName && currentFolderName !== "All files" && (
              <p className="lux-file-summary__folder-note">
                <i className="fe fe-folder" aria-hidden="true" /> Browsing{" "}
                <strong>{currentFolderName}</strong>
              </p>
            )}
          </div>
          <button
            type="button"
            className="lux-bid-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
          >
            {getSummaryToggleLabel(expanded)}
          </button>
        </header>

        {expanded && (
          <div className="lux-bid-summary__body">
            {this.renderKpiStrip(stat, isLoading)}
            {this.renderHighlights(stat)}
            {this.renderFilterChips(showFilter, false)}
          </div>
        )}

        {!expanded && (
          <div className="lux-bid-summary__compact">
            {this.renderKpiStrip(stat, isLoading)}
            {this.renderFilterChips(showFilter, true)}
          </div>
        )}
      </section>
    );
  }
}
