import React from "react";
import classNames from "classnames/bind";

/**
 * Canonical page-level refresh control — always use in PageInnerHeader actions (right side).
 */
export default function LuxPageRefreshButton({
  onClick,
  loading = false,
  disabled = false,
  label = "Refresh",
  title = "Refresh page data",
  compact = false,
  className,
  testId = "page-refresh-btn",
}) {
  const isDisabled = disabled || loading || !onClick;

  return (
    <button
      type="button"
      className={classNames(
        "lux-page-header__refresh-btn",
        { "is-loading": loading, "is-compact": compact },
        className
      )}
      onClick={onClick}
      disabled={isDisabled}
      aria-label={title}
      title={title}
      aria-busy={loading || undefined}
      data-testid={testId}
    >
      <span className="lux-page-header__refresh-btn-icon" aria-hidden="true">
        <i className="fe fe-refresh-cw" />
      </span>
      {!compact && <span className="lux-page-header__refresh-btn-label">{label}</span>}
    </button>
  );
}
