import {
  getSessionHiddenPages,
  isPageHiddenForSession,
  isPageTourCompleted,
  isShellTourCompleted,
  isTourPermanentlyDismissed,
} from './guidedTour.storage';
import { isGuidedNavigationOrgEnabled, GUIDED_TOUR_AUTO_START_ENABLED } from './guidedTour.config';
import { getPageTourDefinition, getShellTourSteps } from './guidedTour.definitions';

/** Normalize dynamic routes to stable tour keys. */
export function getTourPageKey(pathname) {
  const path = (pathname || '').split('?')[0].replace(/\/+$/, '') || '/';

  const rules = [
    [/^\/project\/details\/[^/]+/, 'project/details'],
    [/^\/project\/deliverables\/[^/]+/, 'project/deliverables'],
    [/^\/project\/deliverable\/[^/]+/, 'project/deliverable'],
    [/^\/project\/workitems\/[^/]+/, 'project/workitems'],
    [/^\/sales\/bidrequest\/[^/]+/, 'sales/bidrequest'],
    [/^\/sales\/purchaseorder\/[^/]+/, 'sales/purchaseorder'],
    [/^\/people\/employees\/[^/]+\/360/, 'people/employee-360'],
    [/^\/people\/employees\/[^/]+/, 'hrms/profile'],
    [/^\/hrms\/profile\/[^/]+/, 'hrms/profile'],
    [/^\/finance\/invoice\/details\/[^/]+/, 'hrms/invoice-details'],
    [/^\/hrms\/invoice\/details\/[^/]+/, 'hrms/invoice-details'],
    [/^\/project\/dashboard/, 'project/dashboard'],
    [/^\/project\/list/, 'project/list'],
    [/^\/project\/capacity/, 'project/capacity'],
    [/^\/project\/accounts/, 'project/accounts'],
    [/^\/project\/todolist/, 'project/todolist'],
    [/^\/project\/taskboard/, 'project/taskboard'],
    [/^\/project\/activites/, 'project/activites'],
    [/^\/project\/reports/, 'project/reports'],
    [/^\/project\/feedback/, 'project/feedback'],
    [/^\/project\/search/, 'project/search'],
    [/^\/project\/filemanager/, 'project/filemanager'],
    [/^\/project\/chat/, 'project/chat'],
    [/^\/project\/calendar/, 'project/calendar'],
    [/^\/people\/dashboard/, 'hrms/dashboard'],
    [/^\/people\/employees/, 'hrms/employees'],
    [/^\/people\/attendance/, 'hrms/attendance'],
    [/^\/people\/timesheet/, 'hrms/timesheet'],
    [/^\/people\/settings/, 'hrms/settings'],
    [/^\/finance\/invoice/, 'hrms/invoice'],
    [/^\/admin\/appconfig/, 'hrms/appconfig'],
    [/^\/hrms\/dashboard/, 'hrms/dashboard'],
    [/^\/hrms\/employees/, 'hrms/employees'],
    [/^\/hrms\/attendance/, 'hrms/attendance'],
    [/^\/hrms\/timesheet/, 'hrms/timesheet'],
    [/^\/hrms\/invoice/, 'hrms/invoice'],
    [/^\/hrms\/settings/, 'hrms/settings'],
    [/^\/hrms\/appconfig/, 'hrms/appconfig'],
    [/^\/sales\/bidrequests/, 'sales/bidrequests'],
    [/^\/sales\/purchaseorders/, 'sales/purchaseorders'],
  ];

  for (let i = 0; i < rules.length; i += 1) {
    if (rules[i][0].test(path)) {
      return rules[i][1];
    }
  }

  return null;
}

export function filterAvailableSteps(steps) {
  if (!steps || !steps.length) return [];

  return steps.filter((step) => {
    if (!step || !step.target) return false;
    if (step.target === 'body') return true;
    if (typeof document === 'undefined') return true;
    return !!document.querySelector(step.target);
  });
}

export function buildTourSteps(pathname, options) {
  if (options && options.forceShell) {
    return filterAvailableSteps(getShellTourSteps());
  }

  const pageKey = getTourPageKey(pathname);
  const includeShell = options && options.includeShell;
  const steps = [];

  if (includeShell) {
    steps.push.apply(steps, getShellTourSteps());
  }

  if (pageKey) {
    const pageDef = getPageTourDefinition(pageKey);
    if (pageDef && pageDef.steps) {
      steps.push.apply(steps, pageDef.steps);
    }
  }

  return filterAvailableSteps(steps);
}

export function shouldAutoStartTour(pathname) {
  if (!GUIDED_TOUR_AUTO_START_ENABLED) return false;
  if (!isGuidedNavigationOrgEnabled()) return false;
  if (isTourPermanentlyDismissed()) return false;

  const pageKey = getTourPageKey(pathname);
  if (!pageKey) return false;

  if (isPageHiddenForSession(pageKey)) return false;

  const needsShell = !isShellTourCompleted();
  const needsPage = !isPageTourCompleted(pageKey);

  if (!needsShell && !needsPage) return false;

  if (needsShell && !needsPage) {
    return buildTourSteps(pathname, { forceShell: true }).length > 0;
  }

  if (needsShell && needsPage) {
    return buildTourSteps(pathname, { includeShell: true }).length > 0;
  }

  return buildTourSteps(pathname, { includeShell: false }).length > 0;
}

export function getTourMeta(pathname) {
  const pageKey = getTourPageKey(pathname);
  const pageDef = pageKey ? getPageTourDefinition(pageKey) : null;

  return {
    pageKey,
    pageTitle: pageDef ? pageDef.title : null,
    sessionHidden: pageKey ? isPageHiddenForSession(pageKey) : false,
    pageCompleted: pageKey ? isPageTourCompleted(pageKey) : false,
    permanentlyDismissed: isTourPermanentlyDismissed(),
    shellCompleted: isShellTourCompleted(),
    sessionHiddenPages: getSessionHiddenPages(),
  };
}
