import React from "react";
import classNames from "classnames/bind";

import PageInnerHeaderTeamsSelectionMenu from "views/common/fragments/PageInnerHeaderTeamsSelectionMenu";

function SegmentHeader({ icon, eyebrow, value }) {
  return (
    <div className="lux-proj-dash__segment-head">
      <span className="lux-proj-dash__segment-icon" aria-hidden="true">
        <i className={icon} />
      </span>
      <div className="lux-proj-dash__segment-copy">
        <span className="lux-proj-dash__segment-eyebrow">{eyebrow}</span>
        <strong className="lux-proj-dash__segment-value">{value}</strong>
      </div>
    </div>
  );
}

export default function ProjectDashboardControlDeck({
  userTeams,
  baseTeams,
  managerTeamMode,
  teamScopeLabel,
  canSwitchTeams,
  onTeamModeChange,
  onUserTeamsSelection,
  managerFilter,
  managerFilters,
  onManagerFilterChange,
  dashboardLens,
  dashboardLenses,
  onDashboardLensChange,
}) {
  const totalTeams = baseTeams && baseTeams.length ? baseTeams.length : 0;
  const selectedTeamsCount = userTeams
    ? userTeams.filter((t) => t.isChecked).length
    : 0;

  const portfolioLabel =
    managerFilters && managerFilters.find((f) => f.key === managerFilter);
  const lensLabel =
    dashboardLenses && dashboardLenses.find((l) => l.key === dashboardLens);

  return (
    <section
      className="lux-proj-dash__control-deck"
      aria-label="Dashboard filters"
      data-testid="project-dashboard-control-deck"
    >
      <div className="lux-proj-dash__segment">
        <SegmentHeader
          icon="fe fe-users"
          eyebrow="Team scope"
          value={teamScopeLabel}
        />
        {canSwitchTeams ? (
          <div className="lux-proj-dash__segment-actions">
            <div className="lux-proj-dash__chip-group" role="group" aria-label="Team scope">
              <button
                type="button"
                className={classNames("lux-proj-dash__chip", {
                  "is-active": managerTeamMode === "selected",
                })}
                onClick={() => onTeamModeChange && onTeamModeChange("selected")}
              >
                Selected{selectedTeamsCount ? ` (${selectedTeamsCount})` : ""}
              </button>
              <button
                type="button"
                className={classNames("lux-proj-dash__chip", {
                  "is-active": managerTeamMode === "all",
                })}
                onClick={() => onTeamModeChange && onTeamModeChange("all")}
              >
                All{totalTeams ? ` (${totalTeams})` : ""}
              </button>
            </div>
            {managerTeamMode === "selected" && (
              <PageInnerHeaderTeamsSelectionMenu
                userTeams={userTeams}
                enabled={canSwitchTeams}
                isLoading={false}
                handleUserTeamsSelection={onUserTeamsSelection}
              />
            )}
          </div>
        ) : null}
      </div>

      <div className="lux-proj-dash__segment">
        <SegmentHeader
          icon="fe fe-layers"
          eyebrow="Portfolio"
          value={
            portfolioLabel
              ? portfolioLabel.label
              : managerFilter === "ACTIVE"
                ? "Active"
                : managerFilter
          }
        />
        <div className="lux-proj-dash__segment-actions">
          <div className="lux-proj-dash__chip-group" role="group" aria-label="Portfolio filter">
            {(managerFilters || []).map(function (f) {
              return (
                <button
                  key={f.key}
                  type="button"
                  className={classNames("lux-proj-dash__chip", {
                    "is-active": managerFilter === f.key,
                  })}
                  onClick={function () {
                    onManagerFilterChange && onManagerFilterChange(f.key);
                  }}
                >
                  {f.label}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      <div className="lux-proj-dash__segment">
        <SegmentHeader
          icon="fe fe-eye"
          eyebrow="Leadership lens"
          value={lensLabel ? lensLabel.label : dashboardLens}
        />
        <div className="lux-proj-dash__segment-actions">
          <div className="lux-proj-dash__chip-group" role="group" aria-label="Leadership lens">
            {(dashboardLenses || []).map(function (lens) {
              return (
                <button
                  key={lens.key}
                  type="button"
                  className={classNames("lux-proj-dash__chip", {
                    "is-active": dashboardLens === lens.key,
                  })}
                  onClick={function () {
                    onDashboardLensChange && onDashboardLensChange(lens.key);
                  }}
                >
                  {lens.label}
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </section>
  );
}
