import React from "react";
import classNames from "classnames/bind";

export default function SimulationCompareStrip({ comparison, loading }) {
  if (loading || !comparison || comparison.length === 0) {
    return null;
  }

  return (
    <div className="lux-simulation-compare" role="list" aria-label="Baseline vs scenario comparison">
      {comparison.map((metric) => (
        <article
          key={metric.id}
          className={classNames("lux-simulation-compare__card", metric.tone && `is-${metric.tone}`)}
          role="listitem"
        >
          <span className="lux-simulation-compare__label">{metric.label}</span>
          <div className="lux-simulation-compare__values">
            <span className="lux-simulation-compare__baseline" title="Baseline">
              {metric.baseline}
            </span>
            <i className="fe fe-arrow-right lux-simulation-compare__arrow" aria-hidden="true" />
            <strong className="lux-simulation-compare__projected">{metric.projected}</strong>
          </div>
          <span
            className={classNames("lux-simulation-compare__delta", {
              "is-positive": metric.delta > 0,
              "is-negative": metric.delta < 0,
              "is-neutral": metric.delta === 0,
            })}
          >
            {metric.deltaLabel}
          </span>
        </article>
      ))}
    </div>
  );
}
