import React, { useEffect, useRef } from "react";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";

/**
 * Wide right drawer for editing one Application Config module group
 * (HRMS, PROJECT, NON PROJECT, etc.) with more working space.
 */
function ApplicationConfigModuleDrawer({
  show,
  onClose,
  title,
  subtitle,
  settingCount,
  searchQuery,
  onSearchChange,
  onSearchClear,
  toolbar,
  children,
}) {
  const searchRef = useRef(null);
  const hasSearch = Boolean(searchQuery && String(searchQuery).trim());
  const resolvedSubtitle =
    subtitle ||
    (settingCount != null
      ? `${settingCount} setting${settingCount === 1 ? "" : "s"}${
          hasSearch ? " matching" : ""
        } · edits save with Update`
      : "Edits save with Update");

  useEffect(() => {
    if (!show || !searchRef.current) {
      return undefined;
    }
    const frame = window.requestAnimationFrame(() => {
      if (searchRef.current) {
        searchRef.current.focus();
      }
    });
    return () => window.cancelAnimationFrame(frame);
  }, [show, title]);

  return (
    <LuxCreatePanelShell
      show={!!show}
      onClose={onClose}
      kicker="Application config"
      title={title || "Module settings"}
      subtitle={resolvedSubtitle}
      toolbar={
        <div className="lux-appconfig-module-drawer__toolbar">
          <label className="lux-appconfig-module-drawer__search">
            <i className="fe fe-search" aria-hidden="true" />
            <input
              ref={searchRef}
              type="search"
              value={searchQuery || ""}
              onChange={onSearchChange}
              placeholder={`Search keys & nested flags in ${title || "module"}...`}
              aria-label={`Search settings in ${title || "module"}`}
            />
            {hasSearch && (
              <button
                type="button"
                className="lux-appconfig-module-drawer__search-clear"
                onClick={onSearchClear}
                aria-label="Clear module search"
              >
                <i className="fe fe-x" aria-hidden="true" />
              </button>
            )}
          </label>
          <span className="lux-appconfig-module-drawer__search-meta" aria-live="polite">
            {hasSearch
              ? `${settingCount || 0} match${settingCount === 1 ? "" : "es"}`
              : `${settingCount || 0} settings`}
          </span>
          {toolbar ? <div className="lux-appconfig-module-drawer__actions">{toolbar}</div> : null}
        </div>
      }
      panelId="lux-appconfig-module-drawer"
      className="lux-create-panel--appconfig-module"
      size="lg"
    >
      <div className="lux-appconfig-module-drawer__scroll">
        {children}
        {hasSearch && settingCount === 0 && (
          <div className="lux-appconfig-module-drawer__empty">
            <i className="fe fe-search" aria-hidden="true" />
            <p>No settings match “{String(searchQuery).trim()}”.</p>
            <button type="button" className="lux-appconfig-panel__filter-reset" onClick={onSearchClear}>
              Clear search
            </button>
          </div>
        )}
      </div>
    </LuxCreatePanelShell>
  );
}

export default ApplicationConfigModuleDrawer;
