import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import { NavLink } from "react-router-dom";
import EmployeeImage from "views/common/fragments/EmployeeImage";
import CountUp from "react-countup";
import {
  getDayMeta,
  findAttendanceItem,
  getAttendanceStatusMeta,
  isAttendanceMarked,
  canMarkAttendanceFor,
} from "./attendance.utils";
import { getEmployeeDetailsPathname } from "views/hrms/profileDetailsNavigation.utils";

class AttendanceCurrentUserPanel extends PureComponent {
  renderDayStrip = () => {
    const {
      employee,
      monthDays,
      items,
      isLoading,
      permission,
      currentUserId,
      onRequestMark,
      onRequestViewDetails,
    } = this.props;
    const canMark = canMarkAttendanceFor(
      permission,
      employee && employee.id,
      currentUserId
    );

    return (
      <div className="lux-att-you__strip" role="list" aria-label="Your attendance this month">
        {monthDays.map((dayMonth) => {
          const meta = getDayMeta(dayMonth, this.props.workdays, this.props.holidayDates);
          const item = findAttendanceItem(items, employee.id, dayMonth);
          const statusMeta = getAttendanceStatusMeta(item);
          const isMarked = isAttendanceMarked(item);
          const canViewMarked = isMarked && item && item.id != null;
          const canToggle = !meta.isFuture && !isLoading && (canViewMarked || canMark);

          return (
            <div
              key={dayMonth.format("YYYY-MM-DD")}
              role="listitem"
              className={classNames("lux-att-you__day", {
                "is-present": statusMeta.tone === "present",
                "is-pending": statusMeta.tone === "pending",
                "is-pending-removal": statusMeta.tone === "pending-removal",
                "is-rejected": statusMeta.tone === "rejected",
                "is-leave": statusMeta.tone === "leave",
                "is-holiday": meta.isHoliday,
                "is-weekend": meta.isWeekend,
                "is-absent": statusMeta.tone === "absent" && !meta.isFuture,
                "is-future": meta.isFuture,
                "is-today": meta.isToday,
                "is-saturday": meta.isSaturday,
                "is-sunday": meta.isSunday,
                "is-clickable": canToggle,
              })}
              title={
                meta.isWeekend
                  ? `${dayMonth.format("ddd, MMM D")} · optional day`
                  : dayMonth.format("ddd, MMM D")
              }
            >
              <span className="lux-att-you__day-label">{meta.dayNum}</span>
              {meta.isFuture ? (
                <span
                  className="lux-att-you__day-mark is-future"
                  title={`Upcoming · ${dayMonth.format("MMM D")}`}
                  aria-label={`Upcoming ${dayMonth.format("MMM D")}`}
                >
                  <i className="fe fe-sunrise" aria-hidden="true" />
                </span>
              ) : (
                <button
                  type="button"
                  className={classNames("lux-att-you__day-mark", {
                    "is-present": statusMeta.tone === "present",
                    "is-pending": statusMeta.tone === "pending",
                    "is-rejected": statusMeta.tone === "rejected",
                    "is-leave": statusMeta.tone === "leave",
                    "is-absent": statusMeta.tone === "absent",
                  })}
                  disabled={!canToggle}
                  onClick={(event) => {
                    event.preventDefault();
                    event.stopPropagation();
                    if (!canToggle) return;
                    if (canViewMarked) {
                      onRequestViewDetails(employee.id, employee.name, dayMonth, item);
                    } else if (canMark && onRequestMark) {
                      onRequestMark(employee.id, employee.name, dayMonth);
                    }
                  }}
                  aria-label={`${statusMeta.label} ${dayMonth.format("MMM D")}`}
                >
                  <i className={statusMeta.icon} aria-hidden="true" />
                </button>
              )}
            </div>
          );
        })}
      </div>
    );
  };

  render() {
    const {
      employee,
      stats,
      permission,
      panelLabel,
      isViewingSelf,
      onRequestRegularize,
      leaveApplyPath,
    } = this.props;
    if (!employee) return null;

    const absentCount = stats && typeof stats.absent === "number" ? stats.absent : 0;
    const showAbsentSoftCta = absentCount > 0 && (onRequestRegularize || leaveApplyPath);

    return (
      <section className="lux-att-you" aria-label="Your attendance">
        <div className="lux-att-you__glow" aria-hidden="true" />
        <header className="lux-att-you__head">
          <div className="lux-att-you__identity">
            <div className="lux-att-you__avatar-wrap">
              <EmployeeImage employee={employee} classes="lux-att-you__avatar" />
              <span className="lux-att-you__badge">
                {panelLabel || (isViewingSelf !== false ? "Your attendance" : "Employee attendance")}
              </span>
            </div>
            <div>
              <h3 className="lux-att-you__name">
                {permission && permission.viewEnabled ? (
                  <NavLink to={getEmployeeDetailsPathname(employee.id)}>{employee.name}</NavLink>
                ) : (
                  employee.name
                )}
              </h3>
              {employee.designation && (
                <p className="lux-att-you__designation">{employee.designation}</p>
              )}
            </div>
          </div>

          <div className="lux-att-you__aside">
            <div className="lux-att-you__stats">
              <div className="lux-att-you__stat is-present">
                <strong><CountUp end={stats.present} duration={0.7} /></strong>
                <span>Present</span>
              </div>
              <div className="lux-att-you__stat is-absent">
                <strong><CountUp end={stats.absent} duration={0.7} /></strong>
                <span>Absent</span>
              </div>
              <div className="lux-att-you__stat is-rate">
                <strong><CountUp end={stats.rate} duration={0.7} />%</strong>
                <span>This month</span>
              </div>
            </div>

            {showAbsentSoftCta && (
              <div className="lux-att-you__actions" role="group" aria-label="Resolve absent days">
                {leaveApplyPath && (
                  <NavLink to={leaveApplyPath} className="lux-att-you__apply-leave">
                    <i className="fe fe-calendar" aria-hidden="true" />
                    Apply leave
                  </NavLink>
                )}
                {onRequestRegularize && (
                  <button
                    type="button"
                    className="lux-att-you__regularize"
                    onClick={() => onRequestRegularize(null, null)}
                  >
                    <i className="fe fe-edit-2" aria-hidden="true" />
                    Request regularization
                  </button>
                )}
              </div>
            )}
            {!showAbsentSoftCta && onRequestRegularize && (
              <button
                type="button"
                className="lux-att-you__regularize"
                onClick={() => onRequestRegularize(null, null)}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
                Request regularization
              </button>
            )}
          </div>
        </header>

        {this.renderDayStrip()}
      </section>
    );
  }
}

export default AttendanceCurrentUserPanel;
