import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseClientPortalApi } from "config/client-portal.config";

const CLIENT_USER_KEY = "tracopus_client_portal_user_id";

export const clientPortalService = {
  getOverview,
  getOverviewScoped,
  signOffProject,
  signOffProjectForClientUser,
  resolveSession,
  listProjects,
  getProject,
  listDocuments,
  getDocumentDownloadUrl,
  listInvoices,
  listSignOffs,
  submitFeedback,
  listFeedback,
  createTicket,
  updateTicket,
  listTickets,
  getStoredClientUserId,
  setStoredClientUserId,
  clearStoredClientUserId,
};

const API_ERROR = { payload: null, source: "api-error" };

function getStoredClientUserId() {
  try {
    const raw = sessionStorage.getItem(CLIENT_USER_KEY);
    return raw ? Number(raw) : null;
  } catch (e) {
    return null;
  }
}

function setStoredClientUserId(clientUserId) {
  try {
    if (clientUserId != null) {
      sessionStorage.setItem(CLIENT_USER_KEY, String(clientUserId));
    }
  } catch (e) {
    // ignore
  }
}

function clearStoredClientUserId() {
  try {
    sessionStorage.removeItem(CLIENT_USER_KEY);
  } catch (e) {
    // ignore
  }
}

async function resolveSession({ email, externalSubject, idToken, userTeamId } = {}) {
  if (!shouldUseClientPortalApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  const teamId = userTeamId != null ? userTeamId : commonUtils.getCurrentUserTeamId();
  try {
    const response = await axiosUtils.post(`${urlConfig.CLIENT_PORTAL_API_PATH}/auth/session`, {
      userTeamId: teamId,
      email,
      externalSubject,
      idToken,
    });
    const payload = response && response.payload ? response.payload : response;
    if (payload && payload.clientUserId != null) {
      setStoredClientUserId(payload.clientUserId);
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[ClientPortal] Session API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function getOverview({ clientId } = {}) {
  if (!shouldUseClientPortalApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  if (!clientId) {
    return { ...API_ERROR, reason: "clientId-required" };
  }
  try {
    const response = await axiosUtils.getWithParam(`${urlConfig.CLIENT_PORTAL_API_PATH}/overview`, {
      userTeamId: commonUtils.getCurrentUserTeamId(),
      clientId,
    });
    const payload = response && response.payload ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[ClientPortal] Overview API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

