async function signOffProject({ projectId, clientId, actorId } = {}) {
  if (!shouldUseClientPortalApi()) {
    return { ...API_ERROR, reason: "flag-off" };
  }
  if (!projectId || !clientId) {
    return { ...API_ERROR, reason: "projectId-and-clientId-required" };
  }
  const userTeamId = commonUtils.getCurrentUserTeamId();
  const resolvedActorId = actorId != null ? actorId : commonUtils.getCurrentUserId();
  try {
    const response = await axiosUtils.post(
      `${urlConfig.CLIENT_PORTAL_API_PATH}/projects/${projectId}/sign-off?userTeamId=${userTeamId}&actorId=${resolvedActorId}&clientId=${encodeURIComponent(clientId)}`,
      {}
    );
    const payload = response && response.payload ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[ClientPortal] Sign-off API unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

