import { ACCESS_REQUEST_STATUSES } from "config/asset-register.config";
import {
  buildAuditActionSeries,
  buildAuditAdminMetrics,
  normalizeAdminAuditEvents,
} from "config/audit-admin.utils";
import {
  buildCompliancePackMetrics,
  buildComplianceReadinessSeries,
} from "config/compliance-pack.utils";
import {
  buildFeatureAdoptionSeries,
  buildFeatureFlagMetrics,
} from "config/feature-flag.utils";
import {
  buildMaskingLevelSeries,
  buildMaskingPolicyMetrics,
} from "config/masking-policy.utils";
import { getActionMeta, getEntityMeta } from "_helpers/audit.utils";

export function normalizeAdminInsightsSnapshot(raw) {
  const source = raw || {};
  return {
    auditEvents: normalizeAdminAuditEvents(source.auditEvents || []),
    maskingRules: source.maskingRules || [],
    featureFlags: source.featureFlags || [],
    complianceSections: source.complianceSections || [],
    accessRequests: source.accessRequests || [],
  };
}

export function countAccessDenials(auditEvents, accessRequests = []) {
  const rows = normalizeAdminAuditEvents(auditEvents);
  const auditDenials = rows.filter((event) => {
    const key = getActionMeta(event.actionType).key;
    return key === "REJECTED" || event.actionType === "REJECTED";
  }).length;
  const requestDenials = (accessRequests || []).filter(
    (row) => row.status === ACCESS_REQUEST_STATUSES.REJECTED
  ).length;
  return {
    auditDenials,
    requestDenials,
    total: auditDenials + requestDenials,
  };
}

export function buildAdminInsightsMetrics(snapshot) {
  const data = normalizeAdminInsightsSnapshot(snapshot);
  const audit = buildAuditAdminMetrics(data.auditEvents);
  const masking = buildMaskingPolicyMetrics(data.maskingRules);
  const flags = buildFeatureFlagMetrics(data.featureFlags);
  const compliance = buildCompliancePackMetrics(data.complianceSections);
  const denials = countAccessDenials(data.auditEvents, data.accessRequests);

  return {
    auditTotal: audit.total,
    auditRecent24h: audit.recent24h,
    uniqueActors: audit.uniqueActors,
    accessDenials: denials.total,
    maskingRestrictedPct: masking.restrictedPct,
    flagAdoptionAvg: flags.adoptionAvg,
    complianceReadinessPct: compliance.readinessPct,
    enabledFlags: flags.enabledFlags,
    highRiskRules: masking.highRiskRules,
    readySections: compliance.readySections,
    totalSections: compliance.totalSections,
  };
}

export function buildAdminInsightsInsights(snapshot) {
  const data = normalizeAdminInsightsSnapshot(snapshot);
  const metrics = buildAdminInsightsMetrics(data);
  const insights = [];

  if (metrics.accessDenials > 0) {
    insights.push({
      id: "denials",
      tone: "rose",
      icon: "fe fe-slash",
      title: `${metrics.accessDenials} access denial(s) recorded`,
      copy: "Review rejected approvals and access requests for policy gaps.",
    });
  }

  if (metrics.complianceReadinessPct >= 90) {
    insights.push({
      id: "compliance",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${metrics.complianceReadinessPct}% compliance readiness`,
      copy: "Governance domains are aligned for regulator export.",
    });
  } else if (metrics.complianceReadinessPct > 0) {
    insights.push({
      id: "compliance-partial",
      tone: "amber",
      icon: "fe fe-alert-triangle",
      title: `${metrics.complianceReadinessPct}% pack readiness`,
      copy: "Resolve section gaps before compliance export.",
    });
  }

  if (metrics.highRiskRules > 0 && metrics.maskingRestrictedPct < 80) {
    insights.push({
      id: "masking",
      tone: "amber",
      icon: "fe fe-eye-off",
      title: `${metrics.highRiskRules} high-risk field(s) with open masking`,
      copy: "Tighten persona visibility before production rollout.",
    });
  }

  if (metrics.auditRecent24h >= 3) {
    insights.push({
      id: "volume",
      tone: "blue",
      icon: "fe fe-activity",
      title: `${metrics.auditRecent24h} audit event(s) in 24h`,
      copy: "Elevated activity — spot-check sensitive mutations.",
    });
  }

  if (insights.length === 0) {
    insights.push({
      id: "baseline",
      tone: "violet",
      icon: "fe fe-bar-chart-2",
      title: "Governance dashboard aligned",
      copy: `${metrics.auditTotal} audit events · ${metrics.enabledFlags} flags enabled.`,
    });
  }

  return insights.slice(0, 3);
}

export function buildAuditVolumeByDaySeries(events, days = 7) {
  const rows = normalizeAdminAuditEvents(events);
  const now = new Date();
  const buckets = {};

  for (let i = days - 1; i >= 0; i -= 1) {
    const date = new Date(now);
    date.setDate(date.getDate() - i);
    buckets[date.toISOString().slice(0, 10)] = 0;
  }

  rows.forEach((event) => {
    const key = String(event.createdDate || event.createdAt || "").slice(0, 10);
    if (Object.prototype.hasOwnProperty.call(buckets, key)) {
      buckets[key] += 1;
    }
  });

  return Object.entries(buckets).map(([date, value]) => ({
    id: date,
    label: new Date(`${date}T12:00:00`).toLocaleDateString("en-US", { weekday: "short" }),
    value,
    tone: value >= 3 ? "violet" : value > 0 ? "blue" : "slate",
  }));
}

export function buildAccessDenialSeries(auditEvents, accessRequests = []) {
  const rows = normalizeAdminAuditEvents(auditEvents);
  const entityCounts = {};

  rows.forEach((event) => {
    const key = getActionMeta(event.actionType).key;
    if (key !== "REJECTED" && event.actionType !== "REJECTED") {
      return;
    }
    const entityType = (event.entity && event.entity.type) || event.entityType || "OTHER";
    entityCounts[entityType] = (entityCounts[entityType] || 0) + 1;
  });

  const series = Object.entries(entityCounts).map(([entityType, value]) => {
    const meta = getEntityMeta(entityType);
    return {
      id: `audit-${entityType}`,
      label: meta.label || entityType,
      value,
      tone: "rose",
    };
  });

  const requestDenials = (accessRequests || []).filter(
    (row) => row.status === ACCESS_REQUEST_STATUSES.REJECTED
  ).length;
  if (requestDenials > 0) {
    series.push({
      id: "access-requests",
      label: "Access requests",
      value: requestDenials,
      tone: "amber",
    });
  }

  return series.sort((a, b) => b.value - a.value).slice(0, 6);
}

export function buildSensitiveFieldAccessSeries(rules) {
  return buildMaskingLevelSeries(rules).map((row, index) => ({
    id: `mask-${index}`,
    label: row.label,
    value: row.value,
    tone: row.tone,
  }));
}

export function buildAdminInsightsChartBundle(snapshot) {
  const data = normalizeAdminInsightsSnapshot(snapshot);
  return {
    auditVolume: buildAuditVolumeByDaySeries(data.auditEvents),
    auditActions: buildAuditActionSeries(data.auditEvents),
    accessDenials: buildAccessDenialSeries(data.auditEvents, data.accessRequests),
    sensitiveFieldAccess: buildSensitiveFieldAccessSeries(data.maskingRules),
    complianceReadiness: buildComplianceReadinessSeries(data.complianceSections),
    featureAdoption: buildFeatureAdoptionSeries(data.featureFlags).map((row) => ({
      ...row,
      tone: row.enabled ? "blue" : "slate",
    })),
  };
}
