import React, { useEffect, useState } from "react";
import classNames from "classnames/bind";
import { onboardingService } from "_services/onboarding.service";
import { buildOffboardingSettlementPreview } from "config/onboarding.utils";
import OnboardingStatusBadge from "./OnboardingStatusBadge";

function OffboardingSettlementStrip({ caseData, onTaskSelect }) {
  const [preview, setPreview] = useState(null);

  useEffect(() => {
    if (!caseData || !caseData.id) {
      setPreview(null);
      return undefined;
    }
    let cancelled = false;
    onboardingService
      .getOffboardingSettlementPreview(caseData.id)
      .then((res) => {
        if (!cancelled) {
          setPreview(res.payload || buildOffboardingSettlementPreview(caseData));
        }
      })
      .catch(() => {
        if (!cancelled) {
          setPreview(buildOffboardingSettlementPreview(caseData));
        }
      });
    return () => {
      cancelled = true;
    };
  }, [caseData]);

  if (!preview || caseData.status === "completed" || caseData.status === "cancelled") {
    return null;
  }

  const hasSettlementTasks = preview.settlementTasks && preview.settlementTasks.length > 0;
  if (!hasSettlementTasks) {
    return null;
  }

  const linked = preview.linkedSources || {};
  const assetClearance = linked.assetClearance || null;
  const accessRevocation = linked.accessRevocation || null;
  const documentClearance = linked.documentClearance || null;
  const hasClearance =
    assetClearance != null || accessRevocation != null || documentClearance != null;

  return (
    <section
      className={classNames("lux-onb-detail__cta", "lux-onb-settlement", {
        "lux-onb-settlement--ready": preview.canFinalize,
        "lux-onb-settlement--blocked": preview.blockers.length > 0,
      })}
      aria-label="Final settlement readiness"
    >
      <div className="lux-onb-settlement__head">
        <i className="fe fe-dollar-sign" aria-hidden />
        <div>
          <strong>Final settlement readiness</strong>
          <p className="lux-onb-detail__cta-hint">
            {preview.canFinalize
              ? "All settlement prerequisites are satisfied — payroll can finalize exit pay."
              : "Resolve blockers before payroll can release final settlement."}
          </p>
        </div>
      </div>

      {hasClearance && (
        <ul className="lux-onb-settlement__tasks" aria-label="Canonical clearance sources">
          {assetClearance && (
            <li>
              <span>
                Assets · {assetClearance.clearanceStatus || "UNKNOWN"}
                {assetClearance.openAssignments != null
                  ? ` (${assetClearance.openAssignments} open)`
                  : ""}
              </span>
            </li>
          )}
          {accessRevocation && (
            <li>
              <span>
                Access · {accessRevocation.revocationStatus || "UNKNOWN"}
                {accessRevocation.openRequests != null
                  ? ` (${accessRevocation.openRequests} open)`
                  : ""}
              </span>
            </li>
          )}
          {documentClearance && (
            <li>
              <span>
                Documents · {documentClearance.clearanceStatus || "UNKNOWN"}
                {documentClearance.pendingDocuments != null
                  ? ` (${documentClearance.pendingDocuments} pending)`
                  : ""}
              </span>
            </li>
          )}
        </ul>
      )}

      {preview.blockers.length > 0 && (
        <ul className="lux-onb-settlement__blockers" role="alert">
          {preview.blockers.map((item) => (
            <li key={item}>{item}</li>
          ))}
        </ul>
      )}

      <ul className="lux-onb-settlement__tasks">
        {preview.settlementTasks.map((task) => (
          <li key={task.id}>
            {onTaskSelect ? (
              <button
                type="button"
                className="lux-onb-settlement__task-btn"
                onClick={() => {
                  const fullTask = (caseData.tasks || []).find((row) => row.id === task.id);
                  if (fullTask) {
                    onTaskSelect(fullTask);
                  }
                }}
              >
                <span>{task.title}</span>
                <OnboardingStatusBadge status={task.status} variant="task" />
              </button>
            ) : (
              <>
                <span>{task.title}</span>
                <OnboardingStatusBadge status={task.status} variant="task" />
              </>
            )}
          </li>
        ))}
      </ul>
    </section>
  );
}

export default OffboardingSettlementStrip;
