import React from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";

export default function TimesheetBillabilityPanel({ billability }) {
  if (!billability) {
    return null;
  }

  return (
    <section className="lux-ts-intel__billability" aria-label="Billability and leakage">
      <div className="lux-ts-intel__card-glow" aria-hidden="true" />

      <header className="lux-ts-intel__section-head">
        <div>
          <h4>
            <i className="fe fe-pie-chart" aria-hidden="true" />
            Billability &amp; leakage
          </h4>
          <p>{billability.leakageHint}</p>
        </div>
        <div
          className="lux-ts-intel__ring"
          style={{ "--lux-active-pct": `${billability.billablePct || 0}%` }}
          title="Billable share of work hours"
        >
          <span>
            <CountUp end={billability.billablePct || 0} duration={0.6} />%
          </span>
        </div>
      </header>

      <div className="lux-ts-intel__billability-metrics">
        <article className="lux-ts-intel__billability-metric is-billable">
          <i className="fe fe-briefcase" aria-hidden="true" />
          <div>
            <span>Billable share</span>
            <strong>
              <CountUp end={billability.billablePct || 0} duration={0.5} />%
            </strong>
          </div>
        </article>
        <article className="lux-ts-intel__billability-metric is-leakage">
          <i className="fe fe-trending-down" aria-hidden="true" />
          <div>
            <span>Leakage share</span>
            <strong>
              <CountUp end={billability.leakagePct || 0} duration={0.5} />%
            </strong>
          </div>
        </article>
      </div>

      {billability.typeChart && billability.typeChart.length > 0 ? (
        <div className="lux-ts-intel__chart-block">
          <header className="lux-ts-intel__chart-head">
            <h5>Hours mix</h5>
            <span>Work-hour distribution</span>
          </header>
          <ul className="lux-ts-intel__billability-chart">
            {billability.typeChart.map((row) => (
              <li key={row.code}>
                <span className="lux-ts-intel__chart-label">{row.code}</span>
                <div className="lux-ts-intel__bar-track">
                  <div
                    className={classNames("lux-ts-intel__bar-fill", {
                      "is-leakage": row.code === "Non-billable",
                      "is-leave": row.code === "Leave / holiday",
                      "is-strong": row.code === "Billable",
                    })}
                    style={{ width: `${Math.max(row.pct, 4)}%` }}
                  />
                </div>
                <span className="lux-ts-intel__chart-value">
                  {row.hoursLabel ? `${row.hoursLabel} · ` : ""}
                  {row.pct}%
                </span>
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <p className="lux-ts-intel__empty">
          No hours logged this week yet — enter time on the weekly grid to see billability mix.
        </p>
      )}

      {billability.dailyChart && billability.dailyChart.length > 0 ? (
        <div className="lux-ts-intel__daily-chart">
          <header className="lux-ts-intel__chart-head">
            <h5>
              <i className="fe fe-activity" aria-hidden="true" />
              Daily billable rate
            </h5>
            <span>Elapsed days this week</span>
          </header>
          <ul>
            {billability.dailyChart.map((day) => (
              <li key={day.label}>
                <span className="lux-ts-intel__chart-label">{day.label}</span>
                <div className="lux-ts-intel__bar-track">
                  <div
                    className={classNames("lux-ts-intel__bar-fill", {
                      "is-weak": day.billablePct < 60,
                      "is-strong": day.billablePct >= 80,
                    })}
                    style={{ width: `${Math.max(day.billablePct, day.billablePct > 0 ? 4 : 0)}%` }}
                  />
                </div>
                <span className="lux-ts-intel__chart-value">{day.billablePct}%</span>
              </li>
            ))}
          </ul>
        </div>
      ) : null}
    </section>
  );
}
