import React from "react";
import classNames from "classnames/bind";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import { commonUtils } from "_helpers";
import LuxCreateSectionCard from "views/common/create/LuxCreateSectionCard";
import LuxCreateFieldGroup, { LuxCreateField } from "views/common/create/LuxCreateFieldGroup";
import { CREATE_BID_SECTION_META } from "./createBid.sections";
import CountriesData from "./bidRequestForm/CountriesData";
import BidRequestTargetGroupField from "./bidRequestForm/BidRequestTargetGroupField";
import BidRequestQuestions from "./bidRequestForm/BidRequestQuestions";

const STUDY_TYPE_OPTIONS = [
  { value: "ADHOC", label: "Adhoc" },
  { value: "FTEMS", label: "FTE-Managed Services" },
  { value: "FTESA", label: "FTE-Staff-Aug" },
  { value: "SERVICES", label: "Services" },
  { value: "PRODUCT", label: "Product" },
  { value: "TRACKER", label: "Tracker" },
  { value: "TMHB", label: "T & M (Hourly Billing)" },
];

function CreateBidRequestForm({
  bidRequest,
  readOnly,
  isWizardMode,
  fieldConfig,
  createConfig,
  allEmployees,
  studyTypeConfig,
  screeningQuestions,
  additionalQuestions,
  quotaInformation,
  selectedKindOfStudies,
  onChange,
  onTypeDataChange,
  onFormError,
  isSectionVisible,
}) {
  if (!bidRequest) return null;

  const meta = CREATE_BID_SECTION_META;
  const formProps = {
    readOnly,
    fieldConfig,
    mappingObject: bidRequest,
    onChange,
    onFormError,
  };

  const showKindSpecify =
    bidRequest.kindOfStudies &&
    bidRequest.kindOfStudies.find(
      (ks) => ks.startsWith("Others") || ks.startsWith("Offline Qualitative")
    );

  const showCountriesDetail =
    bidRequest.kindOfStudies && bidRequest.countries && bidRequest.countries.length > 0;

  const isTracker = bidRequest.type === "TRACKER";

  return (
    <div
      className={classNames("lux-bid-form", {
        "lux-bid-form--wizard": isWizardMode,
        "lux-bid-form--full": !isWizardMode,
      })}
    >
      <div
        className={classNames("lux-bid-form__layout", {
          "lux-bid-form__layout--split": !isWizardMode,
        })}
      >
        {isSectionVisible("studyBasics") && (
          <div className="lux-bid-form__pane">
            <LuxCreateSectionCard
              icon={meta.studyBasics.icon}
              title={meta.studyBasics.title}
              hint={meta.studyBasics.hint}
              description={meta.studyBasics.description}
            >
              <LuxCreateFieldGroup
                title="Study identity"
                description="How the study is classified and named for your team."
                columns={isWizardMode ? 2 : 2}
              >
                <LuxCreateField span="full">
                  <CustomInput
                    {...formProps}
                    type="select"
                    label="Mode and kind of study"
                    name="kindOfStudies"
                    configName="kindOfStudy"
                    createConfig={createConfig}
                    isAppConfig={true}
                    datatype="alpnumspace"
                    multi={true}
                  />
                </LuxCreateField>
                {showKindSpecify && (
                  <LuxCreateField span="full">
                    <div className="lux-bid-form__inset">
                      <CustomInput
                        {...formProps}
                        inputtype="text"
                        label="Specify kind of study"
                        name="specifyKindOfStudy"
                        placeholder="Specify kind of study…"
                        datatype="alpnumspl"
                      />
                    </div>
                  </LuxCreateField>
                )}
                <LuxCreateField span="full">
                  <CustomInput
                    {...formProps}
                    inputtype="text"
                    label="Study name"
                    name="studyName"
                    placeholder="Study name…"
                    datatype="alpnumspl"
                  />
                </LuxCreateField>
              </LuxCreateFieldGroup>

              <LuxCreateFieldGroup
                title="Client & feasibility"
                description="Commercial context and expected study metrics."
                columns={2}
              >
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    type="select"
                    label="Client name"
                    name="clientName"
                    placeholder="Client name…"
                    isAppConfig={true}
                    createConfig={createConfig}
                  />
                </LuxCreateField>
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    inputtype="text"
                    label="Number of OEs"
                    name="numberOfOes"
                    placeholder="Number of OEs…"
                    datatype="num"
                  />
                </LuxCreateField>
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    inputtype="text"
                    label="Proposed LOI"
                    name="proposedLoi"
                    placeholder="Proposed LOI…"
                    datatype="alpnumspace"
                  />
                </LuxCreateField>
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    type="radios"
                    label="Target CPI in mind"
                    name="targetCPI"
                    placeholder="Is there a target CPI in mind."
                  />
                </LuxCreateField>
                <LuxCreateField span="full">
                  <CustomInput
                    {...formProps}
                    inputtype="text"
                    label="Expected IR for the study"
                    name="expectedIR"
                    placeholder="Expected IR…"
                    datatype="alpnumspace"
                  />
                </LuxCreateField>
              </LuxCreateFieldGroup>

              <LuxCreateFieldGroup
                title="Geography & sample"
                description="Countries and per-country audience breakdown."
                columns={1}
              >
                <LuxCreateField span="full">
                  <CustomInput
                    {...formProps}
                    type="select"
                    label="Countries and sample size per wave per country"
                    name="countries"
                    placeholder="Countries…"
                    isAppConfig={true}
                    createConfig={createConfig}
                    multi={true}
                  />
                </LuxCreateField>
                {showCountriesDetail && (
                  <LuxCreateField span="full">
                    <CountriesData
                      name="countriesData"
                      readOnly={readOnly}
                      onChange={onChange}
                      countriesData={bidRequest.countriesData}
                      selectedKindOfStudies={selectedKindOfStudies}
                      selectedCountries={bidRequest.countries}
                      onFormError={onFormError}
                      createConfig={createConfig}
                      fieldConfig={fieldConfig}
                    />
                  </LuxCreateField>
                )}
              </LuxCreateFieldGroup>

              <LuxCreateFieldGroup
                title="Ownership"
                description="Team, bid owner, and tagged collaborators."
                columns={2}
              >
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    type="select"
                    label="Owner user team"
                    name="userTeamId"
                    readOnlyValue={
                      bidRequest.ownerUserTeamDetails &&
                      bidRequest.ownerUserTeamDetails.name
                    }
                    isIdAsSelectValue={false}
                    placeholder="Owner user team…"
                    options={
                      commonUtils.getUserTeamsFromUserItem() &&
                      commonUtils.convertObjectToSelectObject(
                        commonUtils.getUserTeamsFromUserItem()
                      )
                    }
                  />
                </LuxCreateField>
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    type="select"
                    label="Bid request owner"
                    name="bidRequestOwner"
                    readOnlyValue={
                      bidRequest.ownerDetails && bidRequest.ownerDetails.name
                    }
                    placeholder="Bid request owner…"
                    options={
                      allEmployees &&
                      commonUtils.convertObjectToSelectObject(allEmployees)
                    }
                  />
                </LuxCreateField>
                <LuxCreateField span="full">
                  <CustomInput
                    {...formProps}
                    type="select"
                    label="Tag employees"
                    name="tagEmployees"
                    placeholder="Tag employees…"
                    options={
                      allEmployees &&
                      commonUtils.convertEmployeeEmailToSelectObject(allEmployees)
                    }
                    multi={true}
                  />
                </LuxCreateField>
              </LuxCreateFieldGroup>
            </LuxCreateSectionCard>
          </div>
        )}

        {isSectionVisible("studyDetails") && (
          <div className="lux-bid-form__pane">
            <LuxCreateSectionCard
              icon={meta.studyDetails.icon}
              title={meta.studyDetails.title}
              hint={meta.studyDetails.hint}
              description={meta.studyDetails.description}
            >
              <LuxCreateFieldGroup
                title="Commercial setup"
                description="Identifiers, study type, and tracker-specific fields."
                columns={2}
              >
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    inputtype="text"
                    label="Sales force ID"
                    name="salesForceId"
                    placeholder="Sales force ID…"
                    datatype="alpnumspace"
                  />
                </LuxCreateField>
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    type="select"
                    label="Study type"
                    name="type"
                    placeholder="Study type…"
                    options={STUDY_TYPE_OPTIONS}
                  />
                </LuxCreateField>
                {isTracker && (
                  <LuxCreateField span="full">
                    <div className="lux-bid-form__inset lux-bid-form__inset--tracker">
                      <LuxCreateFieldGroup title="Tracker waves" columns={3}>
                        <LuxCreateField>
                          <CustomInput
                            readOnly={readOnly}
                            inputtype="text"
                            label="Number of waves"
                            name="numberOfWaves"
                            fieldConfig={fieldConfig}
                            mappingObject={bidRequest.typeData}
                            onChange={onTypeDataChange}
                            onFormError={onFormError}
                            placeholder="Waves…"
                            datatype="num"
                          />
                        </LuxCreateField>
                        <LuxCreateField>
                          <CustomInput
                            readOnly={readOnly}
                            inputtype="text"
                            label="Frequency"
                            name="frequency"
                            fieldConfig={fieldConfig}
                            mappingObject={bidRequest.typeData}
                            onChange={onTypeDataChange}
                            onFormError={onFormError}
                            placeholder="Frequency…"
                            datatype="num"
                          />
                        </LuxCreateField>
                        <LuxCreateField>
                          <CustomInput
                            readOnly={readOnly}
                            inputtype="text"
                            label="Exclusion period"
                            name="exclusionPeriod"
                            fieldConfig={fieldConfig}
                            mappingObject={bidRequest.typeData}
                            onChange={onTypeDataChange}
                            onFormError={onFormError}
                            placeholder="Exclusion…"
                            datatype="num"
                          />
                        </LuxCreateField>
                      </LuxCreateFieldGroup>
                    </div>
                  </LuxCreateField>
                )}
              </LuxCreateFieldGroup>

              <LuxCreateFieldGroup
                title="Timing"
                description="Field window and launch expectations."
                columns={2}
              >
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    inputtype="text"
                    label="Field time available"
                    name="fieldTime"
                    placeholder="Field time…"
                    datatype="num"
                  />
                </LuxCreateField>
                <LuxCreateField>
                  <CustomInput
                    {...formProps}
                    inputtype="text"
                    label="Tentative FW launch time"
                    name="launchTime"
                    placeholder="Launch time…"
                    datatype="num"
                  />
                </LuxCreateField>
              </LuxCreateFieldGroup>

              <LuxCreateFieldGroup
                title="Objectives & audience"
                description="Study goals and target group configuration."
                columns={1}
              >
                <LuxCreateField span="full">
                  <CustomInput
                    {...formProps}
                    type="textarea"
                    label="Study objective"
                    name="objective"
                    rows={4}
                    placeholder="Study objective…"
                    datatype="alpnumspl"
                  />
                </LuxCreateField>
                <LuxCreateField span="full">
                  <BidRequestTargetGroupField
                    bidRequest={bidRequest}
                    readOnly={readOnly}
                    fieldConfig={fieldConfig}
                    createConfig={createConfig}
                    studyTypeConfig={studyTypeConfig}
                    onChange={onChange}
                    onFormError={onFormError}
                  />
                </LuxCreateField>
              </LuxCreateFieldGroup>
            </LuxCreateSectionCard>
          </div>
        )}
      </div>

      {isSectionVisible("screening") && (
        <div className="lux-bid-form__pane lux-bid-form__pane--full">
          <LuxCreateSectionCard
            icon={meta.screening.icon}
            title={meta.screening.title}
            hint={meta.screening.hint}
            description={meta.screening.description}
          >
            <BidRequestQuestions
              header="Screening questions"
              name="screeningQuestions"
              readOnly={readOnly}
              questionData={bidRequest.screeningQuestions}
              questionsConfig={screeningQuestions}
              onChange={onChange}
            />
          </LuxCreateSectionCard>
        </div>
      )}

      {isSectionVisible("additional") && (
        <div className="lux-bid-form__pane lux-bid-form__pane--full">
          <LuxCreateSectionCard
            icon={meta.additional.icon}
            title={meta.additional.title}
            hint={meta.additional.hint}
            description={meta.additional.description}
          >
            <BidRequestQuestions
              header="Additional questions"
              name="additionalQuestions"
              readOnly={readOnly}
              questionData={bidRequest.additionalQuestions}
              questionsConfig={additionalQuestions}
              onChange={onChange}
            />
          </LuxCreateSectionCard>
        </div>
      )}

      {isSectionVisible("quota") && (
        <div className="lux-bid-form__pane lux-bid-form__pane--full">
          <LuxCreateSectionCard
            icon={meta.quota.icon}
            title={meta.quota.title}
            hint={meta.quota.hint}
            description={meta.quota.description}
          >
            <BidRequestQuestions
              header="Quota information"
              name="quotaInformation"
              readOnly={readOnly}
              questionData={bidRequest.quotaInformation}
              questionsConfig={quotaInformation}
              onChange={onChange}
            />
          </LuxCreateSectionCard>
        </div>
      )}
    </div>
  );
}

export default CreateBidRequestForm;
