/**
 * F02-T9: Sensitive field display using persona masking policy.
 */

const MASK_HIDDEN = "HIDDEN";
const MASK_MASKED = "MASKED";

export function resolveMaskedFieldValue(fieldKey, rawValue, maskingPolicy) {
  if (rawValue == null || rawValue === "") {
    return "—";
  }
  const policy = maskingPolicy || {};
  const level = policy[fieldKey];
  if (level === MASK_HIDDEN) {
    return "Restricted";
  }
  if (level === MASK_MASKED) {
    return "••••••";
  }
  return rawValue;
}

export function isFieldVisible(fieldKey, maskingPolicy) {
  const policy = maskingPolicy || {};
  return policy[fieldKey] !== MASK_HIDDEN;
}
