import React, { useEffect, useRef } from "react";
import classNames from "classnames/bind";

const FOCUSABLE =
  'a[href], button:not([disabled]), textarea:not([disabled]), input:not([disabled]), select:not([disabled]), [tabindex]:not([tabindex="-1"])';

/**
 * Reusable luxury right panel shell for create/update flows (employees, projects, etc.).
 * Escape closes; Tab cycles focus inside the open panel.
 */
function LuxCreatePanelShell({
  show,
  onClose,
  kicker,
  title,
  subtitle,
  toolbar,
  children,
  panelId,
  className,
  size = "lg",
}) {
  const panelRef = useRef(null);
  const previouslyFocused = useRef(null);

  useEffect(() => {
    if (!show) {
      return undefined;
    }

    previouslyFocused.current = document.activeElement;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    const panel = panelRef.current;
    const focusFirst = () => {
      if (!panel) {
        return;
      }
      const nodes = panel.querySelectorAll(FOCUSABLE);
      const target = nodes[0] || panel;
      if (target && typeof target.focus === "function") {
        target.focus();
      }
    };
    const frame = window.requestAnimationFrame(focusFirst);

    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        onClose();
        return;
      }
      if (event.key !== "Tab" || !panel) {
        return;
      }
      const nodes = Array.from(panel.querySelectorAll(FOCUSABLE)).filter(
        (el) => el.offsetParent !== null || el === document.activeElement
      );
      if (!nodes.length) {
        return;
      }
      const first = nodes[0];
      const last = nodes[nodes.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.cancelAnimationFrame(frame);
      document.body.style.overflow = previousOverflow;
      window.removeEventListener("keydown", onKeyDown);
      const prev = previouslyFocused.current;
      if (prev && typeof prev.focus === "function") {
        prev.focus();
      }
    };
  }, [show, onClose]);

  return (
    <>
      {show && (
        <button
          type="button"
          className="lux-create-panel__backdrop"
          aria-label="Close panel"
          onClick={onClose}
        />
      )}
      <aside
        ref={panelRef}
        id={panelId || "lux-create-panel"}
        className={classNames(
          "right_sidebar",
          "lux-create-panel",
          "lux-overlay-shell",
          "lux-overlay-shell--create",
          size && `lux-create-panel--size-${size}`,
          className,
          { open: show }
        )}
        role="dialog"
        aria-modal={show ? "true" : undefined}
        aria-hidden={!show}
        aria-label={title}
        tabIndex={-1}
      >
        <header className="lux-create-panel__header">
          <div className="lux-create-panel__header-main">
            <div className="lux-create-panel__header-copy">
              {kicker && <p className="lux-create-panel__kicker">{kicker}</p>}
              <h2 className="lux-create-panel__title">{title}</h2>
              {subtitle && <p className="lux-create-panel__subtitle">{subtitle}</p>}
            </div>
            <button
              type="button"
              className="lux-create-panel__close"
              onClick={onClose}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </div>
          {toolbar && <div className="lux-create-panel__header-toolbar">{toolbar}</div>}
        </header>
        {show && <div className="lux-create-panel__body">{children}</div>}
      </aside>
    </>
  );
}

export default LuxCreatePanelShell;
