import React, { Component } from "react";
import { connect } from "react-redux";
import { accessUtils } from "_helpers";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import PurchaseOrderDetailsGeneral from "../PurchaseOrderDetailsGeneral";

class ViewPurchaseOrderDetailsSidebar extends Component {
  constructor() {
    super();
    this.state = {
      permission: accessUtils.getPurchaseOrderAccessControl(),
    };
  }

  render() {
    const { show, onCloseViewPurchaseOrder, purchaseOrderInfo } = this.props;

    return (
      <LuxCreatePanelShell
        show={show}
        onClose={onCloseViewPurchaseOrder}
        panelId="viewpurchaseorderdetailssidebar"
        className="view_project_right_sidebar lux-view-po-panel"
        kicker="Purchase order"
        title="Purchase order details"
        subtitle={
          purchaseOrderInfo && purchaseOrderInfo.name
            ? purchaseOrderInfo.name
            : "View contract, estimates, and checklist"
        }
      >
        {show && purchaseOrderInfo && (
          <div className="lux-create-panel__scroll lux-view-po-panel__scroll lux-bid-detail__view-body">
            <PurchaseOrderDetailsGeneral
              item={purchaseOrderInfo}
              readOnly={true}
              permission={this.state.permission}
              compactView={true}
            />
          </div>
        )}
      </LuxCreatePanelShell>
    );
  }
}

const mapStateToProps = (state) => ({
  purchaseOrderInfo: state.purchaseOrders.selectedPurchaseOrderInfo,
  isLoading: state.projects.loading,
});

export default connect(mapStateToProps)(ViewPurchaseOrderDetailsSidebar);
