import React from "react";

function LeaveOverlapConflictBanner({ message, linkedLeave, onDismiss }) {
  if (!message) return null;

  return (
    <div className="lux-leave-overlap" role="alert">
      <span className="lux-leave-overlap__icon" aria-hidden="true">
        <i className="fe fe-alert-triangle" />
      </span>
      <div className="lux-leave-overlap__body">
        <strong>Overlapping leave detected</strong>
        <p>{message}</p>
        {linkedLeave && (
          <p className="lux-leave-overlap__linked">
            Existing record: {linkedLeave.leaveTypeDescription || linkedLeave.leaveTypeCode} (
            {linkedLeave.source || "HR"})
          </p>
        )}
      </div>
      {onDismiss && (
        <button type="button" className="lux-leave-overlap__dismiss" onClick={onDismiss}>
          Dismiss
        </button>
      )}
    </div>
  );
}

export default LeaveOverlapConflictBanner;
