import { dashboardActions } from "_actions";
import { store } from "_helpers";
import classNames from "classnames/bind";
import React, { Component } from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import SettingsTabShell from "../settings/SettingsTabShell";
import LuxCreateSectionCard from "views/common/create/LuxCreateSectionCard";
import {
  buildServiceHealthSummary,
  getHealthStatusMeta,
} from "../settings/settingsTab.utils";

function HealthServiceRow({ health }) {
  const meta = getHealthStatusMeta(health.status);
  const name = health.serviceName || health.hostName || "Unknown service";

  return (
    <li className={classNames("lux-health-row", `is-${meta.tone}`)} role="listitem">
      <span className={classNames("lux-health-row__icon", `is-${meta.tone}`)} aria-hidden="true">
        <i className={meta.icon} />
      </span>
      <div className="lux-health-row__copy">
        <strong className="lux-health-row__name">{name}</strong>
        {health.hostName && health.serviceName && health.hostName !== health.serviceName && (
          <span className="lux-health-row__host">{health.hostName}</span>
        )}
      </div>
      <span className={classNames("lux-health-row__pill", `is-${meta.tone}`)}>{meta.label}</span>
    </li>
  );
}

function HealthPanel({ title, hint, icon, items, loading }) {
  return (
    <LuxCreateSectionCard icon={icon} title={title} hint={hint} className="lux-hrms-settings__card">
      {loading && (
        <SkeletonTheme baseColor="#f1f5f9" highlightColor="#e2e8f0">
          <Skeleton count={4} height={48} borderRadius={12} />
        </SkeletonTheme>
      )}
      {!loading && items && items.length > 0 && (
        <ul className="lux-health-panel__list" role="list">
          {items.map((health, index) => (
            <HealthServiceRow key={`${health.serviceName || health.hostName}-${index}`} health={health} />
          ))}
        </ul>
      )}
      {!loading && (!items || items.length === 0) && (
        <p className="lux-health-panel__empty">No services reported in this category.</p>
      )}
    </LuxCreateSectionCard>
  );
}

class ServiceHealthSection extends Component {
  constructor() {
    super();
    this.state = {
      serviceHealth: null,
      loading: true,
    };
  }

  componentDidMount() {
    store.dispatch(
      dashboardActions.getServiceHealth((serviceHealth) => {
        this.setState({
          serviceHealth: serviceHealth || {},
          loading: false,
        });
      })
    );
  }

  render() {
    const { serviceHealth, loading } = this.state;
    const summary = buildServiceHealthSummary(serviceHealth);
    const servers = (serviceHealth && serviceHealth.healthStatusResponses) || [];
    const integrations = (serviceHealth && serviceHealth.serviceStatusResponses) || [];

    return (
      <SettingsTabShell
        icon="fe fe-activity"
        eyebrow="Platform status"
        title="Service health"
        subtitle="Live status of application servers and integration endpoints across your deployment."
        stats={summary.stats}
      >
        <div className="lux-settings-tab__stack lux-health-dashboard">
          <HealthPanel
            title="Server status"
            hint={`${summary.serverCount} infrastructure ${summary.serverCount === 1 ? "node" : "nodes"}`}
            icon="fe fe-server"
            items={servers}
            loading={loading}
          />
          <HealthPanel
            title="Integration services"
            hint={`${summary.integrationCount} connected ${summary.integrationCount === 1 ? "service" : "services"}`}
            icon="fe fe-link"
            items={integrations}
            loading={loading}
          />
        </div>

        {!loading && summary.down > 0 && (
          <p className="lux-hrms-settings__note is-warning">
            <i className="fe fe-alert-triangle" aria-hidden="true" />{" "}
            {summary.down} service{summary.down === 1 ? "" : "s"} need attention. Contact your platform administrator if issues persist.
          </p>
        )}
        {!loading && summary.down === 0 && summary.total > 0 && (
          <p className="lux-hrms-settings__note is-success">
            <i className="fe fe-check-circle" aria-hidden="true" /> All monitored services are reporting healthy.
          </p>
        )}
      </SettingsTabShell>
    );
  }
}

export default ServiceHealthSection;
