import React, { useCallback, useEffect, useMemo, useState } from "react";
import { connect } from "react-redux";
import { withRouter } from "react-router-dom";
import classNames from "classnames/bind";
import { employeeActions, workItemActions } from "_actions";
import { workItemConstants } from "_constants";
import { accessUtils, commonUtils, store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";
import PageInnerHeader from "views/common/PageInnerHeader";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import PageCreateButton from "views/common/fragments/PageCreateButton";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";
import LuxCalendarNav from "views/common/fragments/LuxCalendarNav";
import PlannerAssignWorkPanel from "./components/PlannerAssignWorkPanel";
import { PLANNER_TABS, readPlannerPrefs, writePlannerPrefs } from "./planner.storage";
import {
  buildPlannerRange,
  getPlannerRosterEmployees,
  PLANNER_STATUS_FILTER_OPTIONS,
} from "./planner.utils";
import { readCapacityOverrides, writeCapacityOverride } from "./plannerCapacity.utils";
import { buildEmployeeLeaveMap } from "./plannerLeave.utils";
import {
  loadTeamTimesheetData,
  parseTimesheetActualsByEmployee,
} from "./plannerTimesheet.utils";
import {
  buildAssignPayloadFromDrop,
  evaluateAssignConflict,
} from "./plannerAssign.utils";
import PlannerConflictModal from "./components/PlannerConflictModal";
import PlannerCapacitySettings from "./components/PlannerCapacitySettings";
import TeamCapacitySummary from "./TeamCapacitySummary";
import TeamCapacityRosterView from "./TeamCapacityRosterView";
import TeamCapacityTimelineView from "./TeamCapacityTimelineView";
import TeamCapacityGanttView from "./TeamCapacityGanttView";

function resolveDefaultTab(routePath, search) {
  const tabParam = search && new URLSearchParams(search).get("tab");
  if (tabParam === "roster") return "roster";
  if (tabParam === "timeline") return "timeline";
  if (tabParam === "gantt") return "gantt";
  if (tabParam === "overview") return "overview";
  if (routePath && routePath.includes("taskplanner")) return "roster";
  if (routePath && (routePath.includes("capacity") || routePath.includes("rplanner"))) {
    return "timeline";
  }
  const prefs = readPlannerPrefs();
  return prefs.activeTab || "overview";
}

function TeamCapacityPage(props) {
  const prefs = readPlannerPrefs();
  const accountsPermission = accessUtils.getAccountsAccessControl();

  const [permission] = useState(accessUtils.getTaskPlannerAccessControl());
  const [activeTab, setActiveTab] = useState(() =>
    resolveDefaultTab(
      (props.match && props.match.path) || (props.location && props.location.pathname),
      props.location && props.location.search
    )
  );
  const [filterOptions, setFilterOptions] = useState(
    props.filterOptions || PLANNER_STATUS_FILTER_OPTIONS
  );
  const [horizonWeeks, setHorizonWeeks] = useState(prefs.horizonWeeks || 2);
  const [viewMode, setViewMode] = useState(prefs.viewMode || "TASKS");
  const [weekStartMoment, setWeekStartMoment] = useState(
    dateUtils.getCurrentTime().clone().startOf("isoWeek")
  );
  const [selectedEmployeeId, setSelectedEmployeeId] = useState(
    prefs.selectedEmployeeId != null && prefs.selectedEmployeeId !== ""
      ? prefs.selectedEmployeeId
      : null
  );
  const [reduceForHolidays, setReduceForHolidays] = useState(
    !!prefs.reduceCapacityForHolidays
  );
  const [ganttAxis, setGanttAxis] = useState(prefs.ganttAxis || "EMPLOYEE");
  const [ganttLevel, setGanttLevel] = useState(prefs.ganttLevel || "WORK_ITEM");
  const [timeGranularity, setTimeGranularity] = useState(prefs.timeGranularity || "DAY");
  const [focusDayMoment, setFocusDayMoment] = useState(
    dateUtils.getCurrentTime().clone().startOf("day")
  );
  const [assignContext, setAssignContext] = useState(null);
  const [capacityOverrides, setCapacityOverrides] = useState(() => readCapacityOverrides());
  const [showActuals, setShowActuals] = useState(!!prefs.showActuals);
  const [showCapacitySettings, setShowCapacitySettings] = useState(false);
  const [assignTrayOpen, setAssignTrayOpen] = useState(prefs.assignTrayOpen !== false);
  const [timesheetByEmployee, setTimesheetByEmployee] = useState({});
  const [pendingDrop, setPendingDrop] = useState(null);

  const executiveSummaryOnly = !permission.createEnabled;

  const visibleTabs = executiveSummaryOnly
    ? PLANNER_TABS.filter((t) => t.id === "overview")
    : PLANNER_TABS;

  const getCurrentRange = useCallback(
    (startMoment = weekStartMoment, weeks = horizonWeeks) =>
      buildPlannerRange(startMoment, weeks),
    [weekStartMoment, horizonWeeks]
  );

  const getPlannerUserTeamIds = useCallback(
    () =>
      commonUtils.getSelectedUserTeamIds(
        commonUtils.getUserTeams(props.userTeamsTaskPlanner || props.userTeams)
      ),
    [props.userTeamsTaskPlanner, props.userTeams]
  );

  const reloadEmployees = useCallback(
    (userTeams) => {
      const ids = commonUtils.getSelectedUserTeamIds(userTeams);
      if (ids.length > 0) props.getTeamsEmployees(ids);
    },
    [props]
  );

  const reloadPlannerItems = useCallback(
    (userTeamIds, range) => {
      props.getWorkItemActivities({
        employeeIds: [],
        userTeamIds: userTeamIds || [],
        startDate: range.startDateMoment.format(dateUtils.SERVER_DATE_FORMAT),
        endDate: range.endDateMoment.format(dateUtils.SERVER_DATE_FORMAT),
      });
    },
    [props]
  );

  const reloadHolidays = useCallback((range) => {
    store.dispatch(
      employeeActions.getHolidays({
        startDate: range.startDateMoment.format(dateUtils.SERVER_DATE_FORMAT),
        endDate: range.endDateMoment.format(dateUtils.SERVER_DATE_FORMAT),
      })
    );
  }, []);

  const reloadTimesheets = useCallback(
    (range) => {
      const roster = getPlannerRosterEmployees(props.employees);
      const ids = roster.map((e) => e.id).filter((id) => id != null);
      if (ids.length === 0) {
        setTimesheetByEmployee({});
        return;
      }
      loadTeamTimesheetData(
        props.loadTimeSheetData,
        ids,
        range.startDateMoment.format(dateUtils.SERVER_DATE_FORMAT),
        range.endDateMoment.format(dateUtils.SERVER_DATE_FORMAT)
      ).then((data) => setTimesheetByEmployee(data || {}));
    },
    [props.employees, props.loadTimeSheetData]
  );

  const leaveMap = useMemo(
    () =>
      buildEmployeeLeaveMap({
        workItems: props.workItems || [],
        holidayItems: props.holidayItems,
        timesheetByEmployee,
        employees: props.employees,
      }),
    [props.workItems, props.holidayItems, props.employees, timesheetByEmployee]
  );

  const actualsByEmployee = useMemo(
    () => parseTimesheetActualsByEmployee(timesheetByEmployee),
    [timesheetByEmployee]
  );

  const plannerInsightProps = useMemo(
    () => ({
      leaveMap,
      capacityOverrides,
      actualsByEmployee,
      showActuals,
    }),
    [leaveMap, capacityOverrides, actualsByEmployee, showActuals]
  );

  useEffect(() => {
    if (props.pageHeaderNameChangeHandler) {
      props.pageHeaderNameChangeHandler("Team capacity");
    }
    const userTeams = commonUtils.getUserTeams(props.userTeams);
    store.dispatch({
      type: workItemConstants.INITIALIZE_TASK_PLANNER_USER_TEAMS,
      userTeams,
    });
    const range = getCurrentRange();
    reloadEmployees(userTeams);
    reloadPlannerItems(commonUtils.getSelectedUserTeamIds(userTeams), range);
    reloadHolidays(range);
    reloadTimesheets(range);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    reloadTimesheets(getCurrentRange());
  }, [props.employees, weekStartMoment, horizonWeeks, reloadTimesheets, getCurrentRange]);

  useEffect(() => {
    const path = (props.location && props.location.pathname) || "";
    const nextTab = resolveDefaultTab(path, props.location && props.location.search);
    setActiveTab((prev) => (prev === nextTab ? prev : nextTab));
  }, [props.location && props.location.pathname, props.location && props.location.search]);

  const persistPrefs = (partial) => writePlannerPrefs(partial);

  const handleTabChange = (tabId) => {
    if (executiveSummaryOnly && tabId !== "overview") return;
    setActiveTab(tabId);
    persistPrefs({ activeTab: tabId });
    const { history, location } = props;
    if (history && location) {
      const params = new URLSearchParams(location.search || "");
      if (tabId === "overview") {
        params.delete("tab");
      } else {
        params.set("tab", tabId);
      }
      const search = params.toString();
      history.replace({
        pathname: location.pathname,
        search: search ? `?${search}` : "",
      });
    }
  };

  const handleUserTeamsSelection = (userTeams) => {
    store.dispatch({
      type: workItemConstants.INITIALIZE_TASK_PLANNER_USER_TEAMS,
      userTeams,
    });
    const ids = commonUtils.getSelectedUserTeamIds(userTeams);
    reloadEmployees(userTeams);
    const range = getCurrentRange();
    reloadPlannerItems(ids, range);
    reloadHolidays(range);
    reloadTimesheets(range);
  };

  const handleFilterChange = (newFilterOptions) => {
    setFilterOptions(newFilterOptions);
    store.dispatch({
      type: workItemConstants.CHANGE_FILTER_TASK_PLANNER,
      filterOptions: newFilterOptions,
    });
  };

  const onFilterTextChange = (value) => {
    handleFilterChange({ ...filterOptions, filterText: value });
  };

  const handleEmployeesSelection = (employees) => {
    const ids = commonUtils.getSelectedEmployeeIds(employees);
    const effective = ids.length > 0 ? ids[0] : null;
    setSelectedEmployeeId(effective);
    persistPrefs({ selectedEmployeeId: effective });
  };

  const shiftHorizon = (weeks) => {
    setHorizonWeeks(weeks);
    persistPrefs({ horizonWeeks: weeks });
    reloadPlannerItems(getPlannerUserTeamIds(), getCurrentRange(weekStartMoment, weeks));
    reloadTimesheets(getCurrentRange(weekStartMoment, weeks));
  };

  const goToBack = () => {
    const next = weekStartMoment.clone().subtract(horizonWeeks, "week");
    setWeekStartMoment(next);
    const range = getCurrentRange(next);
    reloadPlannerItems(getPlannerUserTeamIds(), range);
    reloadHolidays(range);
    reloadTimesheets(range);
  };

  const goToNext = () => {
    const next = weekStartMoment.clone().add(horizonWeeks, "week");
    setWeekStartMoment(next);
    const range = getCurrentRange(next);
    reloadPlannerItems(getPlannerUserTeamIds(), range);
    reloadHolidays(range);
    reloadTimesheets(range);
  };

  const goToCurrent = () => {
    const next = dateUtils.getCurrentTime().clone().startOf("isoWeek");
    setWeekStartMoment(next);
    const range = getCurrentRange(next);
    reloadPlannerItems(getPlannerUserTeamIds(), range);
    reloadHolidays(range);
    reloadTimesheets(range);
  };

  const refreshAfterSave = () => {
    reloadPlannerItems(getPlannerUserTeamIds(), getCurrentRange());
  };

  const handleAssignRequest = (ctx) => {
    const employee = ctx && ctx.employee;
    const dayMoment = (ctx && ctx.dayMoment) || focusDayMoment.clone();
    const hour = ctx && ctx.hour;
    const hourStr =
      hour != null ? `${String(hour).padStart(2, "0")}:00` : "08:00";
    setAssignContext({
      key: `${employee && employee.id}-${dayMoment.format("YYYY-MM-DD")}-${hourStr}`,
      employee: employee
        ? {
            id: employee.id,
            name: employee.name,
            userTeamId: employee.userTeamId,
          }
        : null,
      prefillDate: dayMoment.format(dateUtils.SERVER_DATE_FORMAT),
      prefillStartTime: hourStr,
    });
    store.dispatch({ type: workItemConstants.SHOW_TASKPLANNER_CREATE_WINDOW });
  };

  const handleCreateItem = () => {
    setAssignContext(null);
    store.dispatch({ type: workItemConstants.SHOW_TASKPLANNER_CREATE_WINDOW });
  };

  const closeCreateItem = () => {
    store.dispatch({ type: workItemConstants.CLOSE_TASKPLANNER_CREATE_WINDOW });
  };

  const handleCapacityOverride = (employeeId, dailyMinutes) => {
    const next = writeCapacityOverride(employeeId, dailyMinutes);
    setCapacityOverrides(next);
  };

  const commitPlannerDrop = (drop) => {
    if (!drop) return;
    const payload = buildAssignPayloadFromDrop(
      drop.workItem,
      drop.employee,
      drop.dayMoment,
      drop.hour
    );
    store.dispatch(workItemActions.updateWorkItem(payload));
    setPendingDrop(null);
    refreshAfterSave();
  };

  const handleWorkItemDrop = ({ workItemId, employee, dayMoment, hour, allocatedMinutes }) => {
    const workItem = (props.workItems || []).find((w) => String(w.id) === String(workItemId));
    if (!workItem || !employee) return;
    const conflict = evaluateAssignConflict({
      employee,
      dayMoment,
      hour,
      additionalMinutes: workItem.estDurationInMins || 60,
      currentAllocatedMinutes: allocatedMinutes,
      capacityOverrides,
      leaveMap,
    });
    const drop = { workItem, employee, dayMoment, hour, conflict };
    if (conflict.errors.length > 0 || conflict.warnings.length > 0) {
      setPendingDrop(drop);
      return;
    }
    commitPlannerDrop(drop);
  };

  const workItemsForViews = props.filteredWorkItems || props.workItems || [];
  const range = getCurrentRange();
  const rangeLabel = `${weekStartMoment.format("DD MMM")} – ${range.endDateMoment.format("DD MMM YYYY")}`;

  const headerPermission = {
    ...permission,
    switchUserTeamsEnabled:
      permission.switchUserTeamsEnabled || accountsPermission.showAllUserTeamsAccount,
  };

  const showEmployeePicker = activeTab === "timeline" || activeTab === "gantt";

  return (
    <div className="lux-planner-page lux-bid-requests lux-register-page" data-testid="page-team-capacity">
      <LuxModuleIntro
        meta={DENSE_PAGE_META.teamCapacity}
        actions={
          permission.createEnabled && activeTab !== "overview" ? (
            <PageCreateButton onClick={handleCreateItem}>Assign work</PageCreateButton>
          ) : null
        }
      />
      <PageInnerHeader
        userTeams={commonUtils.getUserTeams(
          props.userTeamsTaskPlanner || props.userTeams
        )}
        handleUserTeamsSelection={handleUserTeamsSelection}
        showGridListMenu={false}
        showFilter
        showEmployeeMenu={showEmployeePicker}
        employeeMenuEnabled={showEmployeePicker}
        employeeEnableSingleSelection
        showEmployeeNameDropDownLabel
        applyEmployeeSelectionImmediately
        selectedEmployeeId={selectedEmployeeId}
        allowAllTeamEmployees={showEmployeePicker}
        employees={props.employees}
        handleEmployeesSelection={handleEmployeesSelection}
        showUserTeamMenu
        isLoading={props.isLoading}
        filterOptions={filterOptions}
        handleFilterChange={handleFilterChange}
        onFilterTextChange={onFilterTextChange}
        showDateRangeSelector={false}
        permission={headerPermission}
        enableUserTeamSingleSelection
      />

      <div className="lux-planner-shell">
        <div className="lux-planner-shell__body">
          <div className="lux-planner-shell__intro">
            <div className="lux-planner-shell__intro-main">
              <LuxSummaryEyebrow variant="team-capacity" className="lux-planner-summary__eyebrow">
                Resource planning intelligence
              </LuxSummaryEyebrow>
              {!props.showTaskPlannerCreateModel && (
                <div className="lux-planner-shell__period-row">
                  <LuxCalendarNav
                    onBack={goToBack}
                    onToday={goToCurrent}
                    onNext={goToNext}
                    disabled={props.isLoading}
                  />
                  <span className="lux-planner-shell__range-pill" aria-live="polite">
                    <i className="fe fe-calendar" aria-hidden="true" />
                    {rangeLabel}
                  </span>
                </div>
              )}
            </div>
            <div className="lux-planner-shell__horizon">
                    <span>Horizon</span>
                    <div className="lux-planner-segment">
                      {[1, 2, 4].map((w) => (
                        <button
                          key={w}
                          type="button"
                          className={classNames({ "is-active": horizonWeeks === w })}
                          onClick={() => shiftHorizon(w)}
                        >
                          {w} week{w > 1 ? "s" : ""}
                        </button>
                      ))}
                    </div>
                    {activeTab === "gantt" && (
                      <div className="lux-planner-segment" role="group" aria-label="Gantt time granularity">
                        <button
                          type="button"
                          className={classNames({ "is-active": timeGranularity === "DAY" })}
                          onClick={() => {
                            setTimeGranularity("DAY");
                            persistPrefs({ timeGranularity: "DAY" });
                          }}
                        >
                          By day
                        </button>
                        <button
                          type="button"
                          className={classNames({ "is-active": timeGranularity === "HOUR" })}
                          onClick={() => {
                            setTimeGranularity("HOUR");
                            persistPrefs({ timeGranularity: "HOUR" });
                          }}
                        >
                          By hour
                        </button>
                      </div>
                    )}
                    <label className="lux-planner-shell__holiday">
                      <input
                        type="checkbox"
                        checked={reduceForHolidays}
                        onChange={(e) => {
                          setReduceForHolidays(e.target.checked);
                          persistPrefs({ reduceCapacityForHolidays: e.target.checked });
                        }}
                      />
                      Reduce capacity on holidays
                    </label>
                    <label className="lux-planner-shell__holiday">
                      <input
                        type="checkbox"
                        checked={showActuals}
                        onChange={(e) => {
                          setShowActuals(e.target.checked);
                          persistPrefs({ showActuals: e.target.checked });
                        }}
                      />
                      Show timesheet actuals
                    </label>
                    {!executiveSummaryOnly && (
                      <button
                        type="button"
                        className="lux-planner-btn lux-planner-btn--ghost lux-planner-shell__capacity-btn"
                        onClick={() => setShowCapacitySettings(true)}
                      >
                        <i className="fe fe-sliders" /> Capacity
                      </button>
                    )}
                  </div>
                </div>

                <nav className="lux-planner-nav" aria-label="Planning views">
                  {visibleTabs.map((tab) => (
                    <button
                      key={tab.id}
                      type="button"
                      className={classNames("lux-planner-nav__item", {
                        "is-active": activeTab === tab.id,
                      })}
                      onClick={() => handleTabChange(tab.id)}
                    >
                      <i className={`fe ${tab.icon}`} aria-hidden />
                      <span>{tab.label}</span>
                    </button>
                  ))}
                </nav>

                <div className="lux-planner-shell__view">
                  {activeTab === "overview" && (
                    <TeamCapacitySummary
                      employees={props.employees}
                      workItems={workItemsForViews}
                      projects={props.projects}
                      startMoment={weekStartMoment}
                      horizonWeeks={horizonWeeks}
                      holidayItems={props.holidayItems}
                      reduceForHolidays={reduceForHolidays}
                      filterOptions={filterOptions}
                      isLoading={props.isLoading}
                      executiveSummaryOnly={executiveSummaryOnly}
                      onNavigateTab={handleTabChange}
                      {...plannerInsightProps}
                    />
                  )}

                  {activeTab === "roster" && !executiveSummaryOnly && (
                    <TeamCapacityRosterView
                      employees={props.employees}
                      workItems={workItemsForViews}
                      startMoment={weekStartMoment}
                      horizonWeeks={horizonWeeks}
                      holidayItems={props.holidayItems}
                      reduceForHolidays={reduceForHolidays}
                      filterOptions={filterOptions}
                      isLoading={props.isLoading}
                      history={props.history}
                      canAssign={permission.createEnabled}
                      focusDayMoment={focusDayMoment}
                      onFocusDayChange={(m) => {
                        setFocusDayMoment(m.clone().startOf("day"));
                        persistPrefs({ focusDayKey: m.format("YYYY-MM-DD") });
                      }}
                      onAssignRequest={handleAssignRequest}
                      onWorkItemDrop={handleWorkItemDrop}
                      assignTrayOpen={assignTrayOpen}
                      onAssignTrayToggle={() => {
                        const next = !assignTrayOpen;
                        setAssignTrayOpen(next);
                        persistPrefs({ assignTrayOpen: next });
                      }}
                      {...plannerInsightProps}
                    />
                  )}

                  {activeTab === "timeline" && !executiveSummaryOnly && (
                    <TeamCapacityTimelineView
                      workItems={workItemsForViews}
                      employees={props.employees}
                      selectedEmployeeId={selectedEmployeeId}
                      weekStartMoment={weekStartMoment}
                      horizonWeeks={horizonWeeks}
                      viewMode={viewMode}
                      holidayItems={props.holidayItems}
                      reduceForHolidays={reduceForHolidays}
                      filterOptions={filterOptions}
                      history={props.history}
                      onViewModeChange={(mode) => {
                        setViewMode(mode);
                        persistPrefs({ viewMode: mode });
                      }}
                      canAssign={permission.createEnabled}
                      onAssignRequest={handleAssignRequest}
                      {...plannerInsightProps}
                    />
                  )}

                  {activeTab === "gantt" && !executiveSummaryOnly && (
                    <TeamCapacityGanttView
                      workItems={workItemsForViews}
                      employees={props.employees}
                      weekStartMoment={weekStartMoment}
                      horizonWeeks={horizonWeeks}
                      ganttAxis={ganttAxis}
                      ganttLevel={ganttLevel}
                      filterOptions={filterOptions}
                      selectedEmployeeId={selectedEmployeeId}
                      canEdit={permission.createEnabled}
                      history={props.history}
                      onRescheduled={refreshAfterSave}
                      onGanttAxisChange={(axis) => {
                        setGanttAxis(axis);
                        persistPrefs({ ganttAxis: axis });
                      }}
                      onGanttLevelChange={(level) => {
                        setGanttLevel(level);
                        persistPrefs({ ganttLevel: level });
                      }}
                      timeGranularity={timeGranularity}
                      focusDayMoment={focusDayMoment}
                      onFocusDayChange={(m) => {
                        setFocusDayMoment(m.clone().startOf("day"));
                        persistPrefs({ focusDayKey: m.format("YYYY-MM-DD") });
                      }}
                    />
                  )}
                </div>
        </div>
      </div>

      <PlannerAssignWorkPanel
        show={props.showTaskPlannerCreateModel}
        onClose={closeCreateItem}
        employees={props.employees}
        workItems={workItemsForViews}
        permission={permission}
        weekStartMoment={weekStartMoment}
        horizonWeeks={horizonWeeks}
        holidayItems={props.holidayItems}
        reduceForHolidays={reduceForHolidays}
        filterOptions={filterOptions}
        leaveMap={leaveMap}
        capacityOverrides={capacityOverrides}
        rangeLabel={rangeLabel}
        handleReloadWorkItems={refreshAfterSave}
        assignContext={assignContext}
        minDate={
          weekStartMoment &&
          workItemUtils.getWorkItemCreateStartMinDate(weekStartMoment.clone(), permission)
        }
        maxDate={
          weekStartMoment &&
          workItemUtils.getWorkItemCreateEndMaxDate(range.endDateMoment.clone(), permission)
        }
      />

      <PlannerConflictModal
        pending={pendingDrop}
        onCancel={() => setPendingDrop(null)}
        onConfirm={() => commitPlannerDrop(pendingDrop)}
      />

      <PlannerCapacitySettings
        open={showCapacitySettings}
        onClose={() => setShowCapacitySettings(false)}
        employees={props.employees}
        capacityOverrides={capacityOverrides}
        onSaveOverride={handleCapacityOverride}
      />
    </div>
  );
}

const mapStateToProps = (state) => ({
  isLoading: state.workItem.isLoadingCompleted,
  projects: state.projects.items,
  workItems: state.workItem.workItems,
  filteredWorkItems:
    state.workItem.workItems &&
    commonUtils.filterWorkItems(
      state.workItem.workItems,
      state.workItem.filterOptionsTaskPlanner || PLANNER_STATUS_FILTER_OPTIONS
    ),
  employees: state.employees.teamEmployees,
  userTeamsTaskPlanner: state.workItem.userTeamsTaskPlanner,
  userTeams: state.authentication.userTeams,
  holidayItems: state.employees.holidayItems,
  filterOptions: state.workItem.filterOptionsTaskPlanner,
  showTaskPlannerCreateModel: state.workItem.showTaskPlannerCreateModel,
});

const mapDispatchToProps = {
  getTeamsEmployees: employeeActions.getTeamsEmployees,
  getWorkItemActivities: workItemActions.getWorkItemActivities,
  loadTimeSheetData: workItemActions.loadTimeSheetData,
};

export default withRouter(connect(mapStateToProps, mapDispatchToProps)(TeamCapacityPage));
