/**
 * F02-T9: Employee 360 scope and tab visibility enforcement.
 */

import { EMPLOYEE_360_TABS } from "config/employee360.config";
import { isItemVisibleForPersona } from "config/persona-navigation.utils";

const ORG_WIDE_PERSONAS = ["ADMIN", "HR_ADMIN", "EXECUTIVE"];
const TEAM_SCOPED_PERSONAS = ["MANAGER", "PROJECT_MANAGER", "RESOURCE_MANAGER"];
const PAYROLL_FINANCE_PERSONAS = ["PAYROLL_MANAGER", "FINANCE_MANAGER"];

export function buildEmployee360ViewerContext(personaContext, currentUser) {
  const user = currentUser || {};
  return {
    activePersona: (personaContext && personaContext.activePersona) || "EMPLOYEE",
    scopeType: (personaContext && personaContext.scopeType) || "SELF",
    scopeIds: (personaContext && personaContext.scopeIds) || [],
    viewerEmployeeId: user.id || (personaContext && personaContext.employeeId) || null,
    viewerTeamId:
      (user.defaultUserTeamDetails && user.defaultUserTeamDetails.id) || null,
    maskingPolicy: (personaContext && personaContext.maskingPolicy) || {},
  };
}

/**
 * Client-side scope guard until server returns accessAllowed on aggregate API.
 */
export function canViewEmployee360(viewerContext, targetEmployeeId, employee, apiAccessAllowed) {
  if (!targetEmployeeId) {
    return false;
  }
  if (apiAccessAllowed === false) {
    return false;
  }
  if (apiAccessAllowed === true) {
    return true;
  }

  const ctx = viewerContext || {};
  const viewerId = ctx.viewerEmployeeId;
  if (!viewerId) {
    return false;
  }

  if (String(viewerId) === String(targetEmployeeId)) {
    return true;
  }

  const persona = ctx.activePersona || "EMPLOYEE";
  const scopeType = ctx.scopeType || "SELF";

  if (ORG_WIDE_PERSONAS.includes(persona) || scopeType === "ORG" || scopeType === "ADMIN") {
    return true;
  }

  if (PAYROLL_FINANCE_PERSONAS.includes(persona)) {
    return true;
  }

  if (scopeType === "SELF") {
    return false;
  }

  if (scopeType === "TEAM" || TEAM_SCOPED_PERSONAS.includes(persona)) {
    const employeeTeamId =
      employee && employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.id;
    if (
      ctx.viewerTeamId &&
      employeeTeamId &&
      String(ctx.viewerTeamId) === String(employeeTeamId)
    ) {
      return true;
    }
    if (employee && employee.managerId && String(employee.managerId) === String(viewerId)) {
      return true;
    }
  }

  if (Array.isArray(ctx.scopeIds) && ctx.scopeIds.length > 0) {
    if (ctx.scopeIds.some((id) => String(id) === String(targetEmployeeId))) {
      return true;
    }
    const employeeTeamId =
      employee && employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.id;
    if (
      employeeTeamId &&
      ctx.scopeIds.some((id) => String(id) === String(employeeTeamId))
    ) {
      return true;
    }
  }

  return false;
}

export function getVisibleEmployee360Tabs(activePersona, apiVisibleTabIds) {
  let tabs = EMPLOYEE_360_TABS.filter((tab) =>
    isItemVisibleForPersona({ personas: tab.personas }, activePersona)
  );

  if (Array.isArray(apiVisibleTabIds) && apiVisibleTabIds.length > 0) {
    const allowed = new Set(apiVisibleTabIds);
    tabs = tabs.filter((tab) => allowed.has(tab.id));
  }

  return tabs;
}

export function resolveEmployee360AccessDeniedReason(viewerContext, targetEmployeeId) {
  const persona = (viewerContext && viewerContext.activePersona) || "EMPLOYEE";
  if (String(viewerContext && viewerContext.viewerEmployeeId) === String(targetEmployeeId)) {
    return null;
  }
  if (persona === "EMPLOYEE") {
    return "You can only open Employee 360 for your own profile.";
  }
  if (TEAM_SCOPED_PERSONAS.includes(persona)) {
    return "This employee is outside your team scope.";
  }
  return "You do not have permission to view this employee's 360 profile.";
}
