import React from "react";
import CountUp from "react-countup";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

function MetricCard({ label, value, tone, suffix, decimals }) {
  return (
    <article className={`lux-hrms-dash__kpi lux-leave-analytics__kpi is-${tone || "neutral"}`}>
      <div className="lux-hrms-dash__kpi-top">
        <span className="lux-hrms-dash__kpi-label">{label}</span>
      </div>
      <strong className="lux-hrms-dash__kpi-value">
        <CountUp end={Number(value) || 0} decimals={decimals != null ? decimals : suffix ? 0 : 1} duration={0.55} />
        {suffix || ""}
      </strong>
    </article>
  );
}

export default function LeaveAnalyticsPanel({ analytics, loading }) {
  if (loading) {
    return <div className="lux-leave-subpanel lux-leave-analytics is-loading" aria-busy="true" />;
  }
  if (!analytics) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact lux-leave-empty"
        icon="fe fe-activity"
        title="Insights unavailable"
        description="Leave analytics will appear when enhancement data is loaded."
      />
    );
  }

  return (
    <section className="lux-leave-subpanel lux-leave-analytics" aria-label="Leave analytics">
      <header className="lux-leave-subpanel__head">
        <div>
          <span className="lux-leave-subpanel__eyebrow">Insights</span>
          <h3 className="lux-leave-subpanel__title">Leave insights</h3>
          <p className="lux-leave-subpanel__sub">Utilization, LWP exposure, coverage risk, and approval SLA</p>
        </div>
      </header>

      <div className="lux-hrms-dash__kpi-strip lux-leave-analytics__strip">
        <MetricCard label="Leave utilization" value={analytics.utilizationPct || 0} suffix="%" tone="primary" />
        <MetricCard label="LWP days" value={analytics.lwpDays} tone="amber" />
        <MetricCard label="Upcoming leave" value={analytics.upcomingDays} tone="violet" />
        <MetricCard label="Pending approval" value={analytics.approvalPendingDays} tone="rose" />
        <MetricCard label="Coverage risk days" value={analytics.coverageRiskDays} tone="slate" decimals={0} />
      </div>

      <p className="lux-leave-analytics__sla">{analytics.approvalSlaHint}</p>

      {analytics.typeChart && analytics.typeChart.length > 0 && (
        <div className="lux-leave-analytics__chart">
          <h4>Approved days by leave type</h4>
          <ul>
            {analytics.typeChart.map((row) => (
              <li key={row.code}>
                <span className="lux-leave-analytics__chart-label">{row.code}</span>
                <div className="lux-leave-analytics__bar-track">
                  <div className="lux-leave-analytics__bar-fill" style={{ width: `${row.pct}%` }} />
                </div>
                <span className="lux-leave-analytics__chart-value">{row.days}d</span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </section>
  );
}
