import React, { Component } from "react";
import CountUp from "react-countup";
import { commonUtils } from "_helpers";
import ProjectDetailsTabShell from "./ProjectDetailsTabShell";
import ProjectDetailsSummaryStats from "./ProjectDetailsSummaryStats";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "views/common/fragments/luxSkeleton.constants";
import { getDashboardTabStats } from "./projectDetailsTab.utils";

class ProjectDetailsDashboard extends Component {
  renderCategoryRows() {
    const items = this.props.taskStatisticsByCategory;
    if (!items || !items.length) return null;

    return (
      <div className="lux-pd-dashboard__categories">
        <header className="lux-pd-dashboard__categories-head">
          <h4>By deliverable category</h4>
          <span>Completed vs in progress per category</span>
        </header>
        <ul className="lux-pd-dashboard__category-list">
          {items.map((item, index) => {
            const completed = item.completedCount || 0;
            const inProgress = item.inProgressCount || 0;
            const pct = commonUtils.getPercentageOfCompletion(completed, inProgress);
            return (
              <li key={item.category || index} className="lux-pd-dashboard__category-row">
                <div className="lux-pd-dashboard__category-meta">
                  <strong title={item.category}>{item.category || "Other"}</strong>
                  <span>
                    <CountUp end={completed} duration={0.6} /> done ·{" "}
                    <CountUp end={inProgress} duration={0.6} /> active
                  </span>
                </div>
                <div className="lux-pd-dashboard__category-bar" aria-hidden="true">
                  <span className="lux-pd-dashboard__category-fill" style={{ width: `${pct}%` }} />
                </div>
              </li>
            );
          })}
        </ul>
      </div>
    );
  }

  render() {
    const { projectInfo, readOnly, isLoading, taskStatisticsByCategory, getTaskStatisticsByCategory } =
      this.props;
    const hasCategories = taskStatisticsByCategory && taskStatisticsByCategory.length > 0;
    const tabStats = getDashboardTabStats(taskStatisticsByCategory).map((s) => ({
      ...s,
      value: isLoading && !hasCategories ? "…" : s.value,
    }));

    return (
      <ProjectDetailsTabShell
        icon="fe fe-pie-chart"
        eyebrow="Analytics"
        title="Project dashboard"
        subtitle="Deliverable workload and completion breakdown for this project."
        stats={tabStats}
      >
        <div className="lux-pd-dashboard">
          {!readOnly && projectInfo && (
            <ProjectDetailsSummaryStats
              items={taskStatisticsByCategory}
              loadData={getTaskStatisticsByCategory}
              itemId={projectInfo.id}
            />
          )}

          {hasCategories ? (
            this.renderCategoryRows()
          ) : (
            !isLoading && (
              <LuxRegisterEmptyState
                variant="deliverables"
                eyebrow="No metrics yet"
                title="No dashboard data"
                description="Work item statistics will appear once deliverables are created and tracked on this project."
                hints={[
                  "Open Overview for project facts and timeline",
                  "Assign the project to unlock deliverables",
                ]}
                className="lux-pd-tab__empty"
              />
            )
          )}

          {isLoading && !hasCategories && (
            <div className="lux-pd-tab__loading" aria-busy="true">
              <SkeletonTheme baseColor={LUX_SKELETON_THEME.baseColor} highlightColor={LUX_SKELETON_THEME.highlightColor}>
                <Skeleton height={120} borderRadius={14} />
                <Skeleton height={200} borderRadius={14} style={{ marginTop: 12 }} />
                <Skeleton height={160} borderRadius={14} style={{ marginTop: 12 }} />
              </SkeletonTheme>
            </div>
          )}
        </div>
      </ProjectDetailsTabShell>
    );
  }
}

export default ProjectDetailsDashboard;
