/**
 * F05-T6: Attendance intelligence metrics from matrix data.
 */
import moment from "moment";
import {
  buildAttendanceDashboard,
  buildAttendanceSummary,
  isAttendanceAwaitingManagerAction,
  isAttendanceMarked,
  normalizeAttendanceStatus,
} from "views/hrms/components/attendance/attendance.utils";

export function buildAttendanceIntelligence(employees, items, monthDays, selectedDate, regularizations) {
  const summary = buildAttendanceSummary(employees, items, monthDays, selectedDate);
  const dashboard = buildAttendanceDashboard(employees, items, monthDays, null);

  let missingPunchCount = 0;
  let lateTrendCount = 0;
  let regularizationCount = (regularizations || []).length;

  (items || []).forEach((item) => {
    if (item && item.markTime && !item.checkoutTime && normalizeAttendanceStatus(item.status) === "APPROVED") {
      missingPunchCount += 1;
    }
    const markMoment = moment(item.markDate || item.markTime);
    if (markMoment.isValid() && markMoment.hour() >= 10 && normalizeAttendanceStatus(item.status) === "APPROVED") {
      lateTrendCount += 1;
    }
  });

  const pendingRegularizations = (regularizations || []).filter(
    (row) => String(row.status).toUpperCase() === "SUBMITTED"
  ).length;

  const exceptionPending = (items || []).filter((item) => isAttendanceAwaitingManagerAction(item)).length;

  const dailyLate = (dashboard.dailyTrend || []).map((day) => ({
    label: day.label,
    rate: day.rate,
    present: day.present,
    possible: day.possible,
  }));

  return {
    ...summary,
    missingPunchCount,
    lateTrendCount,
    regularizationCount,
    pendingRegularizations,
    exceptionPending,
    teamCoveragePct: summary.presentPct || 0,
    dailyLate,
    payrollRiskCount: (regularizations || []).filter((row) => row.payrollLocked).length,
  };
}

export function buildAnomalyRecommendationDraft(intelligence) {
  if (!intelligence) return null;
  const parts = [];
  if (intelligence.missingPunchCount > 0) {
    parts.push(`${intelligence.missingPunchCount} approved day(s) missing checkout punches`);
  }
  if (intelligence.lateTrendCount > 0) {
    parts.push(`${intelligence.lateTrendCount} late arrival pattern(s) detected`);
  }
  if (intelligence.pendingRegularizations > 0) {
    parts.push(`${intelligence.pendingRegularizations} regularization(s) awaiting approval`);
  }
  const summary = parts.length ? parts.join("; ") : "No significant attendance anomalies this month.";
  return {
    draftOnly: true,
    summary,
    recommendation:
      intelligence.payrollRiskCount > 0
        ? "Review payroll-locked regularizations before month-end close."
        : "Monitor late trends and approve pending regularizations within SLA.",
    confidence: intelligence.exceptionPending > 3 ? 0.68 : 0.84,
    disclaimer: "Draft anomaly insight — human review required. Full attendance intelligence will be available in a future release.",
  };
}
