import {
  buildUtilizationByResource,
  filterPlannerWorkItems,
  formatPlannerHours,
  getHolidayDateKeys,
  getItemEndDate,
  getItemStartDate,
  getOverlappedMinutes,
  getPlannerDays,
  getPlannerRosterEmployees,
  employeeIdsMatch,
  getWorkItemEmployeeId,
  normalizeWorkItemStatus,
} from "./planner.utils";
import { getDayCapacityMinutesForEmployee } from "./plannerCapacity.utils";
import { isEmployeeOnLeave, isPlannerLeaveOrHolidayItem } from "./plannerLeave.utils";
import { getActualMinutesForDay } from "./plannerTimesheet.utils";

export function buildPlannerSummaryModel({
  employees,
  workItems,
  startMoment,
  horizonWeeks,
  holidayItems,
  reduceForHolidays,
  filterOptions,
  leaveMap,
  capacityOverrides,
  actualsByEmployee,
  showActuals,
}) {
  const holidayKeys = getHolidayDateKeys(holidayItems);
  const days = getPlannerDays(startMoment.clone(), horizonWeeks);
  const roster = getPlannerRosterEmployees(employees);
  const filtered = filterPlannerWorkItems(workItems, filterOptions, null);
  const { rows: utilizationRows, capacityPerEmployee } = buildUtilizationByResource({
    employees,
    workItems: filtered,
    startMoment,
    horizonWeeks,
    holidayKeys,
    reduceForHolidays,
    leaveMap,
    capacityOverrides,
  });

  const statusCounts = {};
  filtered.forEach((item) => {
    const st = normalizeWorkItemStatus(item.status) || "UNKNOWN";
    statusCounts[st] = (statusCounts[st] || 0) + 1;
  });

  const dailyAllocated = days.map((dayMoment) => {
    const dayKey = dayMoment.format("YYYY-MM-DD");
    let allocated = 0;
    let capacity = 0;
    let actual = 0;
    roster.forEach((employee) => {
      if (isEmployeeOnLeave(leaveMap, employee.id, dayKey)) return;
      capacity += getDayCapacityMinutesForEmployee(employee, dayMoment, {
        holidayKeys,
        reduceForHolidays,
        capacityOverrides,
      });
      if (showActuals && actualsByEmployee) {
        actual += getActualMinutesForDay(actualsByEmployee, employee.id, dayKey);
      }
    });
    filtered.forEach((item) => {
      if (isPlannerLeaveOrHolidayItem(item)) return;
      const start = getItemStartDate(item);
      if (!start) return;
      const end = getItemEndDate(item, start);
      const eid = getWorkItemEmployeeId(item);
      roster.forEach((employee) => {
        if (!employeeIdsMatch(eid, employee.id)) return;
        if (isEmployeeOnLeave(leaveMap, employee.id, dayKey)) return;
        allocated += getOverlappedMinutes(start, end, dayMoment);
      });
    });
    return {
      key: dayKey,
      label: dayMoment.format("ddd DD"),
      allocated,
      capacity,
      actual,
      utilization: capacity > 0 ? Math.round((allocated / capacity) * 100) : 0,
      isHoliday: holidayKeys.has(dayKey),
      isWeekend: dayMoment.isoWeekday() >= 6,
    };
  });

  const overbooked = utilizationRows.filter((r) => r.utilization > 100).length;
  const underbooked = utilizationRows.filter((r) => r.utilization < 60).length;
  const avgUtil =
    utilizationRows.length > 0
      ? Math.round(
          utilizationRows.reduce((s, r) => s + r.utilization, 0) / utilizationRows.length
        )
      : 0;

  const totalCapacity = utilizationRows.length * capacityPerEmployee;
  const totalAllocated = utilizationRows.reduce((s, r) => s + r.minutes, 0);

  return {
    holidayKeys,
    utilizationRows,
    statusCounts,
    dailyAllocated,
    kpis: {
      rosterSize: roster.length,
      assignmentCount: filtered.length,
      avgUtilization: avgUtil,
      overbookedResources: overbooked,
      underbookedResources: underbooked,
      totalAllocatedMinutes: totalAllocated,
      totalCapacityMinutes: totalCapacity,
      freeMinutes: Math.max(0, totalCapacity - totalAllocated),
    },
  };
}

export function formatPlannerSummaryHours(minutes) {
  return formatPlannerHours(minutes);
}

export function getPlannerAttentionFilters() {
  return [
    { key: "overbooked", label: "Overbooked (>100%)" },
    { key: "underbooked", label: "Underbooked (<60%)" },
    { key: "unassigned", label: "Unassigned work" },
  ];
}

export function filterUtilizationByAttention(rows, workItems, attentionKey) {
  if (!attentionKey) return rows;
  if (attentionKey === "overbooked") {
    return rows.filter((r) => r.utilization > 100);
  }
  if (attentionKey === "underbooked") {
    return rows.filter((r) => r.utilization < 60);
  }
  if (attentionKey === "unassigned") {
    const assignedIds = new Set(
      (workItems || [])
        .map((w) => getWorkItemEmployeeId(w))
        .filter((id) => id != null)
    );
    return rows.filter((r) => !assignedIds.has(r.id) && r.minutes === 0);
  }
  return rows;
}
