import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyIllustration from "./LuxRegisterEmptyIllustration";

/**
 * Luxury empty register state for list pages (bids, contracts, employees).
 */
function LuxRegisterEmptyState({
  variant = "bid-requests",
  eyebrow,
  title,
  description,
  hints,
  createLabel,
  onCreate,
  showCreate = false,
  createDisabled = false,
  createIcon = "fe fe-plus",
  secondaryLabel,
  onSecondary,
  showSecondary = false,
  secondaryIcon = "fa fa-cloud-download",
  secondaryDisabled = false,
  className,
}) {
  const hintItems = hints && hints.length ? hints : [];

  return (
    <section
      className={classNames("lux-register-empty", `lux-register-empty--${variant}`, className)}
      aria-label={title}
    >
      <div className="lux-register-empty__glow" aria-hidden="true" />
      <div className="lux-register-empty__inner">
        <LuxRegisterEmptyIllustration variant={variant} />

        <div className="lux-register-empty__copy">
          {eyebrow && <span className="lux-register-empty__eyebrow">{eyebrow}</span>}
          <h3 className="lux-register-empty__title">{title}</h3>
          {description && <p className="lux-register-empty__text">{description}</p>}

          {hintItems.length > 0 && (
            <ul className="lux-register-empty__hints">
              {hintItems.map((hint) => (
                <li key={hint}>
                  <i className="fe fe-check-circle" aria-hidden="true" />
                  {hint}
                </li>
              ))}
            </ul>
          )}

          <div className="lux-register-empty__actions">
            {showCreate && createLabel && onCreate && (
              <button
                type="button"
                className="lux-register-empty__btn lux-register-empty__btn--primary"
                onClick={onCreate}
                disabled={createDisabled}
              >
                {createIcon && <i className={createIcon} aria-hidden="true" />}
                {createLabel}
              </button>
            )}
            {showSecondary && secondaryLabel && onSecondary && (
              <button
                type="button"
                className="lux-register-empty__btn lux-register-empty__btn--secondary"
                onClick={onSecondary}
                disabled={secondaryDisabled}
              >
                {secondaryIcon && <i className={secondaryIcon} aria-hidden="true" />}
                {secondaryLabel}
              </button>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}

export default LuxRegisterEmptyState;
