/**
 * F06 — Timesheet intelligence metrics (client-side).
 */
import { computeTimesheetSummary } from "views/hrms/components/timesheet/timesheetSummary.utils";

export function buildTimesheetIntelligence(context) {
  const {
    timeSheetRequest,
    applicableDates,
    employees,
    defaulters,
    pendingWeeks,
    conflictCounts,
  } = context || {};

  const summary = computeTimesheetSummary(timeSheetRequest, applicableDates, employees);
  const openConflicts = Object.keys(conflictCounts || {}).reduce(
    (sum, weekId) => sum + (conflictCounts[weekId] || 0),
    0
  );

  const complianceRate =
    employees && employees.length
      ? Math.max(0, Math.round(((employees.length - (defaulters || []).length) / employees.length) * 100))
      : 100;

  return {
    billableMins: summary.billableMins,
    nonProjectMins: summary.nonProjectMins,
    leaveOrHolidayMins: summary.leaveOrHolidayMins,
    totalMins: summary.totalMins,
    utilizationPct: Math.round(summary.utilizationMins || 0),
    billableUtilizationPct: Math.round(summary.billableUtilizationMins || 0),
    pendingMins: summary.pendingMins || 0,
    pendingApprovals: (pendingWeeks || []).length,
    defaulterCount: (defaulters || []).length,
    openConflicts,
    complianceRate,
    dataQualityIssues: (summary.dataQualityCriticalCount || 0) + (summary.dataQualityHighCount || 0),
    daysNeedingAttention: (summary.daysNeedingAttention || []).length,
    weekStatus: summary.weekStatus,
    dailyMap: summary.dailyMap,
    weekDates: summary.weekDates,
  };
}

export function buildManagerComplianceRows(defaulters, pendingWeeks) {
  const rows = [];
  (defaulters || []).forEach((row) => {
    rows.push({
      id: `defaulter-${row.employeeId}`,
      type: "defaulter",
      employeeName: row.employeeName,
      label: row.reason || "Action required",
      status: row.status || "NOT_SUBMITTED",
    });
  });
  (pendingWeeks || []).slice(0, 8).forEach((week) => {
    rows.push({
      id: `pending-${week.id}`,
      type: "pending",
      employeeName: week.employeeName,
      label: "Awaiting your approval",
      status: week.status || "SUBMITTED",
    });
  });
  return rows;
}
