import React, { Component } from "react";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import LuxRegisterGridSkeleton from "views/common/fragments/LuxRegisterGridSkeleton";
import classNames from "classnames/bind";
import ProjectInfoGrid from "./ProjectInfoGrid";

class ProjectListGrids extends Component {
  render() {
    const count = this.props.items ? this.props.items.length : 0;

    return (
      <div className="lux-project-grid-shell lux-project-register lux-project-register--grid">
        <div className="lux-project-register__toolbar">
          <span className="lux-project-register__count">
            {this.props.isLoading ? (
              <LuxListCountSkeleton />
            ) : (
              <>
                <strong>{count}</strong>
                <em>{count === 1 ? "project" : "projects"}</em>
              </>
            )}
          </span>
        </div>
        <div className={classNames("lux-project-grid lux-project-register__grid", { "is-loading": this.props.isLoading })}>
          {this.props.isLoading && <LuxRegisterGridSkeleton count={12} height={360} />}
          {!this.props.isLoading && this.props.items && this.props.items.map((item) => (
            <ProjectInfoGrid
              item={item}
              key={item.id}
              handleDeleteProject={this.props.handleDeleteProject}
              handleEditProject={this.props.handleEditProject}
              handleDuplicateProject={this.props.handleDuplicateProject}
              handleArchiveProject={this.props.handleArchiveProject}
              handleRemoveProject={this.props.handleRemoveProject}
              handleFavoriteProject={this.props.handleFavoriteProject}
              onViewProject={this.props.onViewProject}
              permission={this.props.permission}
            />
          ))}
        </div>
      </div>
    );
  }
}

export default ProjectListGrids;
