import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import LuxHeroLineSkeleton from "views/common/fragments/LuxHeroLineSkeleton";
import OnboardingStatusBadge from "./OnboardingStatusBadge";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";
import { formatLifecycleDate } from "config/onboarding.utils";

const STORAGE_KEY = "famstack-onboarding-self-service-summary-expanded";

function KpiCard({ label, value, tone, icon }) {
  return (
    <article className={classNames("lux-hrms-dash__kpi", tone && `is-${tone}`)}>
      <div className="lux-hrms-dash__kpi-top">
        <span className="lux-hrms-dash__kpi-label">{label}</span>
        {icon && (
          <span className="lux-hrms-dash__kpi-icon" aria-hidden="true">
            <i className={`fe ${icon}`} />
          </span>
        )}
      </div>
      <strong className="lux-hrms-dash__kpi-value">
        <CountUp end={Number(value) || 0} duration={0.7} />
      </strong>
    </article>
  );
}

class SelfServiceSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = {
      expanded: readSummaryExpanded(STORAGE_KEY),
    };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(STORAGE_KEY, this.state.expanded)
    );
  };

  render() {
    const { caseData, metrics, loading } = this.props;
    const { expanded } = this.state;
    const collapsedLine = caseData
      ? `${caseData.candidateName} · starts ${formatLifecycleDate(caseData.startDate) || "soon"} · ${metrics.readinessPct}% ready · ${metrics.actionNeeded} action needed`
      : "";

    return (
      <section
        className={classNames("lux-onb-summary lux-onb-summary--self-service", {
          "is-collapsed": !expanded,
        })}
        aria-label="My onboarding summary"
      >
        <div className="lux-onb-summary__header-bar">
          <div className="lux-onb-summary__header-main">
            <LuxSummaryEyebrow variant="onboarding" className="lux-onb-summary__eyebrow">
              New-hire self-service
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-onb-summary__title lux-onb-summary__title--compact">
                {loading ? (
                  "Loading…"
                ) : (
                  <>
                    <CountUp end={metrics.actionNeeded} duration={0.7} />{" "}
                    <span>tasks need your attention</span>
                  </>
                )}
              </h2>
            ) : (
              <h2 className="lux-onb-summary__title lux-onb-summary__title--bar">
                My onboarding overview
              </h2>
            )}
          </div>
          <button
            type="button"
            className="lux-onb-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-onb-self-service-summary-body"
            title={expanded ? "Collapse summary" : "Insights"}
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && !loading && collapsedLine && (
          <div className="lux-onb-summary__collapsed-strip">
            <p className="lux-onb-summary__collapsed-line">{collapsedLine}</p>
          </div>
        )}

        <div
          id="lux-onb-self-service-summary-body"
          className="lux-onb-summary__body"
          aria-hidden={!expanded}
        >
          <header className="lux-hrms-dash__hero lux-onb-hero lux-onb-hero--self-service lux-onb-hero--join">
            <div className="lux-hrms-dash__hero-main">
              <span className="lux-hrms-dash__hero-eyebrow">
                <i className="fe fe-user-plus" aria-hidden />
                Welcome to Tracopus
              </span>
              <h1 className="lux-hrms-dash__hero-title">
                {loading ? (
                  <LuxHeroLineSkeleton width={240} />
                ) : (
                  <>
                    Hello, <span>{caseData.candidateName}</span>
                  </>
                )}
              </h1>
              <p className="lux-hrms-dash__hero-sub">
                {loading ? (
                  <LuxHeroLineSkeleton width={320} />
                ) : (
                  <>
                    {caseData.role} · {caseData.department} · {caseData.location}
                  </>
                )}
              </p>
              {!loading && caseData && (
                <p className="lux-hrms-dash__hero-context">
                  Start date {formatLifecycleDate(caseData.startDate) || "—"} · Manager{" "}
                  {caseData.manager} · {caseData.templateName}
                </p>
              )}
            </div>

            <div className="lux-onb-hero__detail-aside">
              {!loading && caseData && (
                <>
                  <div
                    className="lux-onb-progress-ring"
                    style={{ "--lux-onb-pct": metrics.readinessPct }}
                    aria-label={`${metrics.readinessPct}% ready`}
                  >
                    <span className="lux-onb-progress-ring__value">{metrics.readinessPct}%</span>
                  </div>
                  <OnboardingStatusBadge status={caseData.status} lifecycle="onboarding" />
                </>
              )}
            </div>
          </header>

          <div className="lux-hrms-dash__kpi-strip lux-onb-kpi-strip" role="list">
            <KpiCard
              label="Action needed"
              value={metrics.actionNeeded}
              tone="primary"
              icon="fe-check-circle"
            />
            <KpiCard
              label="Due soon"
              value={metrics.dueSoon}
              tone="amber"
              icon="fe-calendar"
            />
            <KpiCard
              label="Overdue"
              value={metrics.overdue}
              tone="rose"
              icon="fe-clock"
            />
            <KpiCard
              label="Completed"
              value={metrics.completed}
              tone="green"
              icon="fe-award"
            />
          </div>
        </div>
      </section>
    );
  }
}

export default SelfServiceSummary;
