import React, { Component } from "react";
import classNames from "classnames/bind";
import LuxPageHeaderPopoverPortal from "./LuxPageHeaderPopoverPortal";

const FILTER_META_KEYS = ["filterText", "dateRangeValue"];

const FILTER_LABELS = {
  SHOW: "Status",
  SORT: "Sort",
  REPORT: "Report",
  LOCATION: "Location",
  GROUP: "Group",
};

const FILTER_ICONS = {
  SHOW: "fe fe-filter",
  SORT: "fe fe-bar-chart-2",
  REPORT: "fe fe-file-text",
  LOCATION: "fe fe-map-pin",
  GROUP: "fe fe-layers",
};

class PageInnerHeaderFilterOptionsMenu extends Component {
  constructor(props) {
    super(props);
    this.state = { openDropdownKey: null };
    this.dropdownRefs = {};
    this.dropdownAnchorRefs = {};
    this.popoverRefs = {};
  }

  componentDidMount() {
    document.addEventListener("mousedown", this.handleOutsideClick, true);
  }

  componentWillUnmount() {
    document.removeEventListener("mousedown", this.handleOutsideClick, true);
  }

  handleOutsideClick = (event) => {
    if (!this.state.openDropdownKey) return;
    const key = this.state.openDropdownKey;
    const ref = this.dropdownRefs[key];
    const popover = this.popoverRefs[key];
    if (ref && ref.contains(event.target)) return;
    if (popover && popover.contains(event.target)) return;
    this.setState({ openDropdownKey: null });
  };

  getFilterLabel = (key) => FILTER_LABELS[key] || key;

  getFilterIcon = (key) => FILTER_ICONS[key] || "fe fe-sliders";

  onFilterOptionChange = (key, value) => {
    const alreadySelectedValue = this.props.filterOptions[key].selected;
    const directionUpValue =
      alreadySelectedValue === value ? !this.props.filterOptions[key].directionUp : true;

    this.props.handleFilterChange({
      ...this.props.filterOptions,
      [key]: {
        ...this.props.filterOptions[key],
        selected: value,
        directionUp: directionUpValue,
      },
    });
    this.setState({ openDropdownKey: null });
  };

  toggleDropdown = (key) => {
    if (this.props.isLoading) return;
    this.setState((prev) => ({
      openDropdownKey: prev.openDropdownKey === key ? null : key,
    }));
  };

  renderSortToggle = (key, config) => {
    const activeOption =
      config.options.find((option) => option.name === config.selected) || config.options[0];
    const showDirection =
      activeOption.hasDirection === undefined || activeOption.hasDirection !== false;

    return (
      <button
        key={key}
        type="button"
        className="lux-page-header__sort-btn"
        disabled={this.props.isLoading}
        onClick={() => this.onFilterOptionChange(key, activeOption.name)}
        title="Toggle sort direction"
      >
        <i className="fe fe-bar-chart-2" aria-hidden="true" />
        <span>{activeOption.label}</span>
        {showDirection && (
          <i
            className={classNames("fe", config.directionUp ? "fe-arrow-up" : "fe-arrow-down")}
            aria-hidden="true"
          />
        )}
      </button>
    );
  };

  getDropdownAnchorRef = (key) => {
    if (!this.dropdownAnchorRefs[key]) {
      this.dropdownAnchorRefs[key] = React.createRef();
    }
    return this.dropdownAnchorRefs[key];
  };

  renderSelectDropdown = (key, config) => {
    const activeOption =
      config.options.find((option) => option.name === config.selected) || config.options[0];
    const isOpen = this.state.openDropdownKey === key;
    const label = this.getFilterLabel(key);
    const isSort = key === "SORT";

    return (
      <div
        key={key}
        className="lux-page-header__filter-dropdown"
        ref={(node) => {
          this.dropdownRefs[key] = node;
          this.getDropdownAnchorRef(key).current = node;
        }}
      >
        <button
          type="button"
          className={classNames("lux-page-header__filter-dropdown-btn", { "is-open": isOpen })}
          disabled={this.props.isLoading}
          onClick={() => this.toggleDropdown(key)}
          aria-expanded={isOpen}
          aria-haspopup="listbox"
        >
          <i className={this.getFilterIcon(key)} aria-hidden="true" />
          <span className="lux-page-header__filter-dropdown-label">{label}</span>
          <span className="lux-page-header__filter-dropdown-value">{activeOption.label}</span>
          <i className="fe fe-chevron-down" aria-hidden="true" />
        </button>

        <LuxPageHeaderPopoverPortal
          isOpen={isOpen}
          anchorRef={this.getDropdownAnchorRef(key)}
          align="left"
          popoverRef={(node) => {
            this.popoverRefs[key] = node;
          }}
          className="lux-page-header__filter-panel"
        >
          <header className="lux-page-header__filter-panel-head">
            <span className="lux-page-header__filter-panel-icon" aria-hidden="true">
              <i className={this.getFilterIcon(key)} />
            </span>
            <div>
              <span className="lux-page-header__filter-panel-eyebrow">Filter</span>
              <strong>{label}</strong>
            </div>
          </header>
          <ul className="lux-page-header__filter-panel-list" role="listbox" aria-label={label}>
            {config.options.map((option) => {
              const isActive = config.selected === option.name;
              const showDirection =
                isSort &&
                isActive &&
                (option.hasDirection === undefined || option.hasDirection !== false);

              return (
                <li key={option.name} role="option" aria-selected={isActive}>
                  <button
                    type="button"
                    className={classNames("lux-page-header__filter-panel-item", {
                      "is-active": isActive,
                    })}
                    onClick={() => this.onFilterOptionChange(key, option.name)}
                  >
                    <span className="lux-page-header__filter-panel-item-mark" aria-hidden="true">
                      {isActive && <i className="fe fe-check" />}
                    </span>
                    <span className="lux-page-header__filter-panel-item-label">{option.label}</span>
                    {showDirection && (
                      <i
                        className={classNames(
                          "fe lux-page-header__filter-panel-item-dir",
                          config.directionUp ? "fe-arrow-up" : "fe-arrow-down"
                        )}
                        aria-hidden="true"
                      />
                    )}
                  </button>
                </li>
              );
            })}
          </ul>
        </LuxPageHeaderPopoverPortal>
      </div>
    );
  };

  render() {
    if (!this.props.filterOptions) return null;

    const hiddenKeys = this.props.hiddenFilterKeys || [];

    return (
      <>
        {Object.keys(this.props.filterOptions).map((key) => {
          if (FILTER_META_KEYS.includes(key) || hiddenKeys.includes(key)) return null;

          const config = this.props.filterOptions[key];
          if (!config || !config.options || config.options.length === 0) return null;

          if (key === "SORT" && config.options.length === 1) {
            return this.renderSortToggle(key, config);
          }

          return this.renderSelectDropdown(key, config);
        })}
      </>
    );
  }
}

export default PageInnerHeaderFilterOptionsMenu;
