import React, { Component } from "react";
import { learningService } from "_services/learning/learning.service";
import LearningLuxPage, {
  LearningLuxPanel,
  LearningMetricCard,
} from "views/learning/components/LearningLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class ReportsPage extends Component {
  state = { loading: true, loadError: null, report: null };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Learning reports");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await learningService.completionReport();
    if (result.source === "api" && result.payload) {
      this.setState({ loading: false, report: result.payload });
    } else {
      this.setState({
        loading: false,
        report: null,
        loadError: result.error || new Error("Unable to load completion report"),
      });
    }
  };

  render() {
    const { loading, loadError, report } = this.state;
    return (
      <LearningLuxPage
        testId="learning-reports-page"
        dataSource={report ? "api" : loadError ? "api-error" : null}
        loading={loading}
        pageMeta={{
          tone: "teal",
          icon: "fe fe-bar-chart-2",
          eyebrow: "People · Learning",
          titleLead: "Completion",
          titleAccent: "report",
          lede: "Aggregate completion, in-progress, and overdue learning metrics.",
        }}
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load completion report">
            {String(loadError.message || loadError)}
          </LuxInlineAlert>
        ) : null}
        <LearningLuxPanel title="Completion report" icon="fe fe-pie-chart">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading"
              description="Fetching records."
            />
          ) : null}
          {!loading && !report && !loadError ? (
            <LuxRegisterEmptyState
              title="No report data"
              description="Completion metrics will appear once assignments exist."
              showCreate={false}
            />
          ) : null}
          {report ? (
            <div className="lux-learning-metric-grid">
              <LearningMetricCard
                label="Total assignments"
                value={report.totalAssignments}
                hint="All active learning assignments"
              />
              <LearningMetricCard
                label="Completed"
                value={report.completed}
                tone="emerald"
                hint="Finished by learners"
              />
              <LearningMetricCard
                label="In progress"
                value={report.inProgress}
                tone="blue"
                hint="Started but not complete"
              />
              <LearningMetricCard
                label="Overdue"
                value={report.overdue}
                tone="rose"
                hint="Requires manager follow-up"
              />
              <LearningMetricCard
                label="Completion"
                value={`${report.completionPct || 0}%`}
                tone="violet"
                hint="Completion rate"
              />
            </div>
          ) : null}
        </LearningLuxPanel>
      </LearningLuxPage>
    );
  }
}

export default ReportsPage;
