/**
 * Apply document title + meta tags for the current SPA route.
 */
import { resolvePageSeo } from "config/page-seo.config";

function upsertMeta(attr, key, content) {
  if (typeof document === "undefined") return;
  let el = document.head.querySelector(`meta[${attr}="${key}"]`);
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute(attr, key);
    document.head.appendChild(el);
  }
  el.setAttribute("content", content || "");
}

/**
 * @param {string} pathname
 * @returns {{ title: string, description: string, robots: string, contentGroup: string, path: string }}
 */
export function applyPageSeo(pathname) {
  const seo = resolvePageSeo(pathname);
  if (typeof document === "undefined") return seo;

  document.title = seo.title;
  upsertMeta("name", "description", seo.description);
  upsertMeta("name", "robots", seo.robots);
  upsertMeta("property", "og:title", seo.title);
  upsertMeta("property", "og:description", seo.description);
  upsertMeta("property", "og:type", "website");
  upsertMeta("name", "twitter:title", seo.title);
  upsertMeta("name", "twitter:description", seo.description);

  return seo;
}
