import React from "react";
import envconfig from "env.config";

function getAppName() {
  return envconfig.APP_NAME || "Tracopus";
}

export const LEGAL_DOC_TYPES = {
  PRIVACY: "privacy",
  TERMS: "terms",
};

export function getLegalDocument(docType) {
  const appName = getAppName();

  if (docType === LEGAL_DOC_TYPES.TERMS) {
    return {
      type: LEGAL_DOC_TYPES.TERMS,
      eyebrow: "Agreement",
      title: "Terms of Service",
      body: (
        <>
          <p>
            These Terms of Service govern access to and use of {appName}, provided by
            Infleca Innovation Pvt Ltd (“Infleca”, “we”, “us”).
          </p>
          <h2>Accounts and access</h2>
          <p>
            You must use a valid organizational account and keep credentials
            confidential. You are responsible for activity under your account. Your
            organization’s administrators may manage users, roles, and data retention.
          </p>
          <h2>Acceptable use</h2>
          <p>
            You agree not to misuse {appName}, attempt unauthorized access, interfere
            with service availability, or use the product in violation of law or your
            employer’s policies.
          </p>
          <h2>Customer data</h2>
          <p>
            Workplace content you or your organization submit remains owned by your
            organization. Infleca processes that content only to provide and improve
            the service and as described in the Privacy Policy.
          </p>
          <h2>Availability and changes</h2>
          <p>
            We aim for reliable service but do not guarantee uninterrupted
            availability. Features may change over time. Continued use after updates
            constitutes acceptance of revised terms when posted here.
          </p>
          <h2>Limitation of liability</h2>
          <p>
            To the fullest extent permitted by law, Infleca’s liability arising from
            use of {appName} is limited as set out in your organization’s commercial
            agreement with Infleca. Where no separate agreement applies, {appName} is
            provided on an “as available” basis.
          </p>
          <h2>Contact</h2>
          <p>
            Questions about these terms may be directed to your organization
            administrator or Infleca Innovation Pvt Ltd via your subscription support
            channel.
          </p>
          <p className="lux-legal-modal__updated">Last updated: July 2026</p>
        </>
      ),
    };
  }

  return {
    type: LEGAL_DOC_TYPES.PRIVACY,
    eyebrow: "Your data",
    title: "Privacy Policy",
    body: (
      <>
        <p>
          This Privacy Policy describes how Infleca Innovation Pvt Ltd (“we”, “us”)
          collects, uses, and protects information when you use {appName}.
        </p>
        <h2>Information we process</h2>
        <p>
          We process account details you provide (such as name, work email, and
          authentication credentials), workplace data your organization configures
          in {appName} (for example projects, timesheets, leave, and attendance),
          and technical logs needed to operate and secure the service.
        </p>
        <h2>How we use information</h2>
        <p>
          Information is used to authenticate users, deliver product features your
          organization enables, provide support, improve reliability and security,
          and meet legal or contractual obligations.
        </p>
        <h2>Sharing</h2>
        <p>
          We do not sell personal information. Data may be shared with subprocessors
          that host or operate the service under contract, or when required by law.
          Your organization remains the controller of employee and workplace data
          entered into {appName}.
        </p>
        <h2>Security and retention</h2>
        <p>
          We apply administrative and technical controls appropriate to the
          sensitivity of the data. Retention follows your organization’s
          configuration and applicable law.
        </p>
        <h2>Contact</h2>
        <p>
          For privacy questions, contact your organization administrator or
          Infleca Innovation Pvt Ltd through the support channels provided with
          your {appName} subscription.
        </p>
        <p className="lux-legal-modal__updated">Last updated: July 2026</p>
      </>
    ),
  };
}
