import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyIllustration from "./LuxRegisterEmptyIllustration";

/**
 * Compact vertical empty state for activity sidebar panels (pending tasks, holidays).
 */
function LuxActivityPanelEmptyState({ variant, eyebrow, title, description, hints, className }) {
  const hintItems = hints && hints.length ? hints : [];

  return (
    <div
      className={classNames(
        "lux-activity-panel-empty",
        variant && `lux-activity-panel-empty--${variant}`,
        className
      )}
      role="status"
    >
      <LuxRegisterEmptyIllustration variant={variant} />
      <div className="lux-activity-panel-empty__copy">
        {eyebrow && <span className="lux-activity-panel-empty__eyebrow">{eyebrow}</span>}
        <strong className="lux-activity-panel-empty__title">{title}</strong>
        {description && <p className="lux-activity-panel-empty__text">{description}</p>}
        {hintItems.length > 0 && (
          <ul className="lux-activity-panel-empty__hints">
            {hintItems.map((hint) => (
              <li key={hint}>
                <i className="fe fe-check-circle" aria-hidden="true" />
                {hint}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

export default LuxActivityPanelEmptyState;
