import React, { Component } from "react";
import classNames from "classnames/bind";
import { Modal } from "views/common/plugins/model/Modal";
import { Effect } from "views/common/plugins/model";
import { history } from "_helpers";
import { getAssistPanelModalStyle } from "./assistDock.utils";
import {
  resolvePageOrgAssist,
  resolvePagePermissionAssist,
} from "config/page-permission-assist.utils";
import "./PagePermissionAssistModal.css";

const ASSIST_SCOPES = {
  ROLE: "role",
  ORG: "org",
};

class PagePermissionAssistModal extends Component {
  state = {
    scope: ASSIST_SCOPES.ROLE,
    roleSnapshot: resolvePagePermissionAssist(
      (typeof window !== "undefined" && window.location && window.location.pathname) || "/"
    ),
    orgSnapshot: resolvePageOrgAssist(
      (typeof window !== "undefined" && window.location && window.location.pathname) || "/"
    ),
  };

  componentDidMount() {
    this.refresh();
  }

  getPathname = () =>
    (history && history.location && history.location.pathname) ||
    (typeof window !== "undefined" && window.location && window.location.pathname) ||
    "/";

  refresh = () => {
    const pathname = this.getPathname();
    this.setState({
      roleSnapshot: resolvePagePermissionAssist(pathname),
      orgSnapshot: resolvePageOrgAssist(pathname),
    });
  };

  setScope = (scope) => {
    this.setState({ scope });
  };

  getSnapshot = () => {
    const { scope, roleSnapshot, orgSnapshot } = this.state;
    return scope === ASSIST_SCOPES.ORG ? orgSnapshot : roleSnapshot;
  };

  navigateToConfig = () => {
    const { onRequestClose } = this.props;
    const snapshot = this.getSnapshot();
    if (onRequestClose) {
      onRequestClose();
    }
    history.push(snapshot.appConfigPath || "/admin/appconfig");
  };

  openFlagGuide = () => {
    const { onOpenFlagGuide, onRequestClose } = this.props;
    if (typeof onOpenFlagGuide === "function") {
      onOpenFlagGuide();
      return;
    }
    if (onRequestClose) {
      onRequestClose();
    }
  };

  permissionIcon(item) {
    if (item.kind === "property") {
      return "fe fe-sliders";
    }
    if (item.id === "menu-access") {
      return "fe fe-layout";
    }
    if (item.id === "module-active") {
      return "fe fe-box";
    }
    if (/create/i.test(item.configKey || item.id || "")) {
      return "fe fe-plus-circle";
    }
    if (/edit|update/i.test(item.configKey || item.id || "")) {
      return "fe fe-edit-2";
    }
    if (/delete|remove/i.test(item.configKey || item.id || "")) {
      return "fe fe-trash-2";
    }
    if (/archive|activate/i.test(item.configKey || item.label || "")) {
      return "fe fe-toggle-right";
    }
    if (/view|open/i.test(item.configKey || item.id || "")) {
      return "fe fe-eye";
    }
    if (/switch|team/i.test(item.configKey || item.id || "")) {
      return "fe fe-users";
    }
    return item.enabled ? "fe fe-check-circle" : "fe fe-lock";
  }

  renderPermission(item, scope) {
    const isProperty = item.kind === "property";
    return (
      <article
        key={item.id}
        className={`lux-perm-assist__item ${
          isProperty ? "is-property" : item.enabled ? "is-enabled" : "is-disabled"
        }`}
      >
        <span className="lux-perm-assist__item-icon" aria-hidden="true">
          <i className={this.permissionIcon(item)} />
        </span>
        <div className="lux-perm-assist__item-copy">
          <strong>{item.label}</strong>
          {item.description ? <span>{item.description}</span> : null}
          <small>
            {isProperty
              ? `Value · ${item.valueText}`
              : item.enabled
                ? scope === ASSIST_SCOPES.ORG
                  ? "Enabled for your team"
                  : "Enabled for your role"
                : scope === ASSIST_SCOPES.ORG
                  ? "Off for your team"
                  : "Needs enablement"}
            {item.configSetting && !isProperty ? ` · ${item.configSetting}` : ""}
          </small>
        </div>
        {isProperty ? (
          <span className="lux-perm-assist__badge is-value" title={item.valueText}>
            {item.valueText}
          </span>
        ) : (
          <span className={`lux-perm-assist__badge ${item.enabled ? "is-on" : "is-off"}`}>
            {item.enabled ? "On" : "Off"}
          </span>
        )}
      </article>
    );
  }

  render() {
    const { onRequestClose, dockAnchor } = this.props;
    const { scope } = this.state;
    const snapshot = this.getSnapshot();
    const isOrg = scope === ASSIST_SCOPES.ORG;
    const enabled = (snapshot.permissions || []).filter((item) => item.enabled);
    const disabled = (snapshot.permissions || []).filter((item) => !item.enabled);
    const properties = snapshot.properties || [];
    const coverage =
      snapshot.permissions && snapshot.permissions.length > 0
        ? Math.round((snapshot.enabledCount / snapshot.permissions.length) * 100)
        : 0;
    const actionOnly = (snapshot.permissions || []).filter(
      (item) => item.id !== "menu-access" && item.id !== "module-active"
    );
    const isMenuOnly = !isOrg && snapshot.supported && actionOnly.length === 0;

    return (
      <Modal
        onRequestClose={onRequestClose}
        effect={Effect.ScaleUp}
        style={getAssistPanelModalStyle(dockAnchor, { width: "520px" })}
      >
        <div className="page-permission-assist-modal lux-assist-panel lux-assist-panel--permissions">
          <div className="lux-assist-panel__hero lux-assist-panel__hero--permissions">
            <div className="lux-assist-panel__hero-bg" aria-hidden="true" />
            <div className="lux-perm-assist__hero-orbs" aria-hidden="true">
              <span className="lux-perm-assist__orb lux-perm-assist__orb--a" />
              <span className="lux-perm-assist__orb lux-perm-assist__orb--b" />
            </div>

            <div className="lux-assist-panel__hero-top">
              <div className="lux-assist-panel__brand lux-perm-assist__brand">
                <span className="lux-assist-panel__brand-icon lux-assist-panel__brand-icon--permissions">
                  <i className={isOrg ? "fe fe-database" : "fe fe-shield"} />
                </span>
                <div className="lux-perm-assist__brand-copy">
                  <div className="lux-perm-assist__kicker-row">
                    <span className="lux-assist-panel__kicker">Access guidance</span>
                    <span className="lux-perm-assist__live-pill">
                      <span className="lux-perm-assist__live-dot" aria-hidden="true" />
                      Live map
                    </span>
                  </div>
                  <h4 className="lux-assist-panel__title mb-0">{snapshot.title}</h4>
                </div>
              </div>
              <button
                type="button"
                onClick={onRequestClose}
                className="lux-assist-panel__close"
                aria-label="Close page permissions panel"
              >
                <i className="fa fa-times" />
              </button>
            </div>

            <p className="lux-assist-panel__hero-lead lux-perm-assist__hero-lead">
              {isOrg
                ? "See which organization flags and property values currently gate this page for your team."
                : "See what your role can do on this page — and what still needs enabling in Application config."}
            </p>

            <div className="lux-perm-assist__hero-controls">
              <div
                className="lux-perm-assist__scope-tabs lux-perm-assist__scope-tabs--hero"
                role="tablist"
                aria-label="Access scope"
              >
                <button
                  type="button"
                  role="tab"
                  aria-selected={!isOrg}
                  className={classNames("lux-perm-assist__scope-tab", { "is-active": !isOrg })}
                  onClick={() => this.setScope(ASSIST_SCOPES.ROLE)}
                >
                  <i className="fe fe-shield" aria-hidden="true" />
                  Role
                </button>
                <button
                  type="button"
                  role="tab"
                  aria-selected={isOrg}
                  className={classNames("lux-perm-assist__scope-tab", { "is-active": isOrg })}
                  onClick={() => this.setScope(ASSIST_SCOPES.ORG)}
                >
                  <i className="fe fe-users" aria-hidden="true" />
                  Org
                </button>
              </div>

              <nav className="lux-perm-assist__hero-links" aria-label="Access guidance links">
                <button
                  type="button"
                  className="lux-perm-assist__text-link"
                  onClick={this.openFlagGuide}
                  title="Open Config guide"
                  aria-label="Open Config guide"
                >
                  <i className="fe fe-book-open" aria-hidden="true" />
                  <span className="lux-perm-assist__text-link-label">Config guide</span>
                  <i className="fe fe-external-link lux-perm-assist__text-link-ext" aria-hidden="true" />
                </button>
                <button
                  type="button"
                  className="lux-perm-assist__text-link"
                  onClick={this.navigateToConfig}
                  title="Open Application config"
                  aria-label="Open Application config"
                >
                  <i className="fe fe-sliders" aria-hidden="true" />
                  <span className="lux-perm-assist__text-link-label">App config</span>
                  <i className="fe fe-external-link lux-perm-assist__text-link-ext" aria-hidden="true" />
                </button>
              </nav>
            </div>
          </div>

          <div className="lux-assist-panel__body lux-perm-assist__body">
            <section className="lux-perm-assist__overview" aria-label="Access overview">
              <div className="lux-perm-assist__overview-head">
                <div className="lux-perm-assist__identity">
                  {!isOrg && snapshot.roleLabel ? (
                    <span
                      className="lux-perm-assist__identity-card"
                      title={
                        snapshot.roleId != null
                          ? `Role: ${snapshot.roleLabel} (#${snapshot.roleId})`
                          : `Role: ${snapshot.roleLabel}`
                      }
                    >
                      <span className="lux-perm-assist__identity-icon" aria-hidden="true">
                        <i className="fe fe-shield" />
                      </span>
                      <span className="lux-perm-assist__identity-meta">
                        <em>Viewing as role</em>
                        <strong className="lux-perm-assist__identity-text">{snapshot.roleLabel}</strong>
                      </span>
                    </span>
                  ) : null}
                  {isOrg && snapshot.orgLabel ? (
                    <span
                      className="lux-perm-assist__identity-card"
                      title={
                        snapshot.teamId != null
                          ? `${snapshot.orgLabel} (id ${snapshot.teamId})`
                          : snapshot.orgLabel
                      }
                    >
                      <span className="lux-perm-assist__identity-icon" aria-hidden="true">
                        <i className="fe fe-users" />
                      </span>
                      <span className="lux-perm-assist__identity-meta">
                        <em>Viewing as org</em>
                        <strong className="lux-perm-assist__identity-text">{snapshot.orgLabel}</strong>
                      </span>
                    </span>
                  ) : null}
                  {!isOrg && !snapshot.roleLabel ? (
                    <span className="lux-perm-assist__identity-card is-muted">
                      <span className="lux-perm-assist__identity-icon" aria-hidden="true">
                        <i className="fe fe-shield" />
                      </span>
                      <span className="lux-perm-assist__identity-meta">
                        <em>Viewing as role</em>
                        <strong className="lux-perm-assist__identity-text">Your role</strong>
                      </span>
                    </span>
                  ) : null}
                  {isOrg && !snapshot.orgLabel ? (
                    <span className="lux-perm-assist__identity-card is-muted">
                      <span className="lux-perm-assist__identity-icon" aria-hidden="true">
                        <i className="fe fe-users" />
                      </span>
                      <span className="lux-perm-assist__identity-meta">
                        <em>Viewing as org</em>
                        <strong className="lux-perm-assist__identity-text">Your org</strong>
                      </span>
                    </span>
                  ) : null}
                </div>
                <button
                  type="button"
                  className="lux-assist-panel__quick-chip lux-assist-panel__quick-chip--accent lux-perm-assist__overview-refresh"
                  onClick={this.refresh}
                >
                  <i className="fe fe-refresh-cw" aria-hidden="true" />
                  Refresh
                </button>
              </div>

              <div className="lux-perm-assist__metrics" role="list">
                <article className="lux-perm-assist__metric is-on" role="listitem">
                  <span className="lux-perm-assist__metric-icon" aria-hidden="true">
                    <i className="fe fe-check-circle" />
                  </span>
                  <div>
                    <strong>{snapshot.enabledCount}</strong>
                    <span>Enabled</span>
                  </div>
                </article>
                <article className="lux-perm-assist__metric is-off" role="listitem">
                  <span className="lux-perm-assist__metric-icon" aria-hidden="true">
                    <i className="fe fe-lock" />
                  </span>
                  <div>
                    <strong>{snapshot.disabledCount}</strong>
                    <span>Not enabled</span>
                  </div>
                </article>
                <article className="lux-perm-assist__metric is-coverage" role="listitem">
                  <span className="lux-perm-assist__metric-icon" aria-hidden="true">
                    <i className={isOrg ? "fe fe-list" : "fe fe-pie-chart"} />
                  </span>
                  <div>
                    <strong>{isOrg ? properties.length : `${coverage}%`}</strong>
                    <span>{isOrg ? "Properties" : "Coverage"}</span>
                  </div>
                </article>
              </div>

              {(snapshot.moduleLabel || snapshot.configSetting || snapshot.path) && (
                <div className="lux-perm-assist__context">
                  {snapshot.moduleLabel ? (
                    <span className="lux-perm-assist__context-chip">
                      <i className="fe fe-grid" aria-hidden="true" />
                      {snapshot.moduleLabel}
                    </span>
                  ) : null}
                  {snapshot.configSetting ? (
                    <span className="lux-perm-assist__context-chip">
                      <i className="fe fe-settings" aria-hidden="true" />
                      {snapshot.configSetting}
                    </span>
                  ) : null}
                  <span className="lux-perm-assist__context-chip is-muted">
                    <i className="fe fe-link" aria-hidden="true" />
                    {snapshot.path}
                  </span>
                </div>
              )}
            </section>

            {!snapshot.supported ? (
              <div className="lux-assist-panel__card lux-perm-assist__notice">
                <strong>{isOrg ? "Limited org map for this URL" : "Limited map for this URL"}</strong>
                <p>
                  {isOrg
                    ? "No matching org Additional groups were found in your access blob for this page. Open Application config for your team and review Tracopus *Additional settings."
                    : "This page is not in the sidebar catalog and has no matching Application Config action block. Enable the related module and page flags for your role, then refresh."}
                </p>
              </div>
            ) : null}

            {isMenuOnly ? (
              <div className="lux-assist-panel__card lux-perm-assist__notice">
                <strong>Page access only</strong>
                <p>
                  This page is controlled mainly by a menu / module flag. There is no separate
                  Create / Edit / Delete matrix — turn on the page under Module access.
                </p>
              </div>
            ) : null}

            {disabled.length ? (
              <section className="lux-perm-assist__section">
                <header className="lux-perm-assist__section-head">
                  <div>
                    <h5>Not enabled</h5>
                    <span>
                      {isOrg ? "Off for your team org config" : "Unlock these in Application config"}
                    </span>
                  </div>
                  <span className="lux-perm-assist__section-count is-off">{disabled.length}</span>
                </header>
                <div className="lux-perm-assist__list">
                  {disabled.map((item) => this.renderPermission(item, scope))}
                </div>
              </section>
            ) : null}

            {enabled.length ? (
              <section className="lux-perm-assist__section">
                <header className="lux-perm-assist__section-head">
                  <div>
                    <h5>Already enabled</h5>
                    <span>
                      {isOrg
                        ? "Org flags on for your current team"
                        : "Available on this page for your role"}
                    </span>
                  </div>
                  <span className="lux-perm-assist__section-count is-on">{enabled.length}</span>
                </header>
                <div className="lux-perm-assist__list">
                  {enabled.map((item) => this.renderPermission(item, scope))}
                </div>
              </section>
            ) : null}

            {isOrg && properties.length ? (
              <section className="lux-perm-assist__section">
                <header className="lux-perm-assist__section-head">
                  <div>
                    <h5>Config properties</h5>
                    <span>Non-flag values from related org groups</span>
                  </div>
                  <span className="lux-perm-assist__section-count is-prop">{properties.length}</span>
                </header>
                <div className="lux-perm-assist__list">
                  {properties.map((item) => this.renderPermission(item, scope))}
                </div>
              </section>
            ) : null}

            <section className="lux-perm-assist__section">
              <header className="lux-perm-assist__section-head">
                <div>
                  <h5>How to enable</h5>
                  <span>
                    {isOrg
                      ? "Follow these org Application config steps"
                      : "Follow these Application config steps"}
                  </span>
                </div>
              </header>
              <ol className="lux-perm-assist__steps">
                {(snapshot.howTo || []).map((step, index) => (
                  <li key={step}>
                    <span className="lux-perm-assist__step-index" aria-hidden="true">
                      {index + 1}
                    </span>
                    <span className="lux-perm-assist__step-copy">{step}</span>
                  </li>
                ))}
              </ol>
            </section>

            <div className="lux-assist-panel__quick-links">
              <span className="lux-assist-panel__quick-label">Quick actions</span>
              <div className="lux-assist-panel__quick-grid">
                <button
                  type="button"
                  className="lux-assist-panel__quick-chip lux-assist-panel__quick-chip--accent"
                  onClick={this.refresh}
                >
                  <i className="fe fe-refresh-cw" aria-hidden="true" />
                  Refresh status
                </button>
              </div>
            </div>
          </div>
        </div>
      </Modal>
    );
  }
}

export default PagePermissionAssistModal;
