import React, { Component } from "react";
import { connect } from "react-redux";
import { commonUtils } from "_helpers";
import { employeeActions } from "_actions";
import { employee360Service } from "_services/employee360.service";
import { PersonaContext } from "context/PersonaContextProvider";
import ProfilePageHero from "views/hrms/components/ProfilePageHero";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import {
  buildEmployee360ViewerContext,
  getVisibleEmployee360Tabs,
  resolveEmployee360Id,
  canViewEmployee360ForPage,
  resolveEmployee360AccessDeniedReason,
} from "config/employee360.utils";
import {
  isEmployee360RouteEnabled,
  isEmployee360PerformanceTabLive,
  isEmployee360FinanceTabLive,
} from "config/employee360.config";
import Employee360PerformanceTab from "views/people/components/employee360/Employee360PerformanceTab";
import Employee360BackNav from "views/people/components/employee360/Employee360BackNav";
import Employee360Tabs from "views/people/components/employee360/Employee360Tabs";
import Employee360OverviewTab from "views/people/components/employee360/Employee360OverviewTab";
import Employee360ProfileTab from "views/people/components/employee360/Employee360ProfileTab";
import Employee360EmploymentTab from "views/people/components/employee360/Employee360EmploymentTab";
import Employee360LeaveTab from "views/people/components/employee360/Employee360LeaveTab";
import Employee360AttendanceTab from "views/people/components/employee360/Employee360AttendanceTab";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import Employee360TimesheetsTab from "views/people/components/employee360/Employee360TimesheetsTab";
import Employee360ActivityTab from "views/people/components/employee360/Employee360ActivityTab";
import Employee360PayrollTab from "views/people/components/employee360/Employee360PayrollTab";
import Employee360ProjectsTab from "views/people/components/employee360/Employee360ProjectsTab";
import Employee360DocumentsTab from "views/people/components/employee360/Employee360DocumentsTab";
import Employee360ApprovalsTab from "views/people/components/employee360/Employee360ApprovalsTab";
import Employee360FinanceTab from "views/people/components/employee360/Employee360FinanceTab";
import Employee360LearningTab from "views/people/components/employee360/Employee360LearningTab";
import Employee360TabPlaceholder from "views/people/components/employee360/Employee360TabPlaceholder";
import Employee360LauncherPage from "views/people/Employee360LauncherPage";

/**
 * F02 — Employee 360 production page (param route + luxury shell).
 */
class Employee360Page extends Component {
  static contextType = PersonaContext;

  state = {
    activeTab: "overview",
    summary: null,
    visibleTabIds: null,
    accessAllowed: null,
    employeeFromAggregate: null,
    loadError: null,
    loading360: true,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Employee 360");
    this.loadEmployee360();
  }

  componentDidUpdate(prevProps) {
    const prevId = resolveEmployee360Id(prevProps.match, commonUtils.getCurrentUserId());
    const nextId = resolveEmployee360Id(this.props.match, commonUtils.getCurrentUserId());
    const prevPersona = this.context && this.context.activePersona;
    const nextPersona = this.context && this.context.activePersona;
    if (prevId !== nextId || prevPersona !== nextPersona) {
      this.loadEmployee360();
    }
  }

  loadEmployee360 = async () => {
    const employeeId = resolveEmployee360Id(this.props.match, commonUtils.getCurrentUserId());
    if (!employeeId) {
      this.setState({ loading360: false, loadError: "Employee not found." });
      return;
    }

    this.setState({ loading360: true, loadError: null, employeeFromAggregate: null });
    this.props.getEmployeesInfo(employeeId);

    try {
      const personaCtx = this.context || {};
      const payload = await employee360Service.getEmployee360(employeeId, {
        maskingPolicy: personaCtx.maskingPolicy,
        activePersona: personaCtx.activePersona,
      });
      if (!payload || payload.source === "api-error") {
        this.setState({
          loading360: false,
          loadError: "Unable to load Employee 360 summary.",
        });
        return;
      }
      this.setState({
        summary: payload.summary,
        visibleTabIds: payload.visibleTabIds || null,
        accessAllowed: payload.accessAllowed,
        employeeFromAggregate: payload.employee || null,
        loading360: false,
      });
    } catch (e) {
      this.setState({
        loading360: false,
        loadError: "Unable to load Employee 360 summary.",
      });
    }
  };

  handleTabSelect = (tabId) => {
    this.setState({ activeTab: tabId });
  };

  renderTabPanel = (employee, summary, visibleTabs) => {
    const { activeTab } = this.state;
    const tab = visibleTabs.find((item) => item.id === activeTab) || visibleTabs[0];
    if (!tab) {
      return null;
    }

    // Planned tabs are filtered from the rail — keep a fail-closed unavailable state only as a guard.
    if (tab.planned === true && tab.id !== "performance" && tab.id !== "finance" && tab.id !== "payroll") {
      return (
        <Employee360TabPlaceholder
          tabLabel={tab.label}
          featureId={tab.feature}
        />
      );
    }

    switch (tab.id) {
      case "overview":
        return (
          <Employee360OverviewTab
            employee={employee}
            summary={summary}
            activePersona={this.context && this.context.activePersona}
            activePersonaLabel={this.context && this.context.activePersonaLabel}
          />
        );
      case "profile":
        return <Employee360ProfileTab employee={employee} />;
      case "employment":
        return (
          <Employee360EmploymentTab
            employee={employee}
            summary={summary}
            maskingPolicy={this.context && this.context.maskingPolicy}
          />
        );
      case "leave":
        return <Employee360LeaveTab employee={employee} summary={summary} />;
      case "attendance":
        return <Employee360AttendanceTab employee={employee} />;
      case "timesheets":
        return <Employee360TimesheetsTab employee={employee} />;
      case "performance":
        // EMP360-004 — tab only reachable when live; no placeholder in the rail.
        return (
          <Employee360PerformanceTab
            employee={employee}
            summary={summary}
            maskingPolicy={this.context && this.context.maskingPolicy}
          />
        );
      case "learning":
        return <Employee360LearningTab employee={employee} summary={summary} />;
      case "activity":
        return <Employee360ActivityTab employee={employee} summary={summary} />;
      case "payroll":
        return (
          <Employee360PayrollTab
            employee={employee}
            summary={summary}
            maskingPolicy={this.context && this.context.maskingPolicy}
          />
        );
      case "finance":
        // EMP360-005 — tab only reachable when live.
        return (
          <Employee360FinanceTab
            employee={employee}
            summary={summary}
            viewerPersona={this.context && this.context.activePersona}
            maskingPolicy={this.context && this.context.maskingPolicy}
          />
        );
      case "projects":
        return <Employee360ProjectsTab employee={employee} summary={summary} />;
      case "documents":
        return <Employee360DocumentsTab employee={employee} summary={summary} />;
      case "approvals":
        return <Employee360ApprovalsTab employee={employee} summary={summary} />;
      default:
        return <Employee360TabPlaceholder tabLabel={tab.label} featureId="" />;
    }
  };

  renderProductionPage() {
    const personaCtx = this.context || {};
    const { selectedEmployeeInfo, getInfoLoading } = this.props;
    const { summary, loadError, loading360, activeTab, visibleTabIds, accessAllowed, employeeFromAggregate } = this.state;
    const employee = selectedEmployeeInfo || employeeFromAggregate;
    const employeeId = resolveEmployee360Id(this.props.match, commonUtils.getCurrentUserId());
    const viewerContext = buildEmployee360ViewerContext(
      {
        activePersona: personaCtx.activePersona,
        scopeType: personaCtx.scopeType,
        scopeIds: personaCtx.context && personaCtx.context.scopeIds,
        employeeId: personaCtx.context && personaCtx.context.employeeId,
        maskingPolicy: personaCtx.maskingPolicy,
      },
      commonUtils.getCurrentUser && commonUtils.getCurrentUser()
    );
    const visibleTabs = getVisibleEmployee360Tabs(
      personaCtx.activePersona,
      visibleTabIds
    )
      .filter((tab) => tab.planned !== true)
      .filter((tab) => tab.id !== "finance" || isEmployee360FinanceTabLive())
      .filter((tab) => tab.id !== "performance" || isEmployee360PerformanceTabLive());
    const resolvedTab = visibleTabs.some((tab) => tab.id === activeTab)
      ? activeTab
      : (visibleTabs[0] && visibleTabs[0].id);

    if (!isEmployee360RouteEnabled(personaCtx.menuAccessControl)) {
      return (
        <PersonaAccessDenied
          moduleName="Employee 360"
          reason="Employee 360 is not enabled for your organization."
        />
      );
    }

    const loading = getInfoLoading || loading360;

    if (!loading && employee && !canViewEmployee360ForPage(viewerContext, employeeId, employee, accessAllowed)) {
      return (
        <PersonaAccessDenied
          moduleName="Employee 360"
          reason={resolveEmployee360AccessDeniedReason(viewerContext, employeeId)}
        />
      );
    }
    return (
      <div className="pd-page profile-page lux-hrms-dash lux-project-details-page lux-employee-360" data-testid="page-employee-360">
        <PageDataSourceReporter dataSource="api" />
        <Employee360BackNav location={this.props.location} employee={employee} />

        <ProfilePageHero employee={employee} readOnly loading={loading} />

        {loadError && !loading && (
          <LuxInlineAlert
            tone="warning"
            title="Unable to load Employee 360"
            className="lux-employee-360__error"
            testId="employee-360-load-error"
          >
            {loadError}
          </LuxInlineAlert>
        )}

        {!employee && !loading && (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact pd-empty lux-employee-360__empty"
            icon="fe fe-user-x"
            title="Employee not found"
            description="The requested employee could not be loaded for Employee 360."
          />
        )}

        {employee && (
          <>
            <Employee360Tabs
              tabs={visibleTabs}
              activeTab={resolvedTab}
              onSelect={this.handleTabSelect}
            />
            <div className="pd-page__body lux-employee-360__body">
              <main
                className="pd-workspace__main lux-employee-360__main"
                role="tabpanel"
                id={`employee-360-tabpanel-${resolvedTab}`}
                aria-labelledby={`employee-360-tab-${resolvedTab}`}
              >
                {this.renderTabPanel(employee, summary, visibleTabs)}
              </main>
            </div>
          </>
        )}
      </div>
    );
  }

  render() {
    const employeeId =
      this.props.match && this.props.match.params && this.props.match.params.employeeId;

    if (!employeeId) {
      return <Employee360LauncherPage />;
    }

    return this.renderProductionPage();
  }
}

const mapStateToProps = (state) => ({
  selectedEmployeeInfo: state.employees.selectedEmployeeInfo,
  getInfoLoading: state.employees.getInfoLoading,
});

const mapDispatchToProps = {
  getEmployeesInfo: employeeActions.getEmployeesInfo,
};

export default connect(mapStateToProps, mapDispatchToProps)(Employee360Page);
