let orgFlags = buildFailClosedOrgFlags();
let configLoaded = false;
let loadPromise = null;

export function readOrgGroupFlag(configList, groupKey, flagKey, defaultWhenMissing = false) {
  const group = commonUtils.getAppConfigValue(configList, groupKey);
  if (!group || typeof group !== "object") {
    return defaultWhenMissing;
  }
  if (!Object.prototype.hasOwnProperty.call(group, flagKey)) {
    return defaultWhenMissing;
  }
  return group[flagKey] === true;
}

