export function getTracopusPilotOrgFlags() {
  return { ...orgFlags };
}

export function isTracopusPilotConfigLoaded() {
  return configLoaded;
}

export function notifyTracopusPilotConfigChanged() {
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(TRACOPUS_PILOT_CONFIG_CHANGED));
  }
}

export function loadTracopusPilotConfig(force, teamIdOverride) {
  if (!force && configLoaded) {
    return Promise.resolve(orgFlags);
  }
  if (!force && loadPromise) {
    return loadPromise;
  }

  const teamId = teamIdOverride || commonUtils.getCurrentUserTeamId();
  if (!teamId) {
    orgFlags = buildFailClosedOrgFlags();
    configLoaded = true;
    return Promise.resolve(orgFlags);
  }

  loadPromise = appConfigService
    .getModuleConfig(teamId, HRMS_MODULE)
    .then((response) => {
      const list = response && response.payload;
      applyTracopusPilotConfig(list);
      applyAuditConfig(list);
      notifyTracopusPilotConfigChanged();
      return orgFlags;
    })
    .catch(() => {
      // Fail-closed: do not invent enabled modules on org config load error.
      orgFlags = buildFailClosedOrgFlags();
      configLoaded = true;
      return orgFlags;
    })
    .finally(() => {
      loadPromise = null;
    });

  return loadPromise;
}

export function refreshTracopusPilotConfig(teamIdOverride) {
  configLoaded = false;
  return loadTracopusPilotConfig(true, teamIdOverride);
}

/**
 * Resolve capability: org Application Config only.
 * Env REACT_APP_* values are ignored for enablement.
 */
function resolveOrgCapability(_envValue, orgKey) {
  return orgFlags[orgKey] === true;
}

