export function isRbacAdminEnabled() {
  return shouldUseRbacAdmin();
}

export function normalizePersonaModulesFromRole(modules) {
  const raw = modules && modules.personaModules;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return {
      configured: false,
      allowedPersonas: [],
      defaultPersona: null,
      personaSwitchEnabled: true,
    };
  }
  const allowed = Array.isArray(raw.allowedPersonas)
    ? raw.allowedPersonas
        .map((p) => String(p || "").trim().toUpperCase())
        .filter((p) => ROLE_PERSONA_OPTIONS.includes(p) || p === "CLIENT")
    : [];
  const defaultPersona =
    raw.defaultPersona != null ? String(raw.defaultPersona).trim().toUpperCase() : null;
  return {
    configured: Array.isArray(raw.allowedPersonas),
    allowedPersonas: allowed,
    defaultPersona:
      defaultPersona && allowed.includes(defaultPersona) ? defaultPersona : allowed[0] || null,
    personaSwitchEnabled: raw.personaSwitchEnabled !== false,
  };
}

export function normalizeRolePermissionProfile(row) {
  if (!row) {
    return null;
  }
  const modules = row.modules && typeof row.modules === "object" && !Array.isArray(row.modules)
    ? row.modules
    : {};
  const statusRaw = String(row.status || ROLE_PERMISSION_STATUSES.ACTIVE).trim().toLowerCase();
  const status =
    statusRaw === "inactive"
      ? ROLE_PERMISSION_STATUSES.INACTIVE
      : ROLE_PERMISSION_STATUSES.ACTIVE;
  return {
    id: row.id != null ? String(row.id) : row.id,
    name: row.name || "Role",
    code: row.code != null ? String(row.code) : String(row.id || ""),
    parentId: row.parentId != null ? String(row.parentId) : null,
    persona: row.persona || "EMPLOYEE",
    status,
    userCount: row.userCount != null ? Number(row.userCount) : 0,
    updatedAt: row.updatedAt || null,
    description: row.description || "",
    modules,
    personaModules: normalizePersonaModulesFromRole(modules),
  };
}

export function flattenPermissionFlags(modules) {
  const rows = [];
  Object.entries(modules || {}).forEach(([moduleKey, flags]) => {
    if (!flags || typeof flags !== "object") {
      return;
    }
    Object.entries(flags).forEach(([flagKey, value]) => {
      if (typeof value === "boolean") {
        rows.push({
          moduleKey,
          flagKey,
          enabled: value,
          label: formatPermissionLabel(flagKey),
        });
      }
    });
  });
  return rows;
}

export function formatPermissionLabel(flagKey) {
  return String(flagKey || "")
    .replace(/Enabled$/i, "")
    .replace(/([A-Z])/g, " $1")
    .replace(/^./, (c) => c.toUpperCase())
    .trim();
}
