export function isOnboardingEnvEnabled() {
  return envconfig.ONBOARDING_ENABLED === true;
}

export function isOffboardingEnvEnabled() {
  return envconfig.OFFBOARDING_ENABLED === true;
}

export function isOnboardingSelfServiceEnvEnabled() {
  return envconfig.ONBOARDING_SELF_SERVICE_ENABLED === true;
}

export function isOnboardingEnabled() {
  return shouldUseOnboarding();
}

export function isOffboardingEnabled() {
  return shouldUseOffboarding();
}

export function isOnboardingSelfServiceEnabled() {
  return shouldUseOnboardingSelfService();
}

export function isOnboardingRouteEnabled(menuAccessControl) {
  if (!menuAccessControl || !menuAccessControl.peopleModules) {
    return false;
  }
  return menuAccessControl.peopleModules.onboardingEnabled === true;
}

export function isOffboardingRouteEnabled(menuAccessControl) {
  if (!menuAccessControl || !menuAccessControl.peopleModules) {
    return false;
  }
  return menuAccessControl.peopleModules.offboardingEnabled === true;
}

export function isOnboardingSelfServiceRouteEnabled(menuAccessControl) {
  if (!menuAccessControl || !menuAccessControl.peopleModules) {
    return false;
  }
  return menuAccessControl.peopleModules.onboardingSelfServiceEnabled === true;
}

