const STORAGE_PATH_KEY = "tracopus:profileDetails:returnPath";
const STORAGE_LABEL_KEY = "tracopus:profileDetails:returnLabel";

const LEGACY_PROFILE_PATH_RE = /^\/hrms\/profile\/[^/]+/;
const CANONICAL_EMPLOYEE_DETAILS_RE = /^\/people\/employees\/[^/]+$/;
const LEGACY_EMPLOYEE_DETAILS_RE = /^\/hrms\/employees\/[^/]+$/;
const EMPLOYEE_360_PATH_RE = /^\/(people|hrms)\/employees\/[^/]+\/360$/;

const RETURN_LABEL_RULES = [
  { test: (p) => p === "/people/employees" || p === "/hrms/employees", label: "Employees" },
  { test: (p) => p.startsWith("/people/employees/") || p.startsWith("/hrms/employees/"), label: "Employee details" },
  { test: (p) => p.startsWith("/people/dashboard") || p.startsWith("/hrms/dashboard"), label: "Dashboard" },
  { test: (p) => p.startsWith("/people/attendance") || p.startsWith("/hrms/attendance"), label: "Attendance" },
  { test: (p) => p.startsWith("/people/timesheet") || p.startsWith("/hrms/timesheet"), label: "Timesheet" },
  { test: (p) => p.startsWith("/people/holidays") || p.startsWith("/hrms/holidays"), label: "Holidays" },
  { test: (p) => p.startsWith("/people/leaves") || p.startsWith("/hrms/leaves"), label: "Leaves" },
  { test: (p) => p.startsWith("/people/"), label: "People" },
  { test: (p) => p.startsWith("/hrms/"), label: "People" },
  { test: (p) => p.startsWith("/project/"), label: "Projects" },
  { test: (p) => p.startsWith("/sales/"), label: "Sales" },
];

const DEFAULT_RETURN = { path: "/people/employees", label: "Employees" };

export function getEmployeeDetailsPathname(employeeId) {
  return `/people/employees/${employeeId}`;
}

/** Canonical employee details URL (ProfilePage) — People layout. */
export function isEmployeeDetailsPath(pathname = "") {
  const path = (pathname || "").split("?")[0];
  if (LEGACY_PROFILE_PATH_RE.test(path)) {
    return true;
  }
  if (CANONICAL_EMPLOYEE_DETAILS_RE.test(path)) {
    return true;
  }
  return LEGACY_EMPLOYEE_DETAILS_RE.test(path);
}

/** @deprecated Use isEmployeeDetailsPath */
export function isProfileDetailsPath(pathname = "") {
  return isEmployeeDetailsPath(pathname);
}

function isEmployee360Path(pathname = "") {
  return EMPLOYEE_360_PATH_RE.test((pathname || "").split("?")[0]);
}

function isSafeReturnPath(path) {
  if (!path || typeof path !== "string" || !path.startsWith("/")) {
    return false;
  }
  const pathname = path.split("?")[0];
  if (isEmployeeDetailsPath(pathname) || isEmployee360Path(pathname)) {
    return false;
  }
  return /^\/(hrms|project|sales|workspace|people|admin|finance)\//.test(pathname);
}

export function getReturnLabelForPath(path) {
  const pathname = (path || "").split("?")[0];
  const rule = RETURN_LABEL_RULES.find((r) => r.test(pathname));
  return rule ? rule.label : "previous page";
}

export function captureProfileDetailsReturn(fromPathname, fromSearch = "") {
  const path = `${fromPathname || ""}${fromSearch || ""}`;
  if (!isSafeReturnPath(path)) {
    return;
  }
  try {
    sessionStorage.setItem(STORAGE_PATH_KEY, path);
    sessionStorage.setItem(STORAGE_LABEL_KEY, getReturnLabelForPath(path));
  } catch (_e) {
    /* ignore */
  }
}

function readStoredReturn() {
  try {
    const path = sessionStorage.getItem(STORAGE_PATH_KEY);
    const label = sessionStorage.getItem(STORAGE_LABEL_KEY);
    if (path && isSafeReturnPath(path)) {
      return { path, label: label || getReturnLabelForPath(path) };
    }
  } catch (_e) {
    /* ignore */
  }
  return null;
}

export function getProfileDetailsReturnTarget(location) {
  const state = location && location.state;
  const stateFrom = state && state.from;
  if (stateFrom && typeof stateFrom === "string" && stateFrom.startsWith("/")) {
    if (state.fromLabel) {
      return { path: stateFrom, label: state.fromLabel };
    }
    if (isSafeReturnPath(stateFrom)) {
      return {
        path: stateFrom,
        label: getReturnLabelForPath(stateFrom),
      };
    }
  }

  const stored = readStoredReturn();
  if (stored) {
    return stored;
  }

  return DEFAULT_RETURN;
}

export function buildEmployeeDetailsLink(employeeId, fromLocation, fromLabel) {
  const pathname = getEmployeeDetailsPathname(employeeId);
  if (!fromLocation) {
    return { pathname };
  }

  const from = (fromLocation.pathname || "") + (fromLocation.search || "");
  const linkState = { from };
  if (fromLabel) {
    linkState.fromLabel = fromLabel;
  }
  return { pathname, state: linkState };
}

/** @deprecated Use buildEmployeeDetailsLink */
export const buildProfileDetailsLink = buildEmployeeDetailsLink;
