import {
  ENTERPRISE_SUMMARY,
  FINANCE_BILLING_PLANS,
  FINANCE_INVOICE_RECOMMENDATIONS,
  FINANCE_REVENUE_FORECASTS,
  FINANCE_REVENUE_LEAKAGE,
  PROJECT_FINANCIAL_SNAPSHOTS,
} from "mock/data/enterprise.mock";
import { buildFinanceDashboardOverview } from "config/finance-intelligence.modules.utils";
import {
  FINANCE_BILLING_STATUSES,
  FINANCE_MARGIN_BANDS,
  normalizeProjectFinancialSnapshot,
} from "config/finance-intelligence.config";

const SENSITIVE_MASK = "••••";

export function filterProjectFinancialSnapshots(rows = [], filters = {}) {
  let result = rows.map((row) => normalizeProjectFinancialSnapshot(row)).filter(Boolean);

  if (filters.marginBand && filters.marginBand !== "ALL") {
    result = result.filter((row) => row.marginBand === filters.marginBand);
  }
  if (filters.billingStatus && filters.billingStatus !== "ALL") {
    result = result.filter((row) => row.billingStatus === filters.billingStatus);
  }
  if (filters.programId && filters.programId !== "ALL") {
    result = result.filter((row) => row.programId === filters.programId);
  }
  if (filters.search) {
    const term = String(filters.search).trim().toLowerCase();
    if (term) {
      result = result.filter(
        (row) =>
          (row.projectName && row.projectName.toLowerCase().indexOf(term) >= 0) ||
          (row.projectCode && row.projectCode.toLowerCase().indexOf(term) >= 0) ||
          (row.ownerName && row.ownerName.toLowerCase().indexOf(term) >= 0)
      );
    }
  }
  return result;
}

export function maskSensitiveFinancialSnapshots(rows = [], options = {}) {
  const includeSensitive = options.includeSensitive === true;
  if (includeSensitive) {
    return rows;
  }
  return rows.map((row) => {
    if (!row.sensitive) {
      return row;
    }
    return {
      ...row,
      marginPct: null,
      marginBand: row.marginBand,
      revenueUsd: null,
      costUsd: null,
      unbilledUsd: null,
      billedUsd: null,
      poRemainingUsd: null,
      forecastVariancePct: null,
      masked: true,
      marginDisplay: SENSITIVE_MASK,
      revenueDisplay: SENSITIVE_MASK,
      costDisplay: SENSITIVE_MASK,
      unbilledDisplay: SENSITIVE_MASK,
    };
  });
}

export function formatFinanceUsd(value, masked) {
  if (masked) {
    return SENSITIVE_MASK;
  }
  if (value == null || Number.isNaN(Number(value))) {
    return "—";
  }
  return `$${Math.round(Number(value)).toLocaleString()}`;
}

export function formatFinancePct(value, masked) {
  if (masked) {
    return SENSITIVE_MASK;
  }
  if (value == null || Number.isNaN(Number(value))) {
    return "—";
  }
  return `${Number(value)}%`;
}

export function buildProjectFinancialsRollup(rows = [], options = {}) {
  const snapshots = rows.map((row) => normalizeProjectFinancialSnapshot(row)).filter(Boolean);
  const includeSensitive = options.includeSensitive === true;
  const canRollupFinancials = includeSensitive || snapshots.every((row) => !row.sensitive);

  const totals = snapshots.reduce(
    (acc, row) => {
      if (includeSensitive || !row.sensitive) {
        acc.revenueUsd += row.revenueUsd || 0;
        acc.costUsd += row.costUsd || 0;
        acc.unbilledUsd += row.unbilledUsd || 0;
        acc.billedUsd += row.billedUsd || 0;
        acc.marginWeight += (row.marginPct || 0) * (row.revenueUsd || 0);
        acc.revenueWeight += row.revenueUsd || 0;
      }
      if (row.billingStatus === FINANCE_BILLING_STATUSES.OVERDUE) {
        acc.overdueCount += 1;
      }
      if (row.billingStatus === FINANCE_BILLING_STATUSES.READY) {
        acc.readyCount += 1;
      }
      if (row.marginBand === FINANCE_MARGIN_BANDS.CRITICAL || row.marginBand === FINANCE_MARGIN_BANDS.WATCH) {
        acc.atRiskCount += 1;
      }
      return acc;
    },
    {
      revenueUsd: 0,
      costUsd: 0,
      unbilledUsd: 0,
      billedUsd: 0,
      marginWeight: 0,
      revenueWeight: 0,
      overdueCount: 0,
      readyCount: 0,
      atRiskCount: 0,
    }
  );

  const blendedMarginPct =
    canRollupFinancials && totals.revenueWeight > 0
      ? Math.round(totals.marginWeight / totals.revenueWeight)
      : null;

  return {
    projectCount: snapshots.length,
    revenueUsd: canRollupFinancials ? totals.revenueUsd : null,
    costUsd: canRollupFinancials ? totals.costUsd : null,
    unbilledUsd: canRollupFinancials ? totals.unbilledUsd : null,
    billedUsd: canRollupFinancials ? totals.billedUsd : null,
    blendedMarginPct,
    overdueCount: totals.overdueCount,
    readyCount: totals.readyCount,
    atRiskCount: totals.atRiskCount,
    maskedRollup: !canRollupFinancials,
  };
}

export function buildProjectFinancialsKpiCards(rollup = {}) {
  return [
    {
      id: "revenue",
      label: "Contract revenue",
      value: rollup.maskedRollup ? SENSITIVE_MASK : formatFinanceUsd(rollup.revenueUsd),
      hint: `${rollup.projectCount || 0} projects`,
      tone: "indigo",
      icon: "fe fe-dollar-sign",
    },
    {
      id: "margin",
      label: "Blended margin",
      value: rollup.maskedRollup ? SENSITIVE_MASK : formatFinancePct(rollup.blendedMarginPct),
      hint: "Revenue-weighted",
      tone: "green",
      icon: "fe fe-trending-up",
    },
    {
      id: "unbilled",
      label: "Unbilled work",
      value: rollup.maskedRollup ? SENSITIVE_MASK : formatFinanceUsd(rollup.unbilledUsd),
      hint: `${rollup.readyCount || 0} billing-ready`,
      tone: "amber",
      icon: "fe fe-alert-circle",
    },
    {
      id: "at-risk",
      label: "Margin watch",
      value: String(rollup.atRiskCount || 0),
      hint: `${rollup.overdueCount || 0} overdue billing`,
      tone: "rose",
      icon: "fe fe-shield",
    },
  ];
}

export function buildProjectFinancialsInsights(rows = []) {
  const snapshots = rows.map((row) => normalizeProjectFinancialSnapshot(row)).filter(Boolean);
  const insights = [];

  const overdue = snapshots.filter((row) => row.billingStatus === FINANCE_BILLING_STATUSES.OVERDUE);
  if (overdue.length) {
    insights.push({
      id: "overdue-billing",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${overdue.length} project${overdue.length > 1 ? "s" : ""} with overdue billing`,
      body: `${overdue.map((row) => row.projectName).join(", ")} need collections follow-up.`,
      path: "/finance/invoice",
    });
  }

  const lowReadiness = snapshots
    .filter((row) => row.billingReadinessPct != null && row.billingReadinessPct < 70)
    .sort((a, b) => a.billingReadinessPct - b.billingReadinessPct);
  if (lowReadiness.length) {
    insights.push({
      id: "billing-readiness",
      tone: "amber",
      icon: "fe fe-clock",
      title: "Billing readiness gap",
      body: `${lowReadiness[0].projectName} is at ${lowReadiness[0].billingReadinessPct}% readiness — review milestone billing.`,
      path: "/finance/billing-plans",
    });
  }

  const highBurn = snapshots.filter((row) => row.poBurnPct != null && row.poBurnPct >= 75);
  if (highBurn.length) {
    insights.push({
      id: "po-burn",
      tone: "violet",
      icon: "fe fe-shopping-cart",
      title: "High PO burn",
      body: `${highBurn.map((row) => row.projectName).join(", ")} exceed 75% PO consumption.`,
      path: "/finance/purchaseorders",
    });
  }

  if (!insights.length) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      title: "Portfolio billing stable",
      body: "No overdue billing or critical margin alerts in the current scope.",
      path: "/analytics/finance",
    });
  }

  return insights;
}

export function buildProjectFinancialsOverview(rows = [], options = {}) {
  const filtered = filterProjectFinancialSnapshots(rows, options.filters || {});
  const secured =
    options.maskSensitive === true ? maskSensitiveFinancialSnapshots(filtered, options) : filtered;
  const rollup = buildProjectFinancialsRollup(filtered, { includeSensitive: true });
  return {
    snapshots: secured,
    rollup,
    kpiCards: buildProjectFinancialsKpiCards(rollup),
    insights: buildProjectFinancialsInsights(filtered),
    programOptions: Array.from(
      new Map(
        filtered
          .filter((row) => row.programId)
          .map((row) => [row.programId, { id: row.programId, name: row.programName }])
      ).values()
    ),
  };
}

export function exportProjectFinancialsCsv(rows = [], options = {}) {
  const secured = maskSensitiveFinancialSnapshots(
    rows.map((row) => normalizeProjectFinancialSnapshot(row)).filter(Boolean),
    options
  );
  if (!secured.length) {
    return "";
  }
  const header =
    "project_code,project_name,program,margin_pct,margin_band,revenue_usd,cost_usd,unbilled_usd,billing_status,po_burn_pct,collection_pct,billing_readiness_pct,sensitive,masked";
  const lines = secured.map((row) => {
    const masked = row.masked === true;
    const cells = [
      row.projectCode,
      row.projectName,
      row.programName || "",
      masked ? SENSITIVE_MASK : row.marginPct,
      row.marginBand || "",
      masked ? SENSITIVE_MASK : row.revenueUsd,
      masked ? SENSITIVE_MASK : row.costUsd,
      masked ? SENSITIVE_MASK : row.unbilledUsd,
      row.billingStatus,
      row.poBurnPct,
      row.collectionPct,
      row.billingReadinessPct,
      row.sensitive ? "yes" : "no",
      masked ? "yes" : "no",
    ];
    return cells.map((cell) => `"${String(cell == null ? "" : cell).replace(/"/g, '""')}"`).join(",");
  });
  return [header, ...lines].join("\n");
}

export function validateProjectFinancialSnapshotPayload(payload = {}) {
  const errors = [];
  if (!payload.projectId) {
    errors.push("projectId is required");
  }
  if (payload.marginPct != null && Number.isNaN(Number(payload.marginPct))) {
    errors.push("marginPct must be numeric");
  }
  return { valid: errors.length === 0, errors };
}

export function buildFinanceHubKpiCards(context = {}) {
  const overview = buildFinanceDashboardOverview({
    snapshots: context.snapshots || PROJECT_FINANCIAL_SNAPSHOTS,
    billingPlans: context.billingPlans || FINANCE_BILLING_PLANS,
    forecasts: context.forecasts || FINANCE_REVENUE_FORECASTS,
    leakage: context.leakage || FINANCE_REVENUE_LEAKAGE,
    recommendations: context.recommendations || FINANCE_INVOICE_RECOMMENDATIONS,
  });
  return overview.kpiCards;
}

export function buildFinanceHubInsights(context = {}) {
  const overview = buildFinanceDashboardOverview({
    snapshots: context.snapshots || PROJECT_FINANCIAL_SNAPSHOTS,
    billingPlans: context.billingPlans || FINANCE_BILLING_PLANS,
    forecasts: context.forecasts || FINANCE_REVENUE_FORECASTS,
    leakage: context.leakage || FINANCE_REVENUE_LEAKAGE,
    recommendations: context.recommendations || FINANCE_INVOICE_RECOMMENDATIONS,
  });
  if (!overview.insights.length) {
    return [
      {
        id: "fallback",
        tone: "indigo",
        icon: "fe fe-layers",
        title: `${ENTERPRISE_SUMMARY.atRiskProjects} at-risk projects`,
        body: "Review project financials before the next steering pack.",
        path: "/finance/project-financials",
      },
    ];
  }
  return overview.insights;
}
