import React, { Component } from "react";
import { npdService } from "_services/npd/npd.service";
import NpdLuxPage, {
  NpdActionButton,
  NpdLuxPanel,
} from "views/npd/components/NpdLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class NpdDashboardPage extends Component {
  state = { loading: true, loadError: null, summary: null };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("NPD dashboard");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, loadError: null });
    const result = await npdService.dashboardSummary();
    if (result.source === "api" && result.payload) {
      this.setState({ loading: false, summary: result.payload });
    } else {
      this.setState({
        loading: false,
        summary: null,
        loadError: result.error || new Error("Unable to load NPD dashboard"),
      });
    }
  };

  render() {
    const { loading, loadError, summary } = this.state;
    const kpiCards = summary
      ? [
          { id: "ideas", label: "Ideas", value: summary.ideaCount, icon: "fe fe-lightbulb" },
          { id: "gate", label: "In gate", value: summary.inGateCount, icon: "fe fe-git-branch" },
          { id: "ready", label: "Launch ready", value: summary.launchReadyCount, icon: "fe fe-check-circle" },
          { id: "launched", label: "Launched", value: summary.launchedCount, icon: "fe fe-rocket" },
          { id: "rejected", label: "Rejected", value: summary.rejectedCount, icon: "fe fe-x-circle" },
          { id: "pending", label: "Pending gates", value: summary.pendingGateCount, icon: "fe fe-clock" },
          { id: "projects", label: "Linked projects", value: summary.linkedProjectCount, icon: "fe fe-folder" },
        ]
      : [];

    return (
      <NpdLuxPage
        testId="npd-dashboard-page"
        dataSource={summary ? "api" : loadError ? "api-error" : null}
        loading={loading}
        kpiCards={kpiCards}
        pageMeta={{
          tone: "violet",
          icon: "fe fe-zap",
          eyebrow: "Projects · NPD",
          titleLead: "NPD",
          titleAccent: "dashboard",
          lede: "Idea-to-launch lifecycle on Project/Task/Gate/Risk/Issue — not a duplicate project system.",
        }}
        heroActions={
          <>
            <NpdActionButton to="/npd/ideas" icon="fe fe-lightbulb" variant="secondary">
              Ideas
            </NpdActionButton>
            <NpdActionButton to="/npd/gates" icon="fe fe-git-branch" variant="secondary">
              Gates
            </NpdActionButton>
            <NpdActionButton to="/npd/launch" icon="fe fe-rocket">
              Launch checklist
            </NpdActionButton>
          </>
        }
      >
        {loadError ? (
          <LuxInlineAlert tone="warning" title="Unable to load NPD dashboard">
            {String(loadError.message || loadError)}{" "}
            <button type="button" className="lux-onb-action lux-onb-action--ghost lux-onb-action--compact" onClick={this.load}>
              Retry
            </button>
          </LuxInlineAlert>
        ) : null}
        {!loading && !summary && !loadError ? (
          <LuxRegisterEmptyState
            title="No NPD summary yet"
            description="Create ideas to populate the new product development dashboard."
            showCreate={false}
          />
        ) : null}
        {summary ? (
          <NpdLuxPanel title="Lifecycle snapshot" meta="Live aggregate from ideas, gates, and launch readiness." icon="fe fe-activity">
            <ul className="list-unstyled mb-0">
              <li>
                Ideas in pipeline: <strong>{summary.ideaCount != null ? summary.ideaCount : "—"}</strong>
              </li>
              <li>
                Pending gates: <strong>{summary.pendingGateCount != null ? summary.pendingGateCount : "—"}</strong>
              </li>
              <li>
                Linked projects: <strong>{summary.linkedProjectCount != null ? summary.linkedProjectCount : "—"}</strong>
              </li>
            </ul>
          </NpdLuxPanel>
        ) : null}
      </NpdLuxPage>
    );
  }
}

export default NpdDashboardPage;
