export const COMPLIANCE_PACK_SECTION_IDS = Object.keys(COMPLIANCE_PACK_SECTIONS);

export function isComplianceExportAdminEnabled() {
  return shouldUseComplianceExportAdmin();
}

export function getCompliancePackSectionMeta(sectionId) {
  return COMPLIANCE_PACK_SECTIONS[sectionId] || {
    id: sectionId,
    label: sectionId,
    icon: "fe fe-file",
    tone: "slate",
    description: "",
  };
}

export function normalizeCompliancePackSection(row) {
  if (!row) {
    return null;
  }
  const meta = getCompliancePackSectionMeta(row.id);
  return {
    id: row.id,
    label: meta.label,
    icon: meta.icon,
    tone: meta.tone,
    description: meta.description,
    recordCount: row.recordCount != null ? row.recordCount : 0,
    ready: row.ready !== false,
    lastExportedAt: row.lastExportedAt || null,
    checksum: row.checksum || null,
    payloadPreview: row.payloadPreview || null,
  };
}
