import React from "react";
import LuxBackNav from "views/common/fragments/LuxBackNav";
import { usePersonaContext } from "hooks/usePersonaContext";
import { canShowEmployee360Entry } from "config/employee360.utils";
import { getEmployee360ReturnTarget } from "views/people/employee360Navigation.utils";
import { getEmployeeDisplayName } from "config/employee360.utils";
import Employee360DetailsEntryLink from "./Employee360DetailsEntryLink";

export default function Employee360BackNav({ location, employee }) {
  const { menuAccessControl, activePersona } = usePersonaContext();
  const { path, label } = getEmployee360ReturnTarget(location);
  const employeeId = employee && employee.id;
  const showDetailsLink =
    employeeId && canShowEmployee360Entry(menuAccessControl, activePersona);

  return (
    <LuxBackNav
      to={path}
      destinationLabel={label}
      currentLabel={employee ? getEmployeeDisplayName(employee) : "Employee 360"}
      actions={
        showDetailsLink ? (
          <Employee360DetailsEntryLink employeeId={employeeId} location={location} />
        ) : null
      }
    />
  );
}
