import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";

export const approvalReminderService = {
  getEligibility,
  sendReminder,
};

async function getEligibility(requestType, referenceId, employeeId) {
  return axiosUtils.getWithParam(urlConfig.APPROVAL_REMIND_API_PATH + "/eligibility", {
    requestType,
    referenceId,
    employeeId,
  });
}

async function sendReminder(payload) {
  return axiosUtils.post(urlConfig.APPROVAL_REMIND_API_PATH, payload);
}
