import dateUtils from "_helpers/date.utils";
import { getTaskStatusMeta, minsToHoursLabel } from "./userDiv.utils";

export function getItemDurationMins(item) {
  const status = (item.status || "").toUpperCase();
  if (status === "COMPLETED" || status === "CLOSED") {
    return Number(item.durationInMins) || 0;
  }
  return Number(item.estDurationInMins) || 0;
}

export function getItemTimeRangeLabel(item) {
  const durationInMinutes = getItemDurationMins(item);
  const estStartTime =
    item.estStartTime && dateUtils.convertDateStringToMoment(item.estStartTime);
  const actualStartTime =
    item.actualStartTime && dateUtils.convertDateStringToMoment(item.actualStartTime);
  const start = actualStartTime || estStartTime;
  if (!start) return "—";
  const end = dateUtils.addXToMoments(start, "minutes", durationInMinutes);
  return `${start.format("hh:mm A")} – ${end.format("hh:mm A")}`;
}

export function summarizeTodayItems(items) {
  const list = Array.isArray(items) ? items : [];
  let completed = 0;
  let inProgress = 0;
  let scheduled = 0;
  let paused = 0;
  let estMins = 0;
  let loggedMins = 0;

  list.forEach((item) => {
    const status = (item.status || "").toUpperCase();
    estMins += Number(item.estDurationInMins) || 0;
    if (status === "COMPLETED" || status === "CLOSED") {
      completed += 1;
      loggedMins += Number(item.durationInMins) || Number(item.estDurationInMins) || 0;
    } else if (status === "INPROGRESS") {
      inProgress += 1;
      loggedMins += Number(item.durationInMins) || 0;
    } else if (status === "PAUSED") {
      paused += 1;
    } else {
      scheduled += 1;
    }
  });

  const total = list.length;
  const progressPct = total > 0 ? Math.round((completed / total) * 100) : 0;
  const timeProgressPct =
    estMins > 0 ? Math.min(100, Math.round((loggedMins / estMins) * 100)) : 0;

  return {
    total,
    completed,
    inProgress,
    scheduled,
    paused,
    estMins,
    loggedMins,
    progressPct,
    timeProgressPct,
  };
}

export function buildActivityFeed(items) {
  const list = Array.isArray(items) ? [...items] : [];

  return list
    .map((item) => {
      const status = (item.status || "").toUpperCase();
      const meta = getTaskStatusMeta(item.status);
      let action = "Scheduled";
      let icon = "fe-calendar";

      if (status === "COMPLETED" || status === "CLOSED") {
        action = "Completed";
        icon = "fe-check-circle";
      } else if (status === "INPROGRESS") {
        action = "In progress";
        icon = "fe-play-circle";
      } else if (status === "PAUSED") {
        action = "Paused";
        icon = "fe-pause-circle";
      } else if (status === "ASSIGNED") {
        action = "Assigned";
        icon = "fe-user-check";
      }

      const when =
        item.actualStartTime ||
        item.estStartTime ||
        item.lastUpdatedTime ||
        item.createdDate;

      return {
        id: item.id,
        action,
        icon,
        statusClass: meta.className,
        title: item.name,
        subtitle: item.taskName || item.taskActCategory || "Work item",
        time: when ? dateUtils.convertDateTimeFormat(when) : null,
        sortTime: when ? new Date(when).getTime() : 0,
      };
    })
    .sort((a, b) => b.sortTime - a.sortTime);
}

export function formatTodayDate() {
  return dateUtils.getCurrentTime().format("dddd, MMM D");
}

export { getTaskStatusMeta, minsToHoursLabel };
