import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isAiWorkIntelligenceEnabled } from "config/ai-work-intelligence.config";
import { accessUtils } from "_helpers";
import { aiWorkIntelligenceService } from "_services/aiWorkIntelligence.service";
import AiLuxPage, { AiActionButton, AiLuxPanel } from "views/ai/components/AiLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

class AiAuditPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    records: [],
    recordTypeFilter: "ALL",
    riskLevelFilter: "ALL",
    query: "",
    exporting: false,
    exportMessage: null,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("AI decision audit");
    this.loadAudit();
  }

  loadAudit = async () => {
    this.setState({ loading: true, loadError: null, exportMessage: null });
    try {
      const { recordTypeFilter, riskLevelFilter, query } = this.state;
      const result = await aiWorkIntelligenceService.listAuditTrail({
        query: query || undefined,
        riskLevel: riskLevelFilter !== "ALL" ? riskLevelFilter : undefined,
      });
      this.setState({ records: result.payload || [], loading: false, dataSource: result.source });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load AI audit trail.", records: [] });
    }
  };

  exportAudit = async () => {
    const { recordTypeFilter, riskLevelFilter, query } = this.state;
    this.setState({ exporting: true, exportMessage: null });
    try {
      const result = await aiWorkIntelligenceService.exportAuditTrailCsv({
        query: query || undefined,
        riskLevel: riskLevelFilter !== "ALL" ? riskLevelFilter : undefined,
      });
      const csv = result.payload || "";
      const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement("a");
      anchor.href = url;
      anchor.download = "ai-audit-export.csv";
      anchor.click();
      URL.revokeObjectURL(url);
      this.setState({ exporting: false, exportMessage: "Masked audit export downloaded." });
    } catch (e) {
      this.setState({ exporting: false, exportMessage: "Unable to export audit records." });
    }
  };

  getFiltered = () => {
    const { records, recordTypeFilter, query } = this.state;
    const q = query.trim().toLowerCase();
    return records.filter((row) => {
      if (recordTypeFilter !== "ALL" && row.recordType !== recordTypeFilter) return false;
      if (!q) return true;
      return [row.id, row.agentName, row.summary, row.status, row.decision]
        .filter(Boolean)
        .join(" ")
        .toLowerCase()
        .includes(q);
    });
  };

  render() {
    const aiModules = accessUtils.getAccessControll("aiModules") || {};
    if (!isAiWorkIntelligenceEnabled() || aiModules.auditEnabled === false) {
      return (
        <PersonaAccessDenied
          moduleName="AI decision audit"
          reason="AI audit review is not enabled for your organization or persona."
        />
      );
    }

    const filtered = this.getFiltered();
    const { loading, loadError, dataSource } = this.state;

    return (
      <div data-testid="page-ai-audit">
        <AiLuxPage
          pageId="ai-audit"
          shellTitle="AI decision audit"
          dataSource={dataSource}
          loading={loading}
          pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
          onRefresh={this.loadAudit}
        refreshLoading={loading}
        >
          <p className="lux-ai-intel-lead">
            Masked audit metadata for agent runs and recommendations — raw sensitive prompt data is never persisted.
          </p>

          {loadError && <p className="lux-ai-intel-error">{loadError}</p>}
          {this.state.exportMessage && <p className="lux-ai-intel-note">{this.state.exportMessage}</p>}

          <AiLuxPanel title="Audit trail" subtitle="Agent runs and recommendation outcomes">
            <div className="lux-admin-toolbar mb-3">
              <input
                type="search"
                className="form-control"
                placeholder="Search agent, summary, decision"
                value={this.state.query}
                onChange={(e) => this.setState({ query: e.target.value })}
                onKeyDown={(e) => e.key === "Enter" && this.loadAudit()}
              />
              <select
                className="form-control"
                value={this.state.recordTypeFilter}
                onChange={(e) => this.setState({ recordTypeFilter: e.target.value })}
              >
                <option value="ALL">All records</option>
                <option value="AGENT_RUN">Agent runs</option>
                <option value="RECOMMENDATION">Recommendations</option>
              </select>
              <select
                className="form-control"
                value={this.state.riskLevelFilter}
                onChange={(e) => this.setState({ riskLevelFilter: e.target.value }, this.loadAudit)}
              >
                <option value="ALL">All risk levels</option>
                <option value="HIGH">High risk</option>
                <option value="MEDIUM">Medium risk</option>
                <option value="LOW">Low risk</option>
              </select>
              <AiActionButton icon="fe fe-filter" onClick={this.loadAudit} disabled={loading}>
                Apply filters
              </AiActionButton>
            </div>

            {loading ? (
              <LuxRegisterEmptyState title="Loading" description="Fetching masked AI audit records." />
            ) : filtered.length === 0 ? (
              <LuxRegisterEmptyState title="No records" description="No AI audit entries match your filters." />
            ) : (
              <div className="table-responsive">
                <table className="table table-hover">
                  <thead>
                    <tr>
                      <th>Type</th>
                      <th>Agent</th>
                      <th>Summary</th>
                      <th>Status / decision</th>
                      <th>Source</th>
                      <th>Masked</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filtered.map((row) => (
                      <tr key={`${row.recordType}-${row.id}`}>
                        <td>{row.recordType}</td>
                        <td>{row.agentName || row.agentId}</td>
                        <td>{row.summary || row.rationale || "—"}</td>
                        <td>{row.decision || row.status || "—"}</td>
                        <td>
                          {row.sourceEntityType
                            ? `${row.sourceEntityType}${row.sourceEntityId ? ` #${row.sourceEntityId}` : ""}`
                            : "—"}
                        </td>
                        <td>{row.maskingApplied ? "Yes" : "—"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </AiLuxPanel>
        </AiLuxPage>
      </div>
    );
  }
}

export default AiAuditPage;
