import React, { Component } from "react";
import CountUp from "react-countup";
import { store } from "_helpers";
import { commonUtils } from "_helpers";

class PurchaseOrderDetailStatistics extends Component {
  componentDidMount() {
    if (this.props.loadData && this.props.itemId) {
      store.dispatch(this.props.loadData(this.props.itemId));
    }
  }

  componentDidUpdate(prevProps) {
    if (prevProps.itemId !== this.props.itemId && this.props.loadData && this.props.itemId) {
      store.dispatch(this.props.loadData(this.props.itemId));
    }
  }

  getSum = (itemName) => {
    let sum = 0;
    if (this.props.items) {
      this.props.items.forEach((item) => {
        sum += item[itemName] || 0;
      });
    }
    return sum;
  };

  render() {
    const completedCount = this.getSum("completedCount");
    const inProgressCount = this.getSum("inProgressCount");
    const newCount = this.getSum("newCount");
    const assignedCount = this.getSum("assignedCount");

    return (
      <section className="lux-bid-detail__card lux-po-detail-stats">
        <header className="lux-bid-detail__card-head">
          <h2>Project statistics</h2>
        </header>
        <div className="lux-po-detail-stats__grid">
          <div className="lux-po-detail-stats__kpi">
            <span className="lux-po-detail-stats__kpi-label">Completed</span>
            <strong className="lux-po-detail-stats__kpi-value is-green">
              <CountUp end={completedCount} duration={0.7} />
            </strong>
          </div>
          <div className="lux-po-detail-stats__kpi">
            <span className="lux-po-detail-stats__kpi-label">In progress</span>
            <strong className="lux-po-detail-stats__kpi-value is-amber">
              <CountUp end={inProgressCount} duration={0.7} />
            </strong>
          </div>
          <div className="lux-po-detail-stats__kpi">
            <span className="lux-po-detail-stats__kpi-label">New</span>
            <strong className="lux-po-detail-stats__kpi-value is-sky">
              <CountUp end={newCount} duration={0.7} />
            </strong>
          </div>
          <div className="lux-po-detail-stats__kpi">
            <span className="lux-po-detail-stats__kpi-label">Assigned</span>
            <strong className="lux-po-detail-stats__kpi-value is-indigo">
              <CountUp end={assignedCount} duration={0.7} />
            </strong>
          </div>
        </div>

        {this.props.items && this.props.items.length > 0 && (
          <div className="lux-po-detail-stats__breakdown">
            {this.props.items.map((item, index) => (
              <div key={index} className="lux-po-detail-stats__row">
                <div className="lux-po-detail-stats__row-head">
                  <span className="lux-po-detail-stats__row-label" title={item.category || "Other"}>
                    {item.category || "Other"}
                  </span>
                  <span className="lux-po-detail-stats__row-counts">
                    {item.completedCount || 0} / {item.inProgressCount || 0}
                  </span>
                </div>
                <div className="lux-po-detail-stats__bar" aria-hidden="true">
                  <span
                    style={{
                      width: `${commonUtils.getPercentageOfCompletion(
                        item.completedCount,
                        item.inProgressCount
                      )}%`,
                    }}
                  />
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    );
  }
}

export default PurchaseOrderDetailStatistics;
