import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPaychecksEnabled, PAYCHECK_STATUSES } from "config/payroll.config";
import {
  buildPaycheckAdminMetrics,
  buildPaycheckInsights,
  filterPaychecks,
} from "config/paycheck.utils";
import { formatPayrollCurrency } from "config/payroll.utils";
import { payrollService } from "_services/payroll.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import PaycheckRegister from "views/payroll/components/PaycheckRegister";
import {
  PayrollActionButton,
  PayrollLuxPage,
  PayrollPanelHead,
} from "views/payroll/components/PayrollLuxShared";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

class PaychecksPage extends Component {
  state = {
    paychecks: [],
    loading: true,
    loadError: null,
    dataSource: null,
    statusFilter: "ALL",
    query: "",
    acting: false,
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Paychecks");
    this.loadPaychecks();
  }

  loadPaychecks = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await payrollService.listPaychecks();
      this.setState({
        paychecks: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load paychecks.", paychecks: [] });
    }
  };

  handlePublish = async (paycheck) => {
    this.setState({ acting: true });
    try {
      await payrollService.publishPaycheck(paycheck.id);
      await this.loadPaychecks();
    } finally {
      this.setState({ acting: false });
    }
  };

  handleRetract = async (paycheck) => {
    this.setState({ acting: true });
    try {
      await payrollService.retractPaycheck(paycheck.id);
      await this.loadPaychecks();
    } finally {
      this.setState({ acting: false });
    }
  };

  getFilteredPaychecks = () => {
    const { paychecks, statusFilter, query } = this.state;
    return filterPaychecks(paychecks, {
      status: statusFilter === "ALL" ? null : statusFilter,
      query,
    });
  };

  renderInsights = () => {
    const { paychecks, loading } = this.state;
    if (loading) return null;
    const insights = buildPaycheckInsights(paychecks);
    if (!insights.length) return null;
    return (
      <div className="lux-paycheck-insights" role="list">
        {insights.map((insight) => {
          const content = (
            <>
              <span className="lux-hrms-dash__alert-icon" aria-hidden="true"><i className={insight.icon} /></span>
              <span className="lux-paycheck-insight__copy">
                <strong>{insight.title}</strong>
                <small>{insight.copy}</small>
              </span>
              {insight.path && <i className="fe fe-chevron-right lux-paycheck-insight__chevron" aria-hidden="true" />}
            </>
          );
          return insight.path ? (
            <Link key={insight.id} to={insight.path} className={classNames("lux-hrms-dash__alert lux-paycheck-insight", `is-${insight.tone}`)} role="listitem">
              {content}
            </Link>
          ) : (
            <article key={insight.id} className={classNames("lux-hrms-dash__alert lux-paycheck-insight", `is-${insight.tone}`)} role="listitem">
              {content}
            </article>
          );
        })}
      </div>
    );
  };

  render() {
    if (!isPaychecksEnabled()) {
      return <PersonaAccessDenied moduleName="Paychecks" reason="Paycheck management is not enabled." />;
    }

    const { loading, loadError, dataSource, statusFilter, query, acting } = this.state;
    const rows = this.getFilteredPaychecks();
    const metrics = buildPaycheckAdminMetrics(this.state.paychecks);
    const kpiCards = [
      { id: "published", label: "Published", value: metrics.published, hint: "Visible to employees", tone: "green", icon: "fe fe-check-circle" },
      { id: "draft", label: "Draft", value: metrics.draft, hint: "Awaiting publish", tone: "amber", icon: "fe fe-file-text" },
      { id: "employees", label: "Employees", value: metrics.employees, hint: "With paycheck records", tone: "primary", icon: "fe fe-users" },
      { id: "net", label: "Net total", value: formatPayrollCurrency(metrics.netTotal), hint: `${metrics.total} paycheck(s)`, tone: "blue", icon: "fe fe-dollar-sign" },
    ];

    return (
      <PayrollLuxPage
        testId="page-payroll-paychecks"
        className="lux-paycheck-page"
        dataSource={dataSource}
        pageMeta={DENSE_PAGE_META.paychecks}
        loading={loading}
        kpiCards={kpiCards}
        heroActions={
          <>
            <PayrollActionButton to="/payroll/runs" icon="fe fe-layers" variant="ghost">
              Payroll runs
            </PayrollActionButton>
            <PayrollActionButton to="/workspace/my-paychecks" icon="fe fe-user" variant="primary">
              My paychecks
            </PayrollActionButton>
          </>
        }
      >
        {loadError && (
          <div className="lux-employee-360__error lux-paycheck__error" role="alert">
            <span>{loadError}</span>
            <PayrollActionButton variant="ghost" onClick={this.loadPaychecks}>Retry</PayrollActionButton>
          </div>
        )}
        {this.renderInsights()}
        <section className="lux-hrms-dash__panel lux-paycheck-panel">
          <PayrollPanelHead
            title="Paycheck register"
            subtitle="Publish payslips to employees or retract for corrections"
          />

          <div className="lux-paycheck-panel__toolbar">
            <div className="lux-appr-toolbar__row">
              <div className="lux-appr-toolbar__search">
                <i className="fe fe-search" aria-hidden="true" />
                <input
                  type="search"
                  className="lux-appr-toolbar__search-input"
                  placeholder="Search employees, periods, or runs"
                  value={query}
                  onChange={(e) => this.setState({ query: e.target.value })}
                />
              </div>
              <span className="lux-appr-toolbar__count">
                <strong>{rows.length}</strong> paycheck{rows.length === 1 ? "" : "s"}
              </span>
            </div>
            <div className="lux-appr-toolbar__group">
              <span className="lux-appr-toolbar__label">Status</span>
              <div className="lux-hrms-dash__filter-group">
                {["ALL", PAYCHECK_STATUSES.DRAFT, PAYCHECK_STATUSES.PUBLISHED, PAYCHECK_STATUSES.RETRACTED].map((value) => (
                  <button
                    key={value}
                    type="button"
                    className={classNames("lux-hrms-dash__filter-chip", { "is-active": statusFilter === value })}
                    onClick={() => this.setState({ statusFilter: value })}
                  >
                    {value === "ALL" ? "All" : value}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="lux-hrms-dash__panel-body">
            {loading ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" title="Loading paychecks" description="Fetching payslip register." />
            ) : rows.length === 0 ? (
              <LuxRegisterEmptyState className="lux-register-empty--compact" icon="fe fe-dollar-sign" title="No paychecks" description="Finalize a payroll run to generate employee paychecks." />
            ) : (
              <PaycheckRegister
                paychecks={rows}
                acting={acting}
                onPublish={this.handlePublish}
                onRetract={this.handleRetract}
              />
            )}
          </div>
        </section>
      </PayrollLuxPage>
    );
  }
}

export default PaychecksPage;
