import React from "react";
import classNames from "classnames/bind";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";

export default function PlannerViewHero({
  eyebrow,
  eyebrowVariant = "team-capacity",
  title,
  description,
  meta,
  actions,
  badge,
  children,
}) {
  return (
    <header className="lux-planner-hero">
      <div className="lux-planner-hero__main">
        {eyebrow && (
          <LuxSummaryEyebrow variant={eyebrowVariant} className="lux-planner-summary__eyebrow">
            {eyebrow}
          </LuxSummaryEyebrow>
        )}
        <div className="lux-planner-hero__title-row">
          <h2 className="lux-planner-hero__title">{title}</h2>
          {badge != null && (
            <span className={classNames("lux-planner-hero__badge", badge.tone && `is-${badge.tone}`)}>
              {badge.label}
            </span>
          )}
        </div>
        {description && <p className="lux-planner-hero__desc">{description}</p>}
        {meta && <p className="lux-planner-hero__meta">{meta}</p>}
      </div>
      {actions && <div className="lux-planner-hero__actions">{actions}</div>}
      {children && <div className="lux-planner-hero__extra">{children}</div>}
    </header>
  );
}
