import {
  MASKING_DOMAINS,
  MASKING_LEVELS,
  MASKING_PERSONAS,
  normalizeMaskingPolicyRule,
} from "config/masking-policy.config";

export function buildMaskingPolicyMetrics(rules) {
  const rows = (rules || []).map(normalizeMaskingPolicyRule).filter(Boolean);
  let hiddenCount = 0;
  let maskedCount = 0;
  let exportRestricted = 0;
  let highRisk = 0;

  rows.forEach((row) => {
    if (row.exportRestricted) {
      exportRestricted += 1;
    }
    if (row.risk === "high") {
      highRisk += 1;
    }
    Object.values(row.levels || {}).forEach((level) => {
      if (level === MASKING_LEVELS.HIDDEN) {
        hiddenCount += 1;
      }
      if (level === MASKING_LEVELS.MASKED) {
        maskedCount += 1;
      }
    });
  });

  const personaGrants = rows.length * MASKING_PERSONAS.length;
  const restrictedPct =
    personaGrants > 0 ? Math.round(((hiddenCount + maskedCount) / personaGrants) * 100) : 0;

  return {
    totalRules: rows.length,
    hiddenGrants: hiddenCount,
    maskedGrants: maskedCount,
    exportRestricted,
    highRiskRules: highRisk,
    restrictedPct,
  };
}

export function buildMaskingPolicyInsights(rules) {
  const rows = (rules || []).map(normalizeMaskingPolicyRule).filter(Boolean);
  const insights = [];

  const execVisible = rows.filter((row) => row.levels && row.levels.EXECUTIVE === MASKING_LEVELS.VISIBLE);
  if (execVisible.length > 0) {
    insights.push({
      id: "exec-visible",
      tone: "amber",
      icon: "fe fe-eye",
      title: `${execVisible.length} field(s) visible to executives`,
      copy: "Confirm aggregate-only visibility is intended for sensitive payroll data.",
    });
  }

  const employeeLeak = rows.filter(
    (row) => row.levels && row.levels.EMPLOYEE === MASKING_LEVELS.VISIBLE && row.risk === "high"
  );
  if (employeeLeak.length > 0) {
    insights.push({
      id: "employee-leak",
      tone: "rose",
      icon: "fe fe-alert-triangle",
      title: `${employeeLeak.length} high-risk field(s) visible to employees`,
      copy: "Tighten employee persona masking before production rollout.",
    });
  }

  const exportGaps = rows.filter((row) => !row.exportRestricted && row.risk === "high");
  if (exportGaps.length > 0) {
    insights.push({
      id: "export-gap",
      tone: "blue",
      icon: "fe fe-download",
      title: `${exportGaps.length} high-risk field(s) without export restriction`,
      copy: "Align CSV/PDF exports with screen masking via export controls.",
    });
  }

  if (insights.length === 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${rows.length} masking rules aligned`,
      copy: "Persona field policies match Tracopus pilot defaults.",
    });
  }

  return insights.slice(0, 3);
}

export function filterMaskingPolicyRules(rules, filters = {}) {
  const { domain = "ALL", level = "ALL", query = "" } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();

  return (rules || [])
    .map(normalizeMaskingPolicyRule)
    .filter(Boolean)
    .filter((row) => {
      if (domain !== "ALL" && row.domain !== domain) {
        return false;
      }
      if (level !== "ALL") {
        const hasLevel = Object.values(row.levels || {}).some((value) => value === level);
        if (!hasLevel) {
          return false;
        }
      }
      if (!normalizedQuery) {
        return true;
      }
      const haystack = [row.name, row.fieldKey, row.domain, row.description]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(normalizedQuery);
    });
}

export function getMaskingDomainMeta(domain) {
  return MASKING_DOMAINS[domain] || { label: domain, icon: "fe fe-circle", tone: "slate" };
}

export function countRestrictedPersonas(rule) {
  const profile = normalizeMaskingPolicyRule(rule);
  if (!profile) {
    return 0;
  }
  return Object.values(profile.levels || {}).filter(
    (level) => level === MASKING_LEVELS.MASKED || level === MASKING_LEVELS.HIDDEN
  ).length;
}

export function applyMaskingLevelUpdate(rule, persona, level) {
  const profile = normalizeMaskingPolicyRule(rule);
  if (!profile) {
    return null;
  }
  return {
    ...profile,
    levels: { ...profile.levels, [persona]: level },
    updatedAt: new Date().toISOString().slice(0, 10),
  };
}

export function buildMaskingLevelSeries(rules) {
  const rows = (rules || []).map(normalizeMaskingPolicyRule).filter(Boolean);
  const totals = {
    [MASKING_LEVELS.VISIBLE]: 0,
    [MASKING_LEVELS.MASKED]: 0,
    [MASKING_LEVELS.HIDDEN]: 0,
  };
  rows.forEach((row) => {
    Object.values(row.levels || {}).forEach((level) => {
      if (totals[level] != null) {
        totals[level] += 1;
      }
    });
  });
  return [
    { label: "Visible", value: totals[MASKING_LEVELS.VISIBLE], tone: "green" },
    { label: "Masked", value: totals[MASKING_LEVELS.MASKED], tone: "amber" },
    { label: "Hidden", value: totals[MASKING_LEVELS.HIDDEN], tone: "rose" },
  ];
}
