import React, { useEffect, useMemo, useState } from "react";
import classNames from "classnames/bind";
import {
  buildRolePermissionTree,
  countEnabledFlagsForRole,
  getPersonaMeta,
  getRoleCoverageStats,
} from "config/role-permission.utils";

function RolePermissionCard({ role, depth, hasChildren, expanded, selected, onSelect, onToggleExpand }) {
  const personaMeta = getPersonaMeta(role.persona);
  const coverage = getRoleCoverageStats(role);
  const enabledCount = countEnabledFlagsForRole(role);
  const isInactive = role.status === "Inactive";

  return (
    <div
      className={classNames("lux-rbac-role-tree__item", {
        "has-children": hasChildren,
        "is-expanded": expanded,
      })}
      style={{ "--rbac-role-depth": depth }}
    >
      <div
        className={classNames("lux-rbac-role-card-wrap", {
          "is-selected": selected,
          "is-inactive": isInactive,
          "is-branch": hasChildren,
        })}
      >
        {hasChildren ? (
          <button
            type="button"
            className={classNames("lux-rbac-role-card__branch-toggle", { "is-open": expanded })}
            aria-label={expanded ? "Collapse nested roles" : "Expand nested roles"}
            aria-expanded={expanded}
            onClick={(event) => onToggleExpand(event, role.id)}
          >
            <i className="fe fe-chevron-right" aria-hidden="true" />
          </button>
        ) : (
          <span className="lux-rbac-role-card__branch-spacer" aria-hidden="true" />
        )}

        <button
          type="button"
          role="listitem"
          className={classNames("lux-rbac-role-card", {
            "is-selected": selected,
            "is-inactive": isInactive,
          })}
          onClick={() => onSelect && onSelect(role)}
          aria-pressed={selected}
        >
        <span
          className={classNames(
            "lux-rbac-role-card__avatar",
            personaMeta.tone && `is-${personaMeta.tone}`
          )}
          aria-hidden="true"
        >
          <i className={personaMeta.icon} />
        </span>

        <span className="lux-rbac-role-card__body">
          <span className="lux-rbac-role-card__top">
            <strong className="lux-rbac-role-card__title">{role.name}</strong>
            <span
              className={classNames("lux-rbac-role-card__status", {
                "is-active": !isInactive,
                "is-inactive": isInactive,
              })}
            >
              {isInactive ? "Off" : "Live"}
            </span>
          </span>

          <span className="lux-rbac-role-card__sub">
            <em>{role.code}</em>
            <span
              className={classNames(
                "lux-rbac-role-card__persona",
                personaMeta.tone && `is-${personaMeta.tone}`
              )}
            >
              <i className={personaMeta.icon} aria-hidden="true" />
              {personaMeta.label}
            </span>
            <span className="lux-rbac-role-card__users">
              <i className="fe fe-users" aria-hidden="true" />
              {role.userCount || 0}
            </span>
            {hasChildren ? (
              <span className="lux-rbac-role-card__branch-count">
                {role.children.length} nested
              </span>
            ) : null}
          </span>

          <span className="lux-rbac-role-card__meter" aria-hidden="true">
            <span className="lux-rbac-role-card__meter-track">
              <span style={{ width: `${Math.max(coverage.coverage, 4)}%` }} />
            </span>
            <span className="lux-rbac-role-card__meter-label">
              {coverage.coverage}% · {enabledCount}/{coverage.total}
            </span>
          </span>
        </span>
        </button>
      </div>
    </div>
  );
}

function collectExpandableRoleIds(nodes, ids = []) {
  (nodes || []).forEach((node) => {
    if (node.isGroup) {
      ids.push(node.id);
      collectExpandableRoleIds(node.children, ids);
      return;
    }
    if (node.children && node.children.length > 0) {
      ids.push(String(node.id));
      collectExpandableRoleIds(node.children, ids);
    }
  });
  return ids;
}

export default function RolePermissionRegister({ roles, tree, selectedId, onSelect }) {
  const resolvedTree = useMemo(
    () => tree || buildRolePermissionTree(roles),
    [tree, roles]
  );
  const [expanded, setExpanded] = useState({});

  useEffect(() => {
    const next = {};
    collectExpandableRoleIds(resolvedTree).forEach((id) => {
      next[id] = true;
    });
    setExpanded(next);
  }, [resolvedTree]);

  const toggleExpanded = (event, id) => {
    event.preventDefault();
    event.stopPropagation();
    const key = String(id);
    setExpanded((prev) => ({
      ...prev,
      [key]: !prev[key],
    }));
  };

  const renderNode = (node, depth = 0) => {
    if (node.isGroup) {
      const groupExpanded = expanded[node.id] !== false;
      return (
        <div key={node.id} className="lux-rbac-role-tree__group">
          <button
            type="button"
            className={classNames("lux-rbac-role-tree__group-header", {
              "is-open": groupExpanded,
            })}
            onClick={() =>
              setExpanded((prev) => ({
                ...prev,
                [node.id]: !groupExpanded,
              }))
            }
            aria-expanded={groupExpanded}
          >
            <i className="fe fe-chevron-right" aria-hidden="true" />
            <span>{node.name}</span>
            <em>{node.children.length}</em>
          </button>
          {groupExpanded ? (
            <div className="lux-rbac-role-tree__group-body">
              {node.children.map((child) => renderNode(child, depth))}
            </div>
          ) : null}
        </div>
      );
    }

    const children = node.children || [];
    const hasChildren = children.length > 0;
    const nodeExpanded = expanded[String(node.id)] !== false;

    return (
      <div key={node.id} className="lux-rbac-role-tree__branch">
        <RolePermissionCard
          role={node}
          depth={depth}
          hasChildren={hasChildren}
          expanded={nodeExpanded}
          selected={selectedId === node.id}
          onSelect={onSelect}
          onToggleExpand={toggleExpanded}
        />
        {hasChildren && nodeExpanded ? (
          <div className="lux-rbac-role-tree__children">
            {children.map((child) => renderNode(child, depth + 1))}
          </div>
        ) : null}
      </div>
    );
  };

  return (
    <div className="lux-rbac-role-list lux-rbac-role-tree" role="list" aria-label="Role profiles">
      {resolvedTree.map((node) => renderNode(node, 0))}
    </div>
  );
}
