import React, { Component } from "react";
import { userActions } from '_actions';
import { connect } from 'react-redux';
import PropTypes from "prop-types";
import { store } from '_helpers';
import { validationUtils } from "_helpers";
import { Link, NavLink } from "react-router-dom";
import LoginPageFooter from "./LoginPageFooter";
import AuthPageShell from "./components/AuthPageShell";
import AuthLoginCard from "./components/AuthLoginCard";
class ChangePassword extends Component {
  constructor() {
    super();
    this.state = {
      passwordType: 'password',
      submitted: false,
      email: "",
      password: "",
      confirmPassword: "",
      invalidEmail: false,
      errors: {
        email: "",
        password: "",
        confirmPassword: "",
      }
    };
  }

  componentDidMount() {
    let activationKey = this.props.match.params.activationKey;
    let employeeId = this.props.match.params.employeeId;
    let uniqueId = this.props.match.params.uniqueId;
    store.dispatch(this.props.validateAccountActivation(uniqueId, employeeId, activationKey));
    //let urlViewName = this.getViewByName(new URLSearchParams(this.props.location.search).get("view"));
    this.setState({
      activateAccount: this.props.routeProp.path.substring(1).startsWith("activateaccount")
    });
  }


  togglePasswordType = () => {
    this.setState({
      passwordType: this.state.passwordType === 'text' ? 'password' : 'text'
    })
  }
  onSubmit = (e) => {
    e.preventDefault();
    this.setState({ invalidEmail: false });
    this.setState({ submitted: true });
    if (this.state.email && validationUtils.validateEmail(this.state.email)) {
      store.dispatch(this.props.changePassword(
        {
          "email": this.state.email,
          "password": this.state.password,
          "identifier": this.props.match.params.uniqueId,
          "employeeId": this.props.match.params.employeeId,
          "activationKey": this.props.match.params.activationKey
        }));
    } else {
      this.setState({ invalidEmail: true });
    }
  }

  onChange = (e) => {
    this.setState({ submitted: false });
    const { name, value } = e.target;
    this.setState({ [name]: value });
  }
  render() {
    const isActivate = this.state.activateAccount;
    const { authentication } = this.props;

    return (
      <AuthPageShell>
        <AuthLoginCard
          eyebrow={isActivate ? "Account setup" : "Password reset"}
          title={isActivate ? "Activate your account" : "Set a new password"}
          subtitle={
            authentication.validKey && !authentication.changePasswordSuccess
              ? `Enter your email and a new password to ${isActivate ? "activate your account" : "complete your reset"}.`
              : null
          }
          footer={
            !authentication.changePasswordSuccess ? (
              <p className="auth-login__foot-text">
                <NavLink
                  to="/user/login"
                  className="auth-login__link"
                  data-ga-action="change_password_back"
                  data-ga-category="auth"
                  data-ga-label="Send me Back"
                >
                  Back to sign in
                </NavLink>
              </p>
            ) : null
          }
        >
          {authentication.changePasswordSuccess && (
            <div className="auth-login__success" role="status">
              <i className="fe fe-check-circle" aria-hidden="true" />
              <p>
                Your account has been activated. Please{" "}
                <Link
                  to="/user/login"
                  className="auth-login__link"
                  data-ga-action="change_password_sign_in"
                  data-ga-category="auth"
                  data-ga-label="Sign In after activation"
                >
                  sign in
                </Link>{" "}
                again.
              </p>
            </div>
          )}
          {!authentication.validKey && !authentication.changePasswordSuccess && (
            <div className="auth-login__alert alert alert-danger" role="alert">
              Invalid activation key.{" "}
              <Link
                to="/user/forgotpassword"
                className="auth-login__link"
                data-ga-action="request_new_activation_key"
                data-ga-category="auth"
                data-ga-label="Request new activation key"
              >
                Request a new link
              </Link>
            </div>
          )}
          {authentication.validKey && !authentication.changePasswordSuccess && (
            <>
              <div className="form-group">
                <label className="form-label" htmlFor="changeEmail">Email</label>
                <div className="passwordinputcontainer auth-login__field">
                  <span className="input-icon-addon"><i className="fe fe-mail" aria-hidden="true" /></span>
                  <input
                    type="email"
                    className="form-control passwordinput"
                    id="changeEmail"
                    placeholder="you@company.com"
                    name="email"
                    value={this.state.email}
                    onChange={this.onChange}
                    autoComplete="email"
                  />
                </div>
                {this.state.submitted && !this.state.email && (
                  <div className="invalid-feedback">Email is required</div>
                )}
              </div>
              <div className="form-group">
                <label className="form-label" htmlFor="changePassword">New password</label>
                <div className="passwordinputcontainer auth-login__field">
                  <span className="input-icon-addon"><i className="fe fe-lock" aria-hidden="true" /></span>
                  <input
                    type={this.state.passwordType}
                    className="form-control passwordinput"
                    id="changePassword"
                    placeholder="Create a strong password"
                    name="password"
                    value={this.state.password}
                    onChange={this.onChange}
                    autoComplete="new-password"
                  />
                  <button
                    type="button"
                    className="passwordshoweye"
                    onClick={this.togglePasswordType}
                    aria-label={this.state.passwordType === "text" ? "Hide password" : "Show password"}
                  >
                    <i className={`fe ${this.state.passwordType === "text" ? "fe-eye-off" : "fe-eye"}`} aria-hidden="true" />
                  </button>
                </div>
                {this.state.submitted && !this.state.password && (
                  <div className="invalid-feedback">Password is required</div>
                )}
              </div>
              <div className="form-footer auth-login__actions">
                <button
                  type="button"
                  className="btn btn-primary btn-block auth-login__submit"
                  onClick={this.onSubmit}
                  data-ga-action={isActivate ? "activate_account_submit" : "change_password_submit"}
                  data-ga-category="auth"
                  data-ga-label={isActivate ? "Activate Account" : "Change Password"}
                >
                  {authentication.changePassword && (
                    <span className="spinner-border spinner-border-sm mr-1" aria-hidden="true" />
                  )}
                  {isActivate ? "Activate account" : "Update password"}
                </button>
              </div>
            </>
          )}
        </AuthLoginCard>
        <LoginPageFooter />
      </AuthPageShell>
    );
  }
}

ChangePassword.propTypes = {
  changePassword: PropTypes.func.isRequired,
  authentication: PropTypes.object.isRequired
};

const mapStateToProps = state => ({
  authentication: state.authentication
});

const mapDispatchToProps = dispatch => ({
  validateAccountActivation: userActions.validateAccountActivation,
  changePassword: userActions.changePassword
});

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(ChangePassword);
