import React from "react";
import classNames from "classnames/bind";
import { LessonStatusBadge } from "views/knowledge/components/KnowledgeLuxShared";

const CATEGORY_ICONS = {
  delivery: "fe fe-layers",
  process: "fe fe-git-branch",
  technical: "fe fe-code",
  communication: "fe fe-message-square",
  risk: "fe fe-alert-triangle",
};

export default function LessonRegister({ lessons, loading, selectedId, onSelect, onPublish }) {
  if (loading) {
    return (
      <div className="lux-krca-register lux-krca-register--loading">
        {[1, 2, 3].map((key) => (
          <div key={key} className="lux-krca-skeleton lux-krca-skeleton--row" />
        ))}
      </div>
    );
  }

  const rows = lessons || [];
  if (!rows.length) {
    return (
      <div className="lux-krca-empty">
        <i className="fe fe-book-open" aria-hidden="true" />
        <p>No lessons captured yet.</p>
      </div>
    );
  }

  return (
    <div className="lux-krca-register">
      {rows.map((row, index) => (
        <article
          key={row.id}
          className={classNames("lux-krca-register__row", row.tone && `is-${row.tone}`, selectedId === row.id && "is-selected")}
        >
          <span className="lux-krca-register__index" aria-hidden="true">
            {String(index + 1).padStart(2, "0")}
          </span>
          <span className="lux-krca-register__rail" aria-hidden="true">
            <i className={CATEGORY_ICONS[row.category] || "fe fe-book-open"} />
          </span>
          <button type="button" className="lux-krca-register__main" onClick={() => onSelect && onSelect(row)}>
            <span className="lux-krca-register__eyebrow">{row.projectName} · {row.category}</span>
            <h3>{row.title}</h3>
            <p>{row.summary}</p>
            <div className="lux-krca-register__meta">
              <LessonStatusBadge status={row.status} />
              <span>{row.authorName}</span>
              {row.ticketNumber ? <span>{row.ticketNumber}</span> : null}
              <span>{row.reuseCount} reuses</span>
            </div>
          </button>
          {row.status === "draft" && onPublish ? (
            <button type="button" className="lux-onb-action lux-onb-action--primary lux-krca-action" onClick={() => onPublish(row)}>
              Publish
            </button>
          ) : null}
        </article>
      ))}
    </div>
  );
}
